const e=JSON.parse(`[{"n":1,"name":"Foundation","tagline":"Learn every move with light weights. Get your glutes working and your hips opening.","info":[["Strength","3 sets unless noted"],["Stretch holds","30-60 sec, 2 rounds. No contract-relax yet (Saturday only, once you're in month 2)."],["Goals","Sit cross-legged comfortably. Reach your toes or shins in a fold."],["Move to next plan","When this whole week feels easy."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"3 sets unless noted","items":[{"name":"Glute bridge (dumbbell on hips)","sets":"3 x 15","steps":["Lie on your back, knees bent, feet flat, heels about a hand's length from your bum.","Lay a dumbbell across your hip bones (towel underneath) and hold both ends.","Tuck your ribs down, push through your heels and squeeze your bum to lift your hips until straight.","Squeeze 2 sec at the top, lower slowly."],"feel":"bum, not lower back","dont":"arch your back at the top"},{"name":"Goblet squat to chair","sets":"3 x 12","steps":["Stand in front of a chair, feet shoulder-width, toes slightly out.","Hold one dumbbell vertically at your chest with both hands cupping the top end (goblet hold), elbows down.","Sit back and down slowly (3 sec) until your bum lightly touches the chair.","Push through your whole foot to stand tall, squeezing your bum."],"feel":"thighs and bum","dont":"let your knees cave in or heels lift"},{"name":"Dumbbell Romanian deadlift","sets":"3 x 12","steps":["Stand tall holding a dumbbell in each hand in front of your thighs, feet hip-width, knees soft.","Push your hips back like closing a car door with your bum, sliding the dumbbells down the front of your legs. Back flat.","Go until you feel a strong stretch in the back of your thighs.","Squeeze your bum and push your hips forward to stand."],"feel":"back of thighs and bum","dont":"round your back or bend your knees into a squat"},{"name":"Donkey kick","sets":"3 x 12/side","steps":["Get on hands and knees: hands under shoulders, knees under hips.","Keeping the knee bent at 90 degrees, push one foot up toward the ceiling (sole facing up).","Lift until your thigh is in line with your body, squeeze your bum, then lower.","All reps one side, then switch."],"feel":"bum of the kicking leg","dont":"arch your lower back or twist your hips"},{"name":"Fire hydrant","sets":"3 x 12/side","steps":["Get on hands and knees: hands under shoulders, knees under hips.","Keeping the knee bent at 90 degrees, lift one leg out to the side (like a dog at a fire hydrant).","Lift as high as you can without tipping your body, then lower slowly.","All reps one side, then switch."],"feel":"side of your bum/outer hip","dont":"lean your body away to cheat the height"},{"name":"Side-lying leg raise","sets":"3 x 15/side","steps":["Lie on your side, bottom knee bent for balance, top leg straight. Head on your arm.","Turn your top toes slightly toward the floor and keep the leg a little behind your body line.","Lift the top leg up (about 45 degrees), lead with the heel, then lower slowly.","All reps one side, then roll over."],"feel":"side of your bum, not the front of your hip","dont":"roll backward or swing the leg"}],"notes":[]},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"15 min","items":[{"name":"90/90 hip switches","hold":"8 slow reps","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null},{"name":"Figure-4 (on back)","hold":"45 sec/side","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null},{"name":"Pigeon pose","hold":"45 sec/side","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Low lunge","hold":"45 sec/side","steps":["Step one foot forward into a lunge, put the back knee down on a cushion.","Torso tall, squeeze the bum of the back leg and gently push your hips forward.","Hold, then switch."],"feel":"front of the back hip","dont":null},{"name":"Deep squat hold","hold":"30 sec","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null}],"notes":[]}]},{"dow":"Tuesday","title":"Row","flow":"Row → Stretch","sections":[{"kind":"row","title":"CONCEPT2 ROW: STEADY","meta":"","intro":["Warm up 3-5 min of light rowing."],"table":[["Start","15 min"],["When that's easy","20 min"],["Easy week","12 min (15 min once you're on 20)"]],"notes":["Effort: Easy. 18-22 strokes/min, damper 3-5. You can talk in full sentences."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"20 min","items":[{"name":"Standing forward fold","hold":"45 sec","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null},{"name":"Heel-on-couch hamstring stretch","hold":"45 sec/side","steps":["Stand facing a couch or stair. Put one heel on it, leg straight, toes up.","Hips facing forward, back flat.","Hinge forward from your hips (not by rounding your back) until you feel a stretch. Hold, then switch."],"feel":"back of the raised thigh","dont":null},{"name":"Half split (runner's stretch)","hold":"45 sec/side","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side of the front leg. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Kneeling quad stretch","hold":"45 sec/side","steps":["Kneel in a low lunge (back knee on a cushion), near a couch or wall.","Reach back and grab your back foot (or rest it on the couch behind you).","Pull the foot toward your bum and squeeze the bum on that side. Hold, then switch."],"feel":"front of the back thigh","dont":null},{"name":"Supported front split","hold":"30 sec/side","steps":["Start in a half split. Put books or pillows under your hands on either side, and a pillow under your front hamstring/hips if needed.","Slowly slide your front heel forward and back knee back, lowering your hips.","Stop at mild tension and rest on the supports. Hips face forward. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Active leg raise","hold":"6 x 3 sec/side","steps":["Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + core","flow":"Warm-up → Upper + core → Stretch","sections":[{"kind":"strength","title":"UPPER + CORE","meta":"3 rounds (do 1-6 in a row = 1 round)","items":[{"name":"Counter push-up","sets":"10","steps":["Put your hands on a kitchen bench, a bit wider than shoulders.","Walk your feet back until your body is a straight line from head to heels.","Bend your elbows (angled back, not flared out) to lower your chest to the bench.","Push back up. Keep your body straight the whole time."],"feel":"chest, arms","dont":"let your hips sag"},{"name":"One-arm dumbbell row","sets":"10/side","steps":["Put one hand and the same-side knee on the couch (or just a hand on a chair, feet staggered). Back flat.","Hold a dumbbell in the other hand, arm hanging straight down.","Pull the dumbbell up toward your hip, elbow close to your side, squeezing your shoulder blade back.","Lower slowly. All reps one side, then switch."],"feel":"upper/middle back (posture muscles)","dont":"twist your body or shrug"},{"name":"Prone Y-T-W raises","sets":"8 each","steps":["Lie face down, forehead on a folded towel.","Y: arms overhead in a Y shape, thumbs up. Lift arms off the floor, squeezing shoulder blades, lower. Do 8.","T: arms straight out to the sides. Lift, squeeze, lower. Do 8.","W: bend elbows, hands near shoulders like a W. Lift, squeeze shoulder blades together, lower. Do 8."],"feel":"upper back, between shoulder blades","dont":"shrug your shoulders up to your ears"},{"name":"Dead bug","sets":"8/side","steps":["Lie on your back, arms pointing at the ceiling, knees bent at 90 degrees above your hips (like a tabletop).","Press your lower back into the floor.","Slowly lower your right arm overhead and straighten your left leg toward the floor at the same time.","Bring them back, switch sides. Each side = 1 rep."],"feel":"deep abs","dont":"let your lower back arch off the floor"},{"name":"Knee plank","sets":"30 sec","steps":["On forearms and knees, elbows under shoulders.","Walk your knees back so your body is straight from knees to head.","Squeeze your bum and abs and hold."],"feel":"abs","dont":"stick your bum up"},{"name":"Knee side plank","sets":"15 sec/side","steps":["Lie on your side, elbow under shoulder, knees bent behind you.","Lift your hips so your body is straight from knees to head.","Hold, then switch sides."],"feel":"side of waist","dont":"let hips drop"}],"notes":["Upper body stays light on purpose: posture and a tight waist, no bulk. Use light dumbbells for rows."]},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"15 min","items":[{"name":"Cat-cow","hold":"10 reps","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null},{"name":"Thread-the-needle","hold":"30 sec/side","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Sphinx or cobra","hold":"30 sec","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null},{"name":"Doorway chest opener","hold":"30 sec/side","steps":["Stand in a doorway. Put your forearm on the frame, elbow at shoulder height.","Step forward with the same-side foot until you feel a stretch across your chest.","Hold, then switch."],"feel":"chest and front of shoulder","dont":null},{"name":"Puppy pose","hold":"45 sec","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null},{"name":"Bridge prep","hold":"3 x 5 sec","steps":["Lie on your back, knees bent, feet flat near your bum.","Put your hands on the floor beside your ears, fingers pointing toward your shoulders.","Push through hands and feet to lift your hips and head off the floor (full bridge). Or just the top of your head down if that's as far as you get.","Hold for the time, lower gently."],"feel":"shoulders, front of body opening","dont":null},{"name":"Supine twist","hold":"45 sec/side","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"3 sets unless noted","items":[{"name":"Dumbbell step-up","sets":"3 x 10/side","steps":["Hold a dumbbell in each hand by your sides. Stand facing a sturdy stair or step.","Put your whole right foot on the step.","Push through the right heel to step up until the leg is straight, bring the left foot up.","Step down with the left foot slowly. All reps on the right, then switch."],"feel":"thigh and bum of the leg on the step","dont":"push off the bottom foot"},{"name":"Dumbbell reverse lunge (hand on wall)","sets":"3 x 8/side","steps":["Hold one dumbbell in the hand away from the wall, other hand on the wall.","Step back with the leg on the dumbbell side and lower until the back knee nearly touches the floor.","Push through the front heel to stand. All reps one side, then turn around and switch."],"feel":"front thigh and bum","dont":"let the front knee cave in"},{"name":"Goblet sumo squat","sets":"3 x 12","steps":["Feet much wider than shoulders, toes turned out about 45 degrees.","Hold one dumbbell vertically by the top end, hanging between your legs (or at your chest).","Sit straight down, knees pushed out over your toes, chest up. Go as low as you can.","Push through your heels to stand."],"feel":"inner thighs and bum","dont":"let your knees fall inward"},{"name":"Standing side leg lift","sets":"3 x 12/side","steps":["Stand tall, holding a chair or wall with one hand.","Keep your outside leg straight and toes pointing forward.","Lift that leg out to the side as high as you can without leaning, then lower slowly.","All reps one side, then switch."],"feel":"side of your hip/bum","dont":"lean your body sideways or turn your toes up"},{"name":"Wall sit","sets":"3 x 30 sec","steps":["Stand with your back flat against a wall.","Walk your feet out about 2 foot-lengths and slide down until your thighs are parallel to the floor (knees at 90 degrees).","Knees above ankles, back flat on the wall, arms crossed or by your sides. Hold for the time."],"feel":"front of thighs burning","dont":"put your hands on your thighs"},{"name":"Dumbbell calf raise","sets":"3 x 15","steps":["Dumbbell in each hand (or one hand, other on a wall). Stand on the edge of a stair if you can, heels hanging off.","Rise up onto your toes as high as you can.","Lower slowly, heels dropping below the step."],"feel":"calves","dont":"bounce"}],"notes":[]},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"15-20 min","items":[{"name":"Butterfly","hold":"60 sec","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"45 sec","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Wall straddle","hold":"1 min","steps":["Lie on your back with your bum close to a wall, legs straight up the wall.","Let your legs slowly slide apart into a V.","Relax and let gravity open them wider. Hold."],"feel":"inner thighs","dont":null},{"name":"Seated straddle (wide-leg fold)","hold":"60 sec","steps":["Sit with legs straight and wide apart, toes up.","Sit tall (sit on a cushion if your back rounds).","Walk your hands forward and hinge from your hips, keeping your back flat. Hold."],"feel":"inner thighs, back of thighs","dont":null},{"name":"Cossack squat hold","hold":"5 sec x 8/side","steps":["Stand with feet very wide.","Sit down into one side (bent knee), other leg straight with toes up.","Hold the low position for the time, then switch sides. Hold a chair if needed."],"feel":"inner thigh of the straight leg","dont":null}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"3 sets unless noted","items":[{"name":"Bridge march","sets":"3 x 10/side","steps":["Get into the top of a glute bridge (hips up, straight line knees to shoulders).","Keeping your hips level and up, lift one foot a few cm off the floor, knee bent.","Put it down, lift the other. That's 1 rep each side."],"feel":"bum of the standing leg working hard","dont":"let your hips drop or tilt to one side"},{"name":"Dumbbell frog pump","sets":"3 x 20","steps":["On your back, soles together, knees out wide, heels near your bum.","Lay a dumbbell across your hips (towel underneath) and hold both ends.","Squeeze your bum to lift your hips, lower, repeat."],"feel":"bum, especially the sides","dont":"arch your lower back"},{"name":"Curtsy lunge (hold support)","sets":"3 x 8/side","steps":["Stand next to a chair or wall and hold it lightly.","Step one leg back and across behind the other (like a curtsy), so it lands diagonally behind.","Bend both knees and lower until the back knee is close to the floor. Keep the front knee over the toes and hips facing forward.","Push through the front heel to stand. All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"twist your hips sideways"},{"name":"Prone hip extension","sets":"3 x 12/side","steps":["Lie face down, forehead on your hands, legs straight.","Squeeze your bum and lift one straight leg a few cm off the floor.","Lower slowly. All reps one side, then switch."],"feel":"bum","dont":"lift by arching your lower back; small lift is fine"},{"name":"Bird-dog","sets":"3 x 8/side","steps":["Get on hands and knees: hands under shoulders, knees under hips, back flat.","Reach your right arm forward and your left leg straight back at the same time, both level with your body.","Hold 1 sec, bring them back, then switch sides. Each side = 1 rep."],"feel":"lower back muscles, bum and core","dont":"let your hips tip or your back sag"},{"name":"Single-leg balance","sets":"3 x 20 sec/side","steps":["Stand on one foot, slight bend in the knee, the other foot lifted.","Stand tall, hands on hips, eyes on a spot in front of you.","Hold for the time. Then switch."],"feel":"ankle, outer hip","dont":"lock your knee"}],"notes":[]},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"20 min","items":[{"name":"Half split","hold":"45 sec/side","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Supported front split","hold":"30 sec/side","steps":["Start in a half split. Put books or pillows under your hands on either side, and a pillow under your front hamstring/hips if needed.","Slowly slide your front heel forward and back knee back, lowering your hips.","Stop at mild tension and rest on the supports. Hips face forward. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Supported middle split","hold":"30 sec","steps":["Stand or kneel with legs wide apart, hands on the floor or books in front of you.","Slowly slide your feet out to the sides, lowering your hips.","Stop at mild tension and rest your weight on your hands/supports. Hold."],"feel":"inner thighs","dont":null},{"name":"Seated forward fold","hold":"60 sec","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null},{"name":"Lying figure-4 contract-relax","hold":"Not yet (starts Plan 2)","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null}],"notes":[]}]},{"dow":"Saturday","title":"Row + test day","flow":"Row → Full-body flow → Test","sections":[{"kind":"row","title":"CONCEPT2 ROW: STEADY","meta":"","intro":["Warm up 3-5 min of light rowing."],"table":[["Steady row","Same time as your Tuesday row"]],"notes":["Effort: Easy, steady. Same as Tuesday."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"30 min","items":[{"name":"Pigeon pose (each side)","hold":"45 sec","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Half split (each side)","hold":"45 sec","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Seated straddle fold","hold":"45 sec","steps":["Sit with legs straight and wide apart, toes up.","Sit tall (on a cushion if needed).","Walk your hands forward, hinge from your hips, back flat. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"45 sec","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Thread-the-needle (each side)","hold":"45 sec","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Deep squat hold","hold":"45 sec","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null},{"name":"Bridge prep","hold":"45 sec","steps":["Lie on your back, knees bent, feet flat near your bum.","Put your hands on the floor beside your ears, fingers pointing toward your shoulders.","Push through hands and feet to lift your hips and head off the floor (full bridge). Or just the top of your head down if that's as far as you get.","Hold for the time, lower gently."],"feel":"shoulders, front of body opening","dont":null}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm or pillows)","Middle split: hips from floor (cm or pillows)","Deep squat hold time","Bridge hold time","Barbell hip thrust: best weight x reps this week"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","hold":"2 min","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null},{"name":"Supine twist","hold":"1 min/side","steps":["On back, knees bent, let both knees fall to one side, shoulders stay down."],"feel":null,"dont":null},{"name":"Legs up the wall","hold":"5 min","steps":["Lie with bum near a wall and legs straight up it. Arms relaxed."],"feel":null,"dont":null},{"name":"Slow breathing","hold":"2 min","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null}],"notes":[]}]}]},{"n":2,"name":"Build","tagline":"Barbell hip thrusts and deadlifts come in. Heavier dumbbells, more single-leg work.","info":[["Strength","4 sets unless noted"],["Stretch holds","60-90 sec, 2-3 rounds. Start contract-relax on hips and hamstrings (see stretching rules)."],["Goals","Straddle fold with a flat back. Half split with hands on the floor. Bridge prep for 10 sec."],["Move to next plan","When this whole week feels easy."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"4 sets unless noted","items":[{"name":"Barbell hip thrust (shoulders on couch)","sets":"4 x 12","steps":["Sit on the floor, upper back (bottom of shoulder blades) against the couch edge, legs straight. Wrap a folded towel or yoga mat around the middle of the bar so it doesn't dig into your hips.","Roll the loaded bar over your legs until it sits in the crease of your hips. Hold it with both hands just outside your hips.","Bend your knees, feet flat and hip-width, so your shins will be vertical at the top. Tuck your chin.","Drive through your heels and push the bar up until your body is a flat tabletop from knees to shoulders. Squeeze your bum hard, then lower slowly."],"feel":"bum, big squeeze at the top","dont":"arch your lower back or throw your head back; ribs stay down"},{"name":"Goblet squat, 3 sec down","sets":"4 x 10","steps":["Goblet hold: one dumbbell vertical at your chest, elbows down. Feet shoulder-width, toes slightly out.","Lower counting 3 slow seconds, knees out, as deep as you can with heels down and chest up.","Stand up and squeeze your bum at the top."],"feel":"thighs and bum","dont":"let your chest drop or knees cave in"},{"name":"Dumbbell curtsy lunge","sets":"3 x 10/side","steps":["Hold one dumbbell at your chest (goblet hold).","Step one leg back and across behind the other, landing diagonally.","Lower until the back knee is near the floor, hips facing forward. Push through the front heel to stand.","All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"twist your hips"},{"name":"Single-leg glute bridge","sets":"3 x 10/side","steps":["Lie on your back, knees bent, feet flat.","Lift one foot off the floor and hold that knee up toward your chest (or keep that leg straight in line with the other thigh).","Push through the heel of the foot on the floor and lift your hips until straight.","Squeeze 1-2 sec at the top, lower slowly. Do all reps, then switch legs."],"feel":"bum of the working leg","dont":"let the hips tilt; keep both hip bones level"},{"name":"Fire hydrant with 3 pulses","sets":"3 x 12/side","steps":["Do a fire hydrant: on hands and knees, lift one bent leg out to the side.","At the top, do 3 small pulses up (a few cm each).","Lower. That's 1 rep. All reps one side, then switch."],"feel":"side of your bum burning","dont":"lean your body away"},{"name":"Side-lying leg raise with pulse","sets":"3 x 15/side","steps":["Set up like a side-lying leg raise.","Lift the top leg up, do 1 small pulse at the top, then lower slowly.","All reps one side, then roll over."],"feel":"side of your bum burning","dont":"roll backward"}],"notes":[]},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"15 min","items":[{"name":"90/90 hip switches","hold":"10 reps","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null},{"name":"Figure-4 (on back)","hold":"60-75 sec/side","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null},{"name":"Pigeon pose","hold":"60-90 sec/side","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Low lunge","hold":"60 sec/side","steps":["Step one foot forward into a lunge, put the back knee down on a cushion.","Torso tall, squeeze the bum of the back leg and gently push your hips forward.","Hold, then switch."],"feel":"front of the back hip","dont":null},{"name":"Deep squat hold","hold":"60 sec","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null}],"notes":[]}]},{"dow":"Tuesday","title":"Row","flow":"Row → Stretch","sections":[{"kind":"row","title":"CONCEPT2 ROW: STEADY","meta":"","intro":["Warm up 5 min of light rowing."],"table":[["Start","25 min"],["When that's easy","30 min"],["Easy week","18 min (22 min once you're on 30)"]],"notes":["Effort: Moderate. 20-22 strokes/min, damper 3-5. You can say short sentences."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"20 min","items":[{"name":"Standing forward fold","hold":"60 sec","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null},{"name":"Heel-on-couch hamstring stretch","hold":"60-90 sec/side","steps":["Stand facing a couch or stair. Put one heel on it, leg straight, toes up.","Hips facing forward, back flat.","Hinge forward from your hips (not by rounding your back) until you feel a stretch. Hold, then switch."],"feel":"back of the raised thigh","dont":null},{"name":"Half split (runner's stretch)","hold":"60-90 sec/side","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side of the front leg. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Kneeling quad stretch","hold":"60 sec/side","steps":["Kneel in a low lunge (back knee on a cushion), near a couch or wall.","Reach back and grab your back foot (or rest it on the couch behind you).","Pull the foot toward your bum and squeeze the bum on that side. Hold, then switch."],"feel":"front of the back thigh","dont":null},{"name":"Supported front split","hold":"60 sec/side","steps":["Start in a half split. Put books or pillows under your hands on either side, and a pillow under your front hamstring/hips if needed.","Slowly slide your front heel forward and back knee back, lowering your hips.","Stop at mild tension and rest on the supports. Hips face forward. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Active leg raise","hold":"8 x 5 sec/side","steps":["Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + core","flow":"Warm-up → Upper + core → Stretch","sections":[{"kind":"strength","title":"UPPER + CORE","meta":"3-4 rounds (do 1-6 in a row = 1 round)","items":[{"name":"Incline push-up (hands on couch)","sets":"10","steps":["Hands on the couch seat (or a sturdy low table), a bit wider than shoulders.","Walk your feet back until your body is straight from head to heels.","Lower your chest to the edge, elbows angled back, then push back up."],"feel":"chest, arms","dont":"let your hips sag"},{"name":"One-arm dumbbell row","sets":"12/side","steps":["Put one hand and the same-side knee on the couch (or just a hand on a chair, feet staggered). Back flat.","Hold a dumbbell in the other hand, arm hanging straight down.","Pull the dumbbell up toward your hip, elbow close to your side, squeezing your shoulder blade back.","Lower slowly. All reps one side, then switch."],"feel":"upper/middle back (posture muscles)","dont":"twist your body or shrug"},{"name":"Reverse snow angel","sets":"10","steps":["Lie face down, forehead on a folded towel, arms by your sides, palms down.","Lift your arms a few cm off the floor and squeeze your shoulder blades together.","Keeping arms off the floor and straight, sweep them out to the sides and up overhead (like a snow angel).","Sweep them back down to your sides. That's 1 rep."],"feel":"upper back, back of shoulders (great for posture, doesn't bulk)","dont":"shrug your shoulders up"},{"name":"Dead bug with dumbbell","sets":"8/side","steps":["Lie on your back, hold one light dumbbell above your chest with both hands, knees bent at 90 degrees above your hips.","Press your lower back into the floor.","Slowly straighten one leg toward the floor while the dumbbell stays still above you.","Bring it back, switch legs. Each leg = 1 rep."],"feel":"deep abs","dont":"let your lower back arch"},{"name":"Forearm plank","sets":"45 sec","steps":["On forearms and toes, elbows under shoulders.","Body in a straight line from head to heels.","Squeeze your bum and abs and hold."],"feel":"abs","dont":"let your hips sag"},{"name":"Side plank","sets":"20 sec/side","steps":["Lie on your side, elbow under shoulder, legs straight and stacked (or top foot in front).","Lift your hips so your body is straight from feet to head.","Hold, then switch sides."],"feel":"side of waist","dont":"let hips drop"}],"notes":["Upper body stays light on purpose: posture and a tight waist, no bulk. Use light dumbbells for rows."]},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"15 min","items":[{"name":"Cat-cow","hold":"12 reps","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null},{"name":"Thread-the-needle","hold":"45 sec/side","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Sphinx or cobra","hold":"45 sec","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null},{"name":"Doorway chest opener","hold":"45 sec/side","steps":["Stand in a doorway. Put your forearm on the frame, elbow at shoulder height.","Step forward with the same-side foot until you feel a stretch across your chest.","Hold, then switch."],"feel":"chest and front of shoulder","dont":null},{"name":"Puppy pose","hold":"60 sec","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null},{"name":"Bridge prep","hold":"3 x 10 sec","steps":["Lie on your back, knees bent, feet flat near your bum.","Put your hands on the floor beside your ears, fingers pointing toward your shoulders.","Push through hands and feet to lift your hips and head off the floor (full bridge). Or just the top of your head down if that's as far as you get.","Hold for the time, lower gently."],"feel":"shoulders, front of body opening","dont":null},{"name":"Supine twist","hold":"60 sec/side","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"4 sets unless noted","items":[{"name":"Dumbbell Bulgarian split squat","sets":"4 x 10/side","steps":["Dumbbell in each hand by your sides. Stand a big stride in front of the couch, top of one foot on the couch behind you.","Lower straight down until the back knee nearly touches the floor. Front heel stays down, lean forward slightly.","Push through the front heel to stand. All reps one side, then switch."],"feel":"front thigh and bum","dont":"let the front heel lift (move your foot further out if it does)"},{"name":"Dumbbell walking lunge","sets":"3 x 10/side","steps":["Dumbbell in each hand, arms by your sides.","Long step forward, lower until back knee nearly touches the floor.","Push through the front heel and step through into the next lunge. Each step = 1 rep on that side."],"feel":"thighs and bum","dont":"take short steps"},{"name":"Goblet Cossack squat (dumbbell at chest)","sets":"3 x 8/side","steps":["Hold one dumbbell vertically at your chest with both hands (goblet hold). Feet very wide.","Sit down into one side, other leg straight with toes up.","Push back up and switch sides. Each side = 1 rep."],"feel":"bum and inner thighs","dont":"lift the heel of the bent leg"},{"name":"Single-leg dumbbell RDL (fingertips on wall)","sets":"3 x 8/side","steps":["Dumbbell in the hand opposite your standing leg. Other hand's fingertips on a wall.","Hinge forward, back leg lifting in line with your body, dumbbell lowering close to your shin. Hips square to the floor.","Squeeze your bum to stand. All reps one side, then switch."],"feel":"back of thigh and bum of the standing leg","dont":"open your hips to the side"},{"name":"Wall sit with dumbbell on lap","sets":"3 x 45 sec","steps":["Back flat against a wall, slide down until thighs are parallel to the floor.","Rest a dumbbell across your thighs, near your hips.","Hold for the time."],"feel":"front of thighs burning","dont":"push your hands into your thighs"},{"name":"Single-leg dumbbell calf raise","sets":"3 x 12/side","steps":["Dumbbell in the hand on the same side as your standing leg, other hand on a wall.","Stand on one foot, rise as high as you can.","Lower slowly. All reps one side, then switch."],"feel":"calf","dont":"bounce"}],"notes":[]},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"15-20 min","items":[{"name":"Butterfly","hold":"90 sec","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"90 sec","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Wall straddle","hold":"2-3 min","steps":["Lie on your back with your bum close to a wall, legs straight up the wall.","Let your legs slowly slide apart into a V.","Relax and let gravity open them wider. Hold."],"feel":"inner thighs","dont":null},{"name":"Seated straddle (wide-leg fold)","hold":"90 sec","steps":["Sit with legs straight and wide apart, toes up.","Sit tall (sit on a cushion if your back rounds).","Walk your hands forward and hinge from your hips, keeping your back flat. Hold."],"feel":"inner thighs, back of thighs","dont":null},{"name":"Cossack squat hold","hold":"10 sec x 8/side","steps":["Stand with feet very wide.","Sit down into one side (bent knee), other leg straight with toes up.","Hold the low position for the time, then switch sides. Hold a chair if needed."],"feel":"inner thigh of the straight leg","dont":null}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"4 sets unless noted","items":[{"name":"Barbell Romanian deadlift","sets":"4 x 10","steps":["Stand holding the bar in front of your thighs, hands just outside your legs, feet hip-width. (First rep: deadlift it up off the floor with a flat back.)","Soft knees. Push your hips back and slide the bar down your thighs, keeping it touching your legs and your back flat.","Go until you feel a strong stretch in the back of your thighs (usually just below the knee).","Squeeze your bum and push your hips forward to stand up."],"feel":"back of thighs and bum","dont":"round your back or let the bar drift away from your legs"},{"name":"Single-leg hip thrust (shoulders on couch)","sets":"3 x 10/side","steps":["Set up like a hip thrust: upper back on the couch edge, feet flat.","Lift one foot off the floor (knee bent, or leg straight).","Drive through the heel of the foot on the floor until your hips are level with your knee.","Squeeze at the top, lower slowly. All reps one side, then switch."],"feel":"bum of the working leg","dont":"let the hip on the lifted side drop"},{"name":"Slider hamstring curl (towel, smooth floor)","sets":"3 x 8","steps":["Lie on your back on a smooth floor (tiles/wood) with heels on a folded towel (or socks), legs straight.","Lift your hips up into a bridge.","Keeping hips up, pull your heels toward your bum, sliding the towel in.","Slowly slide your legs back out to straight. Hips stay up the whole time if you can."],"feel":"back of thighs","dont":"drop your hips to make it easier (lower them only if you must)"},{"name":"Dumbbell lateral lunge (goblet)","sets":"3 x 10/side","steps":["Feet together, one dumbbell at your chest.","Big step out to the side, toes forward. Sit back into that hip, other leg straight. Chest up.","Push off the bent leg to bring your feet back together. All reps one side, then switch."],"feel":"bum and inner thigh","dont":"let the bent knee cave in"},{"name":"Frog pump with 2 sec pause","sets":"3 x 25","steps":["Same as frog pump: on your back, soles together, knees out wide, heels near your bum.","Lift your hips by squeezing your bum.","Hold and squeeze for 2 sec at the top, then lower."],"feel":"bum, especially the sides","dont":"arch your lower back"},{"name":"Bird-dog, 3 sec hold","sets":"3 x 8/side","steps":["Hands and knees, back flat.","Reach opposite arm and leg out straight.","Hold for 3 sec, nice and still, then switch."],"feel":"core and bum","dont":"let your hips tip"}],"notes":[]},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"20 min","items":[{"name":"Half split","hold":"90 sec/side","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Supported front split","hold":"60 sec/side","steps":["Start in a half split. Put books or pillows under your hands on either side, and a pillow under your front hamstring/hips if needed.","Slowly slide your front heel forward and back knee back, lowering your hips.","Stop at mild tension and rest on the supports. Hips face forward. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Supported middle split","hold":"60 sec","steps":["Stand or kneel with legs wide apart, hands on the floor or books in front of you.","Slowly slide your feet out to the sides, lowering your hips.","Stop at mild tension and rest your weight on your hands/supports. Hold."],"feel":"inner thighs","dont":null},{"name":"Seated forward fold","hold":"90 sec","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null},{"name":"Lying figure-4 contract-relax","hold":"3 x 10 sec/side","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null}],"notes":[]}]},{"dow":"Saturday","title":"Row + test day","flow":"Row → Full-body flow → Test","sections":[{"kind":"row","title":"CONCEPT2 ROW: INTERVALS","meta":"","intro":["Warm up 5 min easy. Then alternate 3 min moderate (effort 6-7 out of 10) / 1 min easy. Cool down 3 min."],"table":[["Start","5 rounds"],["When that's easy","6 rounds"],["Easy week","4 rounds (5 once you're on 6)"]],"notes":["Effort: Intervals."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"30 min","items":[{"name":"Pigeon pose (each side)","hold":"75 sec","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Half split (each side)","hold":"75 sec","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Seated straddle fold","hold":"75 sec","steps":["Sit with legs straight and wide apart, toes up.","Sit tall (on a cushion if needed).","Walk your hands forward, hinge from your hips, back flat. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"75 sec","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Thread-the-needle (each side)","hold":"75 sec","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Deep squat hold","hold":"75 sec","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null},{"name":"Bridge prep","hold":"75 sec","steps":["Lie on your back, knees bent, feet flat near your bum.","Put your hands on the floor beside your ears, fingers pointing toward your shoulders.","Push through hands and feet to lift your hips and head off the floor (full bridge). Or just the top of your head down if that's as far as you get.","Hold for the time, lower gently."],"feel":"shoulders, front of body opening","dont":null}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm or pillows)","Middle split: hips from floor (cm or pillows)","Deep squat hold time","Bridge hold time","Barbell hip thrust: best weight x reps this week"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","hold":"2 min","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null},{"name":"Supine twist","hold":"1 min/side","steps":["On back, knees bent, let both knees fall to one side, shoulders stay down."],"feel":null,"dont":null},{"name":"Legs up the wall","hold":"5 min","steps":["Lie with bum near a wall and legs straight up it. Arms relaxed."],"feel":null,"dont":null},{"name":"Slow breathing","hold":"2 min","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null}],"notes":[]}]}]},{"n":3,"name":"Shape and Strength","tagline":"Heavier hip thrusts and deadlifts, harder single-leg moves, more side-glute work for hip width.","info":[["Strength","4 sets unless noted"],["Stretch holds","2-3 min, 2-3 rounds. Lower your split supports and add active leg holds."],["Goals","Dance-ready hips, high controlled leg lifts, a strong bridge."],["Move to next plan","When you tick off the dance-ready checklist at the back. Start dancing and move on to Plan 4."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"4 sets unless noted","items":[{"name":"Barbell hip thrust, 2 sec pause","sets":"4 x 10","steps":["Set up like a barbell hip thrust (upper back on couch, padded bar in your hip crease, chin tucked).","Drive up to a flat tabletop.","Hold and squeeze for 2 full sec at the top, then lower slowly."],"feel":"bum","dont":"arch your lower back"},{"name":"Dumbbell Bulgarian split squat, lean forward","sets":"4 x 10/side","steps":["Hold a dumbbell in each hand, arms hanging by your sides. Set up like a Bulgarian split squat, back foot on the couch.","Lean your chest forward about 30 degrees and keep it there.","Lower until the back knee nearly touches the floor, front heel down.","Push through the front heel to stand. All reps one side, then switch."],"feel":"bum more than thigh (that's the forward lean)","dont":"let the front knee cave in"},{"name":"Dumbbell curtsy lunge, 2 sec pause","sets":"3 x 10/side","steps":["Dumbbell at your chest.","Step back and across into a curtsy lunge, back knee near the floor.","Hold still 2 sec at the bottom, then push up through the front heel. All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"bounce out of the bottom"},{"name":"Barbell glute bridge (floor)","sets":"3 x 15","steps":["Lie on your back on the floor, knees bent, feet flat. Wrap a folded towel or yoga mat around the middle of the bar so it doesn't dig into your hips.","Roll the bar up your legs until it sits in your hip crease. Hold it with both hands.","Push through your heels and squeeze your bum to lift your hips until straight from knees to shoulders.","Squeeze 1-2 sec, lower slowly."],"feel":"bum","dont":"arch your back at the top"},{"name":"Fire hydrant + donkey kick combo","sets":"3 x 12/side","steps":["On hands and knees.","Lift one bent leg out to the side (fire hydrant), bring it back.","Then kick that foot up toward the ceiling (donkey kick), bring it back. Hydrant + kick = 1 rep.","All reps one side, then switch."],"feel":"all of your bum","dont":"arch your lower back"},{"name":"Side plank leg lift (on knee)","sets":"3 x 10/side","steps":["Get into a knee side plank: on your side, elbow under shoulder, knees bent, hips lifted.","Straighten your top leg.","Lift the top leg up as high as you can, then lower it. Hips stay up the whole time.","All reps one side, then switch."],"feel":"side of your bum on BOTH legs (bottom one holds you up)","dont":"let your hips drop"}],"notes":[]},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"15 min","items":[{"name":"90/90 hip switches","hold":"12 reps with pause","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null},{"name":"Figure-4 (on back)","hold":"90 sec/side","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null},{"name":"Pigeon pose","hold":"2 min/side","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Low lunge","hold":"90 sec/side","steps":["Step one foot forward into a lunge, put the back knee down on a cushion.","Torso tall, squeeze the bum of the back leg and gently push your hips forward.","Hold, then switch."],"feel":"front of the back hip","dont":null},{"name":"Deep squat hold","hold":"90-120 sec","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null}],"notes":[]}]},{"dow":"Tuesday","title":"Row","flow":"Row → Stretch","sections":[{"kind":"row","title":"CONCEPT2 ROW: STEADY","meta":"","intro":["Warm up 5 min easy."],"table":[["Every week","35 min"],["Easy week","25 min"]],"notes":["Effort: Moderate. 20-22 strokes/min, damper 3-5."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"20 min","items":[{"name":"Standing forward fold","hold":"90 sec","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null},{"name":"Heel-on-couch hamstring stretch","hold":"2 min/side","steps":["Stand facing a couch or stair. Put one heel on it, leg straight, toes up.","Hips facing forward, back flat.","Hinge forward from your hips (not by rounding your back) until you feel a stretch. Hold, then switch."],"feel":"back of the raised thigh","dont":null},{"name":"Half split (runner's stretch)","hold":"2 min/side","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side of the front leg. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Kneeling quad stretch","hold":"90 sec/side","steps":["Kneel in a low lunge (back knee on a cushion), near a couch or wall.","Reach back and grab your back foot (or rest it on the couch behind you).","Pull the foot toward your bum and squeeze the bum on that side. Hold, then switch."],"feel":"front of the back thigh","dont":null},{"name":"Supported front split","hold":"90-120 sec/side","steps":["Start in a half split. Put books or pillows under your hands on either side, and a pillow under your front hamstring/hips if needed.","Slowly slide your front heel forward and back knee back, lowering your hips.","Stop at mild tension and rest on the supports. Hips face forward. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Active leg raise","hold":"8 x 8 sec/side","steps":["Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + core","flow":"Warm-up → Upper + core → Stretch","sections":[{"kind":"strength","title":"UPPER + CORE","meta":"4 rounds (do 1-6 in a row = 1 round)","items":[{"name":"Full push-up (or your best version)","sets":"8","steps":["Hands on the floor a bit wider than shoulders, legs straight, body in one line.","Lower your chest to just above the floor, elbows angled back.","Push back up. If you can't do 6, use knees or a low incline."],"feel":"chest, arms, core","dont":"let hips sag"},{"name":"One-arm dumbbell row","sets":"12/side","steps":["Put one hand and the same-side knee on the couch (or just a hand on a chair, feet staggered). Back flat.","Hold a dumbbell in the other hand, arm hanging straight down.","Pull the dumbbell up toward your hip, elbow close to your side, squeezing your shoulder blade back.","Lower slowly. All reps one side, then switch."],"feel":"upper/middle back (posture muscles)","dont":"twist your body or shrug"},{"name":"Reverse snow angel","sets":"12","steps":["Lie face down, forehead on a folded towel, arms by your sides, palms down.","Lift your arms a few cm off the floor and squeeze your shoulder blades together.","Keeping arms off the floor and straight, sweep them out to the sides and up overhead (like a snow angel).","Sweep them back down to your sides. That's 1 rep."],"feel":"upper back, back of shoulders (great for posture, doesn't bulk)","dont":"shrug your shoulders up"},{"name":"Hollow hold","sets":"30 sec","steps":["Lie on your back, press your lower back into the floor.","Lift your head and shoulders, reach arms overhead, lift straight legs a few cm off the floor (like a banana).","Hold for the time. Too hard? Bend your knees or bring arms by your sides."],"feel":"abs","dont":"let your lower back lift"},{"name":"Side plank with hip dips","sets":"8/side","steps":["Get into a side plank.","Lower your hip toward the floor (don't touch), then lift it back up past straight.","That's 1 rep. All reps one side, then switch."],"feel":"side of waist","dont":"rush"},{"name":"Reverse plank","sets":"30 sec","steps":["Sit on the floor with legs straight, hands behind your hips, fingers pointing toward your feet.","Push through your hands and heels to lift your hips until your body is straight from shoulders to heels.","Hold for the time. Bent knees (tabletop) is easier."],"feel":"back of shoulders, bum, hamstrings","dont":"let your hips sag"}],"notes":["Upper body stays light on purpose: posture and a tight waist, no bulk. Use light dumbbells for rows."]},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"15 min","items":[{"name":"Cat-cow","hold":"15 reps","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null},{"name":"Thread-the-needle","hold":"60 sec/side","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Sphinx or cobra","hold":"60 sec","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null},{"name":"Doorway chest opener","hold":"60 sec/side","steps":["Stand in a doorway. Put your forearm on the frame, elbow at shoulder height.","Step forward with the same-side foot until you feel a stretch across your chest.","Hold, then switch."],"feel":"chest and front of shoulder","dont":null},{"name":"Puppy pose","hold":"90 sec","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null},{"name":"Bridge prep","hold":"3 x 15 sec","steps":["Lie on your back, knees bent, feet flat near your bum.","Put your hands on the floor beside your ears, fingers pointing toward your shoulders.","Push through hands and feet to lift your hips and head off the floor (full bridge). Or just the top of your head down if that's as far as you get.","Hold for the time, lower gently."],"feel":"shoulders, front of body opening","dont":null},{"name":"Supine twist","hold":"90 sec/side","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"4 sets unless noted","items":[{"name":"Goblet skater squat (dumbbell at chest)","sets":"4 x 8/side","steps":["Hold one dumbbell vertically at your chest with both hands (goblet hold). Stand on one leg, other knee bent with that foot behind you. Light touch on a wall if needed.","Lower the back knee toward the floor behind you, leaning forward a bit.","Touch the knee to a cushion, then stand. All reps one side, then switch."],"feel":"thigh and bum of standing leg","dont":"let the knee cave in"},{"name":"Heel-elevated goblet squat","sets":"3 x 12","steps":["Stand with your heels on a thin book or plate (2-3 cm), feet close together, dumbbell at your chest.","Squat straight down, letting your knees travel forward over your toes, torso upright.","Go as deep as you can, then stand up."],"feel":"front of thighs (gives that shapely thigh look)","dont":"let your heels slide off"},{"name":"Dumbbell walking lunge","sets":"3 x 12/side","steps":["Dumbbell in each hand, arms by your sides.","Long step forward, lower until back knee nearly touches the floor.","Push through the front heel and step through into the next lunge. Each step = 1 rep on that side."],"feel":"thighs and bum","dont":"take short steps"},{"name":"Single-leg dumbbell RDL","sets":"3 x 10/side","steps":["Hold a dumbbell in the hand opposite your standing leg.","Hinge forward, back leg lifting in line with your body, dumbbell lowering toward the floor close to your shin.","Squeeze your bum to stand back up. All reps one side, then switch."],"feel":"back of thigh and bum","dont":"round your back or open your hips"},{"name":"Assisted shrimp or pistol to box","sets":"3 x 6/side","steps":["Stand in front of a couch or low box, on one leg. Hold a wall or door frame if you need it.","Pistol: hold the free leg straight out in front. Shrimp: bend the free knee and hold that foot behind you.","Slowly sit down onto the couch on one leg, controlling the way down.","Stand back up on that one leg without using the free foot. All reps one side, then switch."],"feel":"thigh and bum of the standing leg","dont":"drop onto the seat; control it"},{"name":"Single-leg calf raise off a stair, with dumbbell","sets":"3 x 12/side","steps":["Dumbbell in the hand on the same side as your standing leg. Stand on one foot on the edge of a stair, heel hanging off, other hand on the rail.","Lower your heel below the step, then rise as high as you can.","All reps one side, then switch."],"feel":"calf","dont":"bounce"}],"notes":[]},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"15-20 min","items":[{"name":"Butterfly","hold":"2 min","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"2-3 min","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Wall straddle","hold":"4-5 min","steps":["Lie on your back with your bum close to a wall, legs straight up the wall.","Let your legs slowly slide apart into a V.","Relax and let gravity open them wider. Hold."],"feel":"inner thighs","dont":null},{"name":"Seated straddle (wide-leg fold)","hold":"2-3 min","steps":["Sit with legs straight and wide apart, toes up.","Sit tall (sit on a cushion if your back rounds).","Walk your hands forward and hinge from your hips, keeping your back flat. Hold."],"feel":"inner thighs, back of thighs","dont":null},{"name":"Cossack squat hold","hold":"15 sec x 8/side","steps":["Stand with feet very wide.","Sit down into one side (bent knee), other leg straight with toes up.","Hold the low position for the time, then switch sides. Hold a chair if needed."],"feel":"inner thigh of the straight leg","dont":null}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"4 sets unless noted","items":[{"name":"Barbell Romanian deadlift, 3 sec lowering","sets":"4 x 8","steps":["Same as the barbell Romanian deadlift.","Lower counting 3 slow seconds, bar sliding down your legs, back flat.","Squeeze your bum to stand back up."],"feel":"back of thighs and bum","dont":"round your back"},{"name":"Single-leg dumbbell hip thrust","sets":"3 x 10/side","steps":["Upper back on the couch edge, a dumbbell across your hips (towel underneath), holding both ends.","Lift one foot off the floor.","Drive up through the heel of the other foot until your hips are level. Squeeze, lower slowly.","All reps one side, then switch."],"feel":"bum of the working leg","dont":"let the hips tilt"},{"name":"Slider hamstring curl","sets":"3 x 12","steps":["Lie on your back, heels on a towel on a smooth floor, legs straight.","Lift your hips up into a bridge.","Pull your heels in toward your bum, then slowly slide them back out.","Hips stay up the whole time."],"feel":"back of thighs","dont":"let your hips sag"},{"name":"Dumbbell lateral lunge to curtsy flow","sets":"3 x 8/side","steps":["Dumbbell in each hand, arms by your sides.","Step out into a side lunge, push off and swing the same leg back and across into a curtsy lunge.","Stand up. Side lunge + curtsy = 1 rep. All reps one side, then switch."],"feel":"bum, outer hips, inner thighs","dont":"rush"},{"name":"Nordic-style hamstring lower (feet under couch)","sets":"3 x 5","steps":["Kneel on a cushion with your ankles hooked under a heavy couch (or someone holding them).","Body straight from knees to head, hips pushed forward, hands in front of your chest.","Slowly lean forward as far as you can, fighting it with the back of your thighs.","When you can't hold it, fall onto your hands (like a push-up), push yourself back up to kneeling."],"feel":"back of thighs, very hard","dont":"bend at the hips; keep a straight line"},{"name":"Single-leg balance, eyes closed","sets":"3 x 20 sec/side","steps":["Stand on one foot, slight bend in the knee.","Find your balance, then close your eyes.","Hold for the time. Stand near a wall in case you wobble."],"feel":"ankle and outer hip working hard","dont":"lock your knee"}],"notes":[]},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"20 min","items":[{"name":"Half split","hold":"2 min/side","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Supported front split","hold":"2 min/side","steps":["Start in a half split. Put books or pillows under your hands on either side, and a pillow under your front hamstring/hips if needed.","Slowly slide your front heel forward and back knee back, lowering your hips.","Stop at mild tension and rest on the supports. Hips face forward. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Supported middle split","hold":"2 min","steps":["Stand or kneel with legs wide apart, hands on the floor or books in front of you.","Slowly slide your feet out to the sides, lowering your hips.","Stop at mild tension and rest your weight on your hands/supports. Hold."],"feel":"inner thighs","dont":null},{"name":"Seated forward fold","hold":"2 min","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null},{"name":"Lying figure-4 contract-relax","hold":"3 x 10 sec/side","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null}],"notes":[]}]},{"dow":"Saturday","title":"Row + test day","flow":"Row → Full-body flow → Test","sections":[{"kind":"row","title":"CONCEPT2 ROW: INTERVALS","meta":"","intro":["Warm up 5 min easy. Then alternate 3 min hard but controlled (effort 7 out of 10) / 1 min easy. Cool down 3 min."],"table":[["Start","7 rounds"],["When that's easy","8 rounds"],["Easy week","5 rounds (6 once you're on 8)"]],"notes":["Effort: Intervals."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"30 min","items":[{"name":"Pigeon pose (each side)","hold":"2 min","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Half split (each side)","hold":"2 min","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Seated straddle fold","hold":"2 min","steps":["Sit with legs straight and wide apart, toes up.","Sit tall (on a cushion if needed).","Walk your hands forward, hinge from your hips, back flat. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"2 min","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Thread-the-needle (each side)","hold":"2 min","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Deep squat hold","hold":"2 min","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null},{"name":"Bridge prep","hold":"2 min","steps":["Lie on your back, knees bent, feet flat near your bum.","Put your hands on the floor beside your ears, fingers pointing toward your shoulders.","Push through hands and feet to lift your hips and head off the floor (full bridge). Or just the top of your head down if that's as far as you get.","Hold for the time, lower gently."],"feel":"shoulders, front of body opening","dont":null}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm or pillows)","Middle split: hips from floor (cm or pillows)","Deep squat hold time","Bridge hold time","Barbell hip thrust: best weight x reps this week"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","hold":"2 min","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null},{"name":"Supine twist","hold":"1 min/side","steps":["On back, knees bent, let both knees fall to one side, shoulders stay down."],"feel":null,"dont":null},{"name":"Legs up the wall","hold":"5 min","steps":["Lie with bum near a wall and legs straight up it. Arms relaxed."],"feel":null,"dont":null},{"name":"Slow breathing","hold":"2 min","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null}],"notes":[]}]}]},{"n":4,"name":"Load","tagline":"Go heavier on the big lifts. Fewer reps, more weight, more growth.","info":[["Strength","4 sets unless noted"],["Stretch holds","2-3 min, 2-3 rounds. Contract-relax on everything. Add active holds (lifting your own leg with no hands)."],["Goals","Front and middle split with only one support. Full bridge for 15 sec. Heavy barbell hip thrusts and dumbbell Bulgarian split squats feel solid."],["Move to next plan","When this whole week feels easy."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"4 sets unless noted","items":[{"name":"Barbell hip thrust (shoulders on couch)","sets":"4 x 8 (heavy)","steps":["Sit on the floor, upper back (bottom of shoulder blades) against the couch edge, legs straight. Wrap a folded towel or yoga mat around the middle of the bar so it doesn't dig into your hips.","Roll the loaded bar over your legs until it sits in the crease of your hips. Hold it with both hands just outside your hips.","Bend your knees, feet flat and hip-width, so your shins will be vertical at the top. Tuck your chin.","Drive through your heels and push the bar up until your body is a flat tabletop from knees to shoulders. Squeeze your bum hard, then lower slowly."],"feel":"bum, big squeeze at the top","dont":"arch your lower back or throw your head back; ribs stay down"},{"name":"Dumbbell Bulgarian split squat","sets":"4 x 8/side (heavy)","steps":["Dumbbell in each hand by your sides. Stand a big stride in front of the couch, top of one foot on the couch behind you.","Lower straight down until the back knee nearly touches the floor. Front heel stays down, lean forward slightly.","Push through the front heel to stand. All reps one side, then switch."],"feel":"front thigh and bum","dont":"let the front heel lift (move your foot further out if it does)"},{"name":"B-stance barbell hip thrust","sets":"3 x 10/side","steps":["Barbell hip thrust set-up (upper back on couch, padded bar on hips).","Move one foot forward so only that heel touches the floor, toes up. The other foot does about 80% of the work.","Drive up through the back foot's heel, squeeze, lower slowly. All reps one side, then switch."],"feel":"bum of the working (back) leg","dont":"let the hips tilt"},{"name":"Dumbbell deficit reverse lunge","sets":"3 x 10/side","steps":["Stand on a low step or a weight plate, dumbbell in each hand.","Step one foot back off the step and lower until the back knee nearly touches the floor (deeper than normal).","Push through the front heel to step back up. All reps one side, then switch."],"feel":"bum of the front leg, stretch at the bottom","dont":"lean back"},{"name":"Dumbbell frog pump","sets":"3 x 25","steps":["On your back, soles together, knees out wide, heels near your bum.","Lay a dumbbell across your hips (towel underneath) and hold both ends.","Squeeze your bum to lift your hips, lower, repeat."],"feel":"bum, especially the sides","dont":"arch your lower back"},{"name":"Side plank leg lift (on feet)","sets":"3 x 10/side","steps":["Get into a full side plank on your elbow and feet, hips up.","Lift your top leg as high as you can, then lower it.","All reps one side, then switch."],"feel":"side of your bum, side of waist","dont":"let your hips sag"}],"notes":[]},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"15 min","items":[{"name":"90/90 hip switches","hold":"12 reps, hands off the floor","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null},{"name":"Figure-4 (on back)","hold":"2 min/side","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null},{"name":"Pigeon pose","hold":"2-3 min/side","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Couch stretch","hold":"90 sec/side","steps":["Kneel with your back to a couch. Put one knee on the floor right against the couch, with that shin and foot up the couch.","Step the other foot forward into a lunge.","Slowly lift your torso upright and squeeze the bum of the back leg. Hold, then switch."],"feel":"front of the back thigh and hip (strong)","dont":null},{"name":"Deep squat hold","hold":"2 min","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null}],"notes":[]}]},{"dow":"Tuesday","title":"Row","flow":"Row → Stretch","sections":[{"kind":"row","title":"CONCEPT2 ROW: STEADY","meta":"","intro":["Warm up 5 min easy."],"table":[["Every week","40 min"],["Easy week","30 min"]],"notes":["Effort: Moderate. 20-22 strokes/min, damper 3-5."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"20 min","items":[{"name":"Standing forward fold","hold":"2 min","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null},{"name":"Heel-on-couch hamstring stretch","hold":"2 min/side","steps":["Stand facing a couch or stair. Put one heel on it, leg straight, toes up.","Hips facing forward, back flat.","Hinge forward from your hips (not by rounding your back) until you feel a stretch. Hold, then switch."],"feel":"back of the raised thigh","dont":null},{"name":"Half split (runner's stretch)","hold":"2 min/side","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side of the front leg. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Couch stretch","hold":"2 min/side","steps":["Kneel with your back to a couch. Put one knee on the floor right against the couch, with that shin and foot up the couch.","Step the other foot forward into a lunge.","Slowly lift your torso upright and squeeze the bum of the back leg. Hold, then switch."],"feel":"front of the back thigh and hip (strong)","dont":null},{"name":"Supported front split","hold":"2 min/side (one fewer support)","steps":["Start in a half split. Put books or pillows under your hands on either side, and a pillow under your front hamstring/hips if needed.","Slowly slide your front heel forward and back knee back, lowering your hips.","Stop at mild tension and rest on the supports. Hips face forward. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Active leg raise","hold":"8 x 10 sec/side","steps":["Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null},{"name":"Standing front leg hold","hold":"6 x 5 sec/side","steps":["Stand tall next to a wall, hand on it.","Lift your outside leg straight in front of you as high as you can, using only your leg muscles.","Hold for the time, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of thigh working, back of thigh stretching","dont":null}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + core","flow":"Warm-up → Upper + core → Stretch","sections":[{"kind":"strength","title":"UPPER + CORE","meta":"4 rounds (do 1-6 in a row = 1 round)","items":[{"name":"Full push-up, 3 sec lowering","sets":"8","steps":["Full push-up position (or knees if needed), body straight.","Lower your chest to just above the floor counting 3 slow seconds.","Push back up."],"feel":"chest, arms, core","dont":"let hips sag"},{"name":"One-arm dumbbell row","sets":"12/side","steps":["Put one hand and the same-side knee on the couch (or just a hand on a chair, feet staggered). Back flat.","Hold a dumbbell in the other hand, arm hanging straight down.","Pull the dumbbell up toward your hip, elbow close to your side, squeezing your shoulder blade back.","Lower slowly. All reps one side, then switch."],"feel":"upper/middle back (posture muscles)","dont":"twist your body or shrug"},{"name":"Reverse snow angel","sets":"12","steps":["Lie face down, forehead on a folded towel, arms by your sides, palms down.","Lift your arms a few cm off the floor and squeeze your shoulder blades together.","Keeping arms off the floor and straight, sweep them out to the sides and up overhead (like a snow angel).","Sweep them back down to your sides. That's 1 rep."],"feel":"upper back, back of shoulders (great for posture, doesn't bulk)","dont":"shrug your shoulders up"},{"name":"Hollow hold","sets":"40 sec","steps":["Lie on your back, press your lower back into the floor.","Lift your head and shoulders, reach arms overhead, lift straight legs a few cm off the floor (like a banana).","Hold for the time. Too hard? Bend your knees or bring arms by your sides."],"feel":"abs","dont":"let your lower back lift"},{"name":"Side plank with reach-through","sets":"8/side","steps":["Full side plank on your elbow (knees down if needed), top arm reaching to the ceiling.","Reach your top arm down and under your body, twisting your chest toward the floor.","Unwind back to the start. Hips stay up. All reps one side, then switch."],"feel":"side of waist and core","dont":"let your hips drop"},{"name":"Reverse plank","sets":"40 sec","steps":["Sit on the floor with legs straight, hands behind your hips, fingers pointing toward your feet.","Push through your hands and heels to lift your hips until your body is straight from shoulders to heels.","Hold for the time. Bent knees (tabletop) is easier."],"feel":"back of shoulders, bum, hamstrings","dont":"let your hips sag"}],"notes":["Upper body stays light on purpose: posture and a tight waist, no bulk. Use light dumbbells for rows."]},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"15 min","items":[{"name":"Cat-cow","hold":"15 reps","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null},{"name":"Thread-the-needle","hold":"60 sec/side","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Sphinx or cobra","hold":"60 sec","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null},{"name":"Doorway chest opener","hold":"60 sec/side","steps":["Stand in a doorway. Put your forearm on the frame, elbow at shoulder height.","Step forward with the same-side foot until you feel a stretch across your chest.","Hold, then switch."],"feel":"chest and front of shoulder","dont":null},{"name":"Puppy pose","hold":"90 sec","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null},{"name":"Full bridge hold","hold":"3 x 15 sec","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null},{"name":"Supine twist","hold":"90 sec/side","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"4 sets unless noted","items":[{"name":"Goblet skater squat, no support","sets":"4 x 8/side","steps":["Hold one dumbbell at your chest (goblet hold), or a light one in each hand reaching forward for balance. No wall this time.","Stand on one leg, lower the back knee toward a cushion behind you, arms reaching forward.","Tap the cushion, then stand. All reps one side, then switch."],"feel":"thigh and bum of standing leg","dont":"let the knee cave in"},{"name":"Shrimp squat","sets":"3 x 6/side","steps":["Stand on one leg. Bend the other knee and hold that foot behind you with the same-side hand.","Lower until the back knee touches a cushion on the floor. Lean forward and reach the other arm forward.","Stand back up. All reps one side, then switch. Hold a wall if needed."],"feel":"thigh and bum of standing leg","dont":"let the knee cave in"},{"name":"Dumbbell walking lunge","sets":"3 x 12/side (heavier)","steps":["Dumbbell in each hand, arms by your sides.","Long step forward, lower until back knee nearly touches the floor.","Push through the front heel and step through into the next lunge. Each step = 1 rep on that side."],"feel":"thighs and bum","dont":"take short steps"},{"name":"Single-leg dumbbell RDL, 3 sec lowering","sets":"3 x 10/side","steps":["Dumbbell in the hand opposite your standing leg.","Hinge forward counting 3 slow seconds, back leg lifting in line.","Squeeze your bum to stand up. All reps one side, then switch."],"feel":"back of thigh and bum","dont":"round your back"},{"name":"Sissy squat (hold door frame)","sets":"3 x 8","steps":["Stand holding a door frame with one hand, feet hip-width.","Rise onto the balls of your feet and push your knees forward while leaning your body back, so your body is a straight line from knees to head.","Lower as far as you comfortably can, then push back up."],"feel":"front of thighs","dont":"go deep if your knees hurt; small range is fine"},{"name":"Single-leg calf raise off a stair, with dumbbell","sets":"3 x 15/side","steps":["Dumbbell in the hand on the same side as your standing leg. Stand on one foot on the edge of a stair, heel hanging off, other hand on the rail.","Lower your heel below the step, then rise as high as you can.","All reps one side, then switch."],"feel":"calf","dont":"bounce"}],"notes":[]},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"15-20 min","items":[{"name":"Butterfly","hold":"2 min","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"3 min","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Wall straddle","hold":"5 min","steps":["Lie on your back with your bum close to a wall, legs straight up the wall.","Let your legs slowly slide apart into a V.","Relax and let gravity open them wider. Hold."],"feel":"inner thighs","dont":null},{"name":"Pancake fold","hold":"2-3 min","steps":["Sit with legs wide in a straddle, toes up. Sit on a cushion if your back rounds.","Tilt your pelvis forward (stick your bum out) and walk your hands forward.","Lower your chest toward the floor with a flat back. Hold."],"feel":"inner thighs, back of thighs","dont":null},{"name":"Cossack squat hold","hold":"20 sec x 6/side","steps":["Stand with feet very wide.","Sit down into one side (bent knee), other leg straight with toes up.","Hold the low position for the time, then switch sides. Hold a chair if needed."],"feel":"inner thigh of the straight leg","dont":null},{"name":"Side leg hold","hold":"6 x 5 sec/side","steps":["Stand tall, side-on to a wall, hand on it.","Lift your outside leg straight out to the side as high as you can, toes forward.","Hold for the time, lower. Do all reps, then switch."],"feel":"side of hip working, inner thigh stretching","dont":null}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"4 sets unless noted","items":[{"name":"Barbell Romanian deadlift","sets":"4 x 8 (heavy)","steps":["Stand holding the bar in front of your thighs, hands just outside your legs, feet hip-width. (First rep: deadlift it up off the floor with a flat back.)","Soft knees. Push your hips back and slide the bar down your thighs, keeping it touching your legs and your back flat.","Go until you feel a strong stretch in the back of your thighs (usually just below the knee).","Squeeze your bum and push your hips forward to stand up."],"feel":"back of thighs and bum","dont":"round your back or let the bar drift away from your legs"},{"name":"Single-leg dumbbell hip thrust, 1.5 reps","sets":"3 x 8/side","steps":["Upper back on the couch, dumbbell across your hips, one foot down.","Up all the way, down halfway, up all the way, then down fully. That's 1 rep.","All reps one side, then switch."],"feel":"bum of the working leg burning","dont":"let the hips tilt"},{"name":"Single-leg slider hamstring curl","sets":"3 x 6/side","steps":["Lie on your back, one heel on a towel on a smooth floor, other leg lifted.","Lift your hips up into a bridge.","Pull the heel in toward your bum, then slowly slide it back out. Hips stay up.","All reps one side, then switch."],"feel":"back of thigh","dont":"let your hips sag"},{"name":"Goblet Cossack squat (dumbbell at chest)","sets":"3 x 8/side","steps":["Hold one dumbbell vertically at your chest with both hands (goblet hold). Feet very wide.","Sit down into one side, other leg straight with toes up.","Push back up and switch sides. Each side = 1 rep."],"feel":"bum and inner thighs","dont":"lift the heel of the bent leg"},{"name":"Nordic-style hamstring lower (feet under couch)","sets":"3 x 6","steps":["Kneel on a cushion with your ankles hooked under a heavy couch (or someone holding them).","Body straight from knees to head, hips pushed forward, hands in front of your chest.","Slowly lean forward as far as you can, fighting it with the back of your thighs.","When you can't hold it, fall onto your hands (like a push-up), push yourself back up to kneeling."],"feel":"back of thighs, very hard","dont":"bend at the hips; keep a straight line"},{"name":"Copenhagen plank (knee on couch)","sets":"3 x 15 sec/side","steps":["Lie on your side next to a couch. Put your top knee/inner knee on the couch seat, bottom leg under it.","Prop up on your elbow and lift your hips so your body is straight. Bottom leg can hang or lift to touch the couch.","Hold for the time, then switch."],"feel":"inner thigh of the top leg","dont":"let your hips sag"}],"notes":[]},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"20 min","items":[{"name":"Half split","hold":"2 min/side","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Supported front split","hold":"2-3 min/side","steps":["Start in a half split. Put books or pillows under your hands on either side, and a pillow under your front hamstring/hips if needed.","Slowly slide your front heel forward and back knee back, lowering your hips.","Stop at mild tension and rest on the supports. Hips face forward. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Supported middle split","hold":"2-3 min","steps":["Stand or kneel with legs wide apart, hands on the floor or books in front of you.","Slowly slide your feet out to the sides, lowering your hips.","Stop at mild tension and rest your weight on your hands/supports. Hold."],"feel":"inner thighs","dont":null},{"name":"Seated forward fold","hold":"2 min","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null},{"name":"Lying figure-4 contract-relax","hold":"3 x 10 sec/side","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null}],"notes":[]}]},{"dow":"Saturday","title":"Row + test day","flow":"Row → Full-body flow → Test","sections":[{"kind":"row","title":"CONCEPT2 ROW: INTERVALS","meta":"","intro":["Warm up 5 min easy. Then alternate 4 min hard but controlled (effort 7 out of 10) / 1 min easy. Cool down 3 min."],"table":[["Start","6 rounds"],["When that's easy","7 rounds"],["Easy week","5 rounds"]],"notes":["Effort: Intervals."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"30 min","items":[{"name":"Pigeon pose (each side)","hold":"2 min","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Half split (each side)","hold":"2 min","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Seated straddle fold","hold":"2 min","steps":["Sit with legs straight and wide apart, toes up.","Sit tall (on a cushion if needed).","Walk your hands forward, hinge from your hips, back flat. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"2 min","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Thread-the-needle (each side)","hold":"2 min","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Deep squat hold","hold":"2 min","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null},{"name":"Bridge prep","hold":"2 min","steps":["Lie on your back, knees bent, feet flat near your bum.","Put your hands on the floor beside your ears, fingers pointing toward your shoulders.","Push through hands and feet to lift your hips and head off the floor (full bridge). Or just the top of your head down if that's as far as you get.","Hold for the time, lower gently."],"feel":"shoulders, front of body opening","dont":null}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm or pillows)","Middle split: hips from floor (cm or pillows)","Deep squat hold time","Bridge hold time","Barbell hip thrust: best weight x reps this week"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","hold":"2 min","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null},{"name":"Supine twist","hold":"1 min/side","steps":["On back, knees bent, let both knees fall to one side, shoulders stay down."],"feel":null,"dont":null},{"name":"Legs up the wall","hold":"5 min","steps":["Lie with bum near a wall and legs straight up it. Arms relaxed."],"feel":null,"dont":null},{"name":"Slow breathing","hold":"2 min","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null}],"notes":[]}]}]},{"n":5,"name":"Advanced","tagline":"Slow reps, pauses and 1.5 reps with real weight. Peak glute and hip work.","info":[["Strength","4 sets unless noted"],["Stretch holds","2-3 min, 3 rounds. Supports almost gone. Active holds 8-10 sec."],["Goals","Front split with hips near the floor. Pancake fold with chest heading to the floor. Full bridge 20 sec. 10 sec standing leg holds."],["Move to next plan","When this whole week feels easy."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"4 sets unless noted","items":[{"name":"Barbell hip thrust, 1.5 reps","sets":"4 x 8","steps":["Barbell hip thrust set-up.","Up all the way, down halfway, up all the way again, then lower fully. That's 1 rep."],"feel":"bum burning","dont":"rush the half rep"},{"name":"Dumbbell Bulgarian split squat, 1.5 reps","sets":"4 x 8/side","steps":["Dumbbell in each hand by your sides. Back foot on the couch.","Lower all the way down, come halfway up, go back all the way down, then stand up fully. That's 1 rep.","All reps one side, then switch."],"feel":"thigh and bum burning","dont":"rush the half rep"},{"name":"B-stance barbell hip thrust, 2 sec pause","sets":"3 x 10/side","steps":["B-stance set-up: one foot forward on its heel, the other doing the work, padded bar on hips.","Drive up, hold and squeeze 2 sec at the top, lower slowly.","All reps one side, then switch."],"feel":"bum of the working leg","dont":"let the hips tilt"},{"name":"Dumbbell deficit curtsy lunge","sets":"3 x 10/side","steps":["Stand on a low step or plate, dumbbell at your chest.","Step one leg back and across onto the floor and lower into a curtsy lunge.","Push through the front heel to stand back up on the step. All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"twist your hips"},{"name":"Barbell glute bridge pulses","sets":"3 x 20","steps":["Barbell glute bridge on the floor, padded bar in your hip crease.","Lift into the bridge.","Without coming all the way down, pulse your hips up and down a few cm, squeezing at the top each time."],"feel":"bum on fire","dont":"let your lower back take over"},{"name":"Fire hydrant + donkey kick combo, 2 sec hold","sets":"3 x 12/side","steps":["On hands and knees.","Lift one bent leg out to the side and hold 2 sec. Bring it back.","Kick that foot up toward the ceiling and hold 2 sec. Bring it back. That's 1 rep.","All reps one side, then switch."],"feel":"all of your bum","dont":"arch your lower back"}],"notes":[]},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"15 min","items":[{"name":"90/90 hip switches","hold":"12 reps, hands off the floor","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null},{"name":"Figure-4 (on back)","hold":"2 min/side","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null},{"name":"Pigeon pose","hold":"3 min/side","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Couch stretch","hold":"2 min/side","steps":["Kneel with your back to a couch. Put one knee on the floor right against the couch, with that shin and foot up the couch.","Step the other foot forward into a lunge.","Slowly lift your torso upright and squeeze the bum of the back leg. Hold, then switch."],"feel":"front of the back thigh and hip (strong)","dont":null},{"name":"Deep squat hold","hold":"2-3 min","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null}],"notes":[]}]},{"dow":"Tuesday","title":"Row","flow":"Row → Stretch","sections":[{"kind":"row","title":"CONCEPT2 ROW: STEADY","meta":"","intro":["Warm up 5 min easy."],"table":[["Start","40 min"],["When that's easy","45 min"],["Easy week","30 min"]],"notes":["Effort: Moderate. 20-22 strokes/min, damper 3-5."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"20 min","items":[{"name":"Standing forward fold","hold":"2 min","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null},{"name":"Heel-on-couch hamstring stretch","hold":"2-3 min/side","steps":["Stand facing a couch or stair. Put one heel on it, leg straight, toes up.","Hips facing forward, back flat.","Hinge forward from your hips (not by rounding your back) until you feel a stretch. Hold, then switch."],"feel":"back of the raised thigh","dont":null},{"name":"Half split (runner's stretch)","hold":"2-3 min/side","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side of the front leg. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Couch stretch","hold":"2 min/side","steps":["Kneel with your back to a couch. Put one knee on the floor right against the couch, with that shin and foot up the couch.","Step the other foot forward into a lunge.","Slowly lift your torso upright and squeeze the bum of the back leg. Hold, then switch."],"feel":"front of the back thigh and hip (strong)","dont":null},{"name":"Front split","hold":"2 min/side","steps":["Start in a half split. Keep one book or a cushion under your front thigh if you need it.","Slide your front heel forward and back knee back until you're as low as you can go, hips square.","Hands on the floor or books beside you. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Active leg raise","hold":"8 x 10 sec/side","steps":["Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null},{"name":"Standing front leg hold","hold":"6 x 8 sec/side","steps":["Stand tall next to a wall, hand on it.","Lift your outside leg straight in front of you as high as you can, using only your leg muscles.","Hold for the time, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of thigh working, back of thigh stretching","dont":null}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + core","flow":"Warm-up → Upper + core → Stretch","sections":[{"kind":"strength","title":"UPPER + CORE","meta":"4 rounds (do 1-6 in a row = 1 round)","items":[{"name":"Full push-up, 3 sec lowering","sets":"10","steps":["Full push-up position (or knees if needed), body straight.","Lower your chest to just above the floor counting 3 slow seconds.","Push back up."],"feel":"chest, arms, core","dont":"let hips sag"},{"name":"One-arm dumbbell row, 3 sec lowering","sets":"10/side","steps":["Hand and knee on the couch, dumbbell in the other hand.","Pull the dumbbell up to your hip, squeeze your shoulder blade.","Lower counting 3 slow seconds. All reps one side, then switch."],"feel":"upper/middle back","dont":"twist or shrug"},{"name":"Reverse snow angel","sets":"12","steps":["Lie face down, forehead on a folded towel, arms by your sides, palms down.","Lift your arms a few cm off the floor and squeeze your shoulder blades together.","Keeping arms off the floor and straight, sweep them out to the sides and up overhead (like a snow angel).","Sweep them back down to your sides. That's 1 rep."],"feel":"upper back, back of shoulders (great for posture, doesn't bulk)","dont":"shrug your shoulders up"},{"name":"Hollow hold","sets":"45 sec","steps":["Lie on your back, press your lower back into the floor.","Lift your head and shoulders, reach arms overhead, lift straight legs a few cm off the floor (like a banana).","Hold for the time. Too hard? Bend your knees or bring arms by your sides."],"feel":"abs","dont":"let your lower back lift"},{"name":"Side plank with reach-through","sets":"10/side","steps":["Full side plank on your elbow (knees down if needed), top arm reaching to the ceiling.","Reach your top arm down and under your body, twisting your chest toward the floor.","Unwind back to the start. Hips stay up. All reps one side, then switch."],"feel":"side of waist and core","dont":"let your hips drop"},{"name":"Reverse plank leg lift","sets":"6/side","steps":["Get into a reverse plank: sit, hands behind your hips, lift your body into a straight line.","Keeping hips up, lift one straight leg a little, hold 1 sec, lower.","Alternate legs. Each lift = 1 rep on that side."],"feel":"bum, hamstrings, back of shoulders","dont":"let your hips sag"}],"notes":["Upper body stays light on purpose: posture and a tight waist, no bulk. Use light dumbbells for rows."]},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"15 min","items":[{"name":"Cat-cow","hold":"15 reps","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null},{"name":"Thread-the-needle","hold":"90 sec/side","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Sphinx or cobra","hold":"90 sec","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null},{"name":"Doorway chest opener","hold":"90 sec/side","steps":["Stand in a doorway. Put your forearm on the frame, elbow at shoulder height.","Step forward with the same-side foot until you feel a stretch across your chest.","Hold, then switch."],"feel":"chest and front of shoulder","dont":null},{"name":"Puppy pose","hold":"2 min","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null},{"name":"Full bridge hold","hold":"3 x 20 sec","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null},{"name":"Supine twist","hold":"90 sec/side","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"4 sets unless noted","items":[{"name":"Goblet skater squat, no support","sets":"4 x 10/side","steps":["Hold one dumbbell at your chest (goblet hold), or a light one in each hand reaching forward for balance. No wall this time.","Stand on one leg, lower the back knee toward a cushion behind you, arms reaching forward.","Tap the cushion, then stand. All reps one side, then switch."],"feel":"thigh and bum of standing leg","dont":"let the knee cave in"},{"name":"Shrimp squat with dumbbell","sets":"3 x 6/side","steps":["Same as shrimp squat, holding a light dumbbell in your free hand, reaching it forward for balance.","Hold the back foot, lower the back knee to the cushion, stand back up.","All reps one side, then switch."],"feel":"thigh and bum","dont":"let the knee cave in"},{"name":"Assisted pistol squat to low cushion","sets":"3 x 6/side","steps":["Stand on one leg in front of a low cushion or a couple of pillows (lower than a couch). Hold a door frame.","Hold the free leg straight out in front.","Sit down slowly onto the cushion on one leg, then stand back up, using the door frame only as much as you need.","All reps one side, then switch."],"feel":"thigh and bum","dont":"drop onto the cushion"},{"name":"Single-leg dumbbell RDL","sets":"3 x 10/side (heavy)","steps":["Hold a dumbbell in the hand opposite your standing leg.","Hinge forward, back leg lifting in line with your body, dumbbell lowering toward the floor close to your shin.","Squeeze your bum to stand back up. All reps one side, then switch."],"feel":"back of thigh and bum","dont":"round your back or open your hips"},{"name":"Heel-elevated goblet squat, 3 sec lowering","sets":"3 x 10","steps":["Heels on a thin book or plate, feet close, dumbbell at your chest.","Lower counting 3 slow seconds, knees forward, torso upright.","Stand up."],"feel":"front of thighs","dont":"bounce out of the bottom"},{"name":"Single-leg calf raise off a stair, with dumbbell","sets":"3 x 15/side","steps":["Dumbbell in the hand on the same side as your standing leg. Stand on one foot on the edge of a stair, heel hanging off, other hand on the rail.","Lower your heel below the step, then rise as high as you can.","All reps one side, then switch."],"feel":"calf","dont":"bounce"}],"notes":[]},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"15-20 min","items":[{"name":"Butterfly","hold":"2-3 min","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"3 min","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Wall straddle","hold":"5 min","steps":["Lie on your back with your bum close to a wall, legs straight up the wall.","Let your legs slowly slide apart into a V.","Relax and let gravity open them wider. Hold."],"feel":"inner thighs","dont":null},{"name":"Pancake fold","hold":"3 min","steps":["Sit with legs wide in a straddle, toes up. Sit on a cushion if your back rounds.","Tilt your pelvis forward (stick your bum out) and walk your hands forward.","Lower your chest toward the floor with a flat back. Hold."],"feel":"inner thighs, back of thighs","dont":null},{"name":"Middle split","hold":"2 min","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null},{"name":"Side leg hold","hold":"6 x 8 sec/side","steps":["Stand tall, side-on to a wall, hand on it.","Lift your outside leg straight out to the side as high as you can, toes forward.","Hold for the time, lower. Do all reps, then switch."],"feel":"side of hip working, inner thigh stretching","dont":null}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"4 sets unless noted","items":[{"name":"Barbell Romanian deadlift, 3 sec lowering","sets":"4 x 8 (heavy)","steps":["Same as the barbell Romanian deadlift.","Lower counting 3 slow seconds, bar sliding down your legs, back flat.","Squeeze your bum to stand back up."],"feel":"back of thighs and bum","dont":"round your back"},{"name":"Feet-elevated single-leg dumbbell hip thrust","sets":"4 x 10/side","steps":["Upper back on the couch, one foot up on a low step or book stack (10-20 cm) in front of you. Dumbbell across your hips, holding both ends.","Lift the other foot off the floor.","Drive through the heel on the step until your hips are level. Squeeze 1-2 sec, lower slowly.","All reps one side, then switch."],"feel":"bum and back of thigh","dont":"let the hips tilt"},{"name":"Single-leg slider hamstring curl","sets":"3 x 8/side","steps":["Lie on your back, one heel on a towel on a smooth floor, other leg lifted.","Lift your hips up into a bridge.","Pull the heel in toward your bum, then slowly slide it back out. Hips stay up.","All reps one side, then switch."],"feel":"back of thigh","dont":"let your hips sag"},{"name":"Dumbbell lateral lunge to curtsy flow","sets":"3 x 10/side","steps":["Dumbbell in each hand, arms by your sides.","Step out into a side lunge, push off and swing the same leg back and across into a curtsy lunge.","Stand up. Side lunge + curtsy = 1 rep. All reps one side, then switch."],"feel":"bum, outer hips, inner thighs","dont":"rush"},{"name":"Nordic-style hamstring lower, 5 sec lowering","sets":"3 x 6","steps":["Kneel on a cushion, ankles hooked under a heavy couch.","Body straight from knees to head.","Lower forward counting 5 slow seconds, catch yourself with your hands, push back up."],"feel":"back of thighs, very hard","dont":"bend at the hips"},{"name":"Copenhagen plank (foot on couch)","sets":"3 x 15 sec/side","steps":["Same as the knee version, but your top foot/ankle rests on the couch (harder, longer lever).","Elbow under shoulder, lift hips so body is straight.","Hold for the time, then switch."],"feel":"inner thigh","dont":"let your hips sag"}],"notes":[]},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"20 min","items":[{"name":"Front split","hold":"2-3 min/side","steps":["Start in a half split. Keep one book or a cushion under your front thigh if you need it.","Slide your front heel forward and back knee back until you're as low as you can go, hips square.","Hands on the floor or books beside you. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Middle split","hold":"2-3 min","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null},{"name":"Standing split","hold":"60 sec/side","steps":["Stand facing the floor in a forward fold, hands on the floor or on books.","Lift one leg straight up behind you as high as it will go, hips as square as you can.","Hold, then switch."],"feel":"back of the standing thigh, front of the lifted hip","dont":null},{"name":"Seated forward fold","hold":"2 min","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null},{"name":"Lying figure-4 contract-relax","hold":"3 x 10 sec/side","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null}],"notes":[]}]},{"dow":"Saturday","title":"Row + test day","flow":"Row → Full-body flow → Test","sections":[{"kind":"row","title":"CONCEPT2 ROW: INTERVALS","meta":"","intro":["Warm up 5 min easy. Then alternate 2 min hard (effort 8 out of 10) / 1 min easy. Cool down 3 min."],"table":[["Start","8 rounds"],["When that's easy","10 rounds"],["Easy week","6 rounds"]],"notes":["Effort: Intervals."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"30 min","items":[{"name":"Pigeon pose (each side)","hold":"2-3 min","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Half split (each side)","hold":"2-3 min","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Seated straddle fold","hold":"2-3 min","steps":["Sit with legs straight and wide apart, toes up.","Sit tall (on a cushion if needed).","Walk your hands forward, hinge from your hips, back flat. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"2-3 min","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Thread-the-needle (each side)","hold":"2-3 min","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Deep squat hold","hold":"2-3 min","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null},{"name":"Bridge prep","hold":"2-3 min","steps":["Lie on your back, knees bent, feet flat near your bum.","Put your hands on the floor beside your ears, fingers pointing toward your shoulders.","Push through hands and feet to lift your hips and head off the floor (full bridge). Or just the top of your head down if that's as far as you get.","Hold for the time, lower gently."],"feel":"shoulders, front of body opening","dont":null}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm or pillows)","Middle split: hips from floor (cm or pillows)","Deep squat hold time","Bridge hold time","Barbell hip thrust: best weight x reps this week"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","hold":"2 min","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null},{"name":"Supine twist","hold":"1 min/side","steps":["On back, knees bent, let both knees fall to one side, shoulders stay down."],"feel":null,"dont":null},{"name":"Legs up the wall","hold":"5 min","steps":["Lie with bum near a wall and legs straight up it. Arms relaxed."],"feel":null,"dont":null},{"name":"Slow breathing","hold":"2 min","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null}],"notes":[]}]}]},{"n":6,"name":"Dance Strong","tagline":"Keep the heavy glute work, add power, balance and control for dancing.","info":[["Strength","4 sets unless noted"],["Stretch holds","3 min, 3 rounds. Full splits work. Active holds 10 sec."],["Goals","Full front and middle splits (or as close as your hips allow). Full bridge 30 sec. High, controlled leg lifts."],["Move to next plan","When this whole week feels easy, drop the weights and start Plan 7: Floor Foundations."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"4 sets unless noted","items":[{"name":"Barbell hip thrust, 3 sec squeeze","sets":"4 x 10","steps":["Barbell hip thrust set-up.","Drive up and hold a hard squeeze at the top for 3 full sec.","Lower slowly."],"feel":"bum","dont":"arch your lower back"},{"name":"Dumbbell Bulgarian split squat, 3 sec lowering","sets":"4 x 10/side","steps":["Dumbbell in each hand by your sides. Back foot on the couch.","Lower counting 3 slow seconds until the back knee nearly touches the floor.","Drive up through the front heel. All reps one side, then switch."],"feel":"thigh and bum","dont":"drop fast"},{"name":"Reverse lunge to knee drive","sets":"3 x 12/side","steps":["Stand tall.","Step one leg back into a reverse lunge, back knee near the floor.","Push through the front heel and drive the back knee up in front of you to hip height as you stand. Balance for a moment.","Go straight into the next rep. All reps one side, then switch."],"feel":"bum and thigh of the front leg, balance","dont":"rush; control the balance at the top"},{"name":"Barbell glute bridge pulses","sets":"3 x 30","steps":["Barbell glute bridge on the floor, padded bar in your hip crease.","Lift into the bridge.","Without coming all the way down, pulse your hips up and down a few cm, squeezing at the top each time."],"feel":"bum on fire","dont":"let your lower back take over"},{"name":"Side plank leg lift, 3 sec hold","sets":"3 x 10/side","steps":["Full side plank on elbow and feet.","Lift your top leg and hold it up for 3 sec, lower.","All reps one side, then switch."],"feel":"side of your bum","dont":"let your hips sag"},{"name":"Standing arabesque lift (hold wall)","sets":"3 x 12/side","steps":["Stand facing a wall, both hands on it, body tall.","Keep one leg straight and lift it straight back behind you, toes pointed.","Lift as high as you can without arching your lower back, hold 2 sec, lower.","All reps one side, then switch."],"feel":"bum of the lifting leg","dont":"crank your lower back to get height"}],"notes":[]},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"15 min","items":[{"name":"90/90 hip switches","hold":"15 reps, hands off the floor","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null},{"name":"Figure-4 (on back)","hold":"2 min/side","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null},{"name":"Pigeon pose","hold":"3 min/side","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Couch stretch","hold":"2 min/side","steps":["Kneel with your back to a couch. Put one knee on the floor right against the couch, with that shin and foot up the couch.","Step the other foot forward into a lunge.","Slowly lift your torso upright and squeeze the bum of the back leg. Hold, then switch."],"feel":"front of the back thigh and hip (strong)","dont":null},{"name":"Deep squat hold","hold":"3 min","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null}],"notes":[]}]},{"dow":"Tuesday","title":"Row","flow":"Row → Stretch","sections":[{"kind":"row","title":"CONCEPT2 ROW: STEADY","meta":"","intro":["Warm up 5 min easy."],"table":[["Every week","45 min"],["Easy week","35 min"]],"notes":["Effort: Moderate. 20-22 strokes/min, damper 3-5."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"20 min","items":[{"name":"Standing forward fold","hold":"2 min","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null},{"name":"Heel-on-couch hamstring stretch","hold":"3 min/side","steps":["Stand facing a couch or stair. Put one heel on it, leg straight, toes up.","Hips facing forward, back flat.","Hinge forward from your hips (not by rounding your back) until you feel a stretch. Hold, then switch."],"feel":"back of the raised thigh","dont":null},{"name":"Couch stretch","hold":"2 min/side","steps":["Kneel with your back to a couch. Put one knee on the floor right against the couch, with that shin and foot up the couch.","Step the other foot forward into a lunge.","Slowly lift your torso upright and squeeze the bum of the back leg. Hold, then switch."],"feel":"front of the back thigh and hip (strong)","dont":null},{"name":"Front split","hold":"3 min/side","steps":["Start in a half split. Keep one book or a cushion under your front thigh if you need it.","Slide your front heel forward and back knee back until you're as low as you can go, hips square.","Hands on the floor or books beside you. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Standing split","hold":"60 sec/side","steps":["Stand facing the floor in a forward fold, hands on the floor or on books.","Lift one leg straight up behind you as high as it will go, hips as square as you can.","Hold, then switch."],"feel":"back of the standing thigh, front of the lifted hip","dont":null},{"name":"Active leg raise","hold":"8 x 10 sec/side","steps":["Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null},{"name":"Standing front leg hold","hold":"6 x 10 sec/side","steps":["Stand tall next to a wall, hand on it.","Lift your outside leg straight in front of you as high as you can, using only your leg muscles.","Hold for the time, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of thigh working, back of thigh stretching","dont":null}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + core","flow":"Warm-up → Upper + core → Stretch","sections":[{"kind":"strength","title":"UPPER + CORE","meta":"4 rounds (do 1-6 in a row = 1 round)","items":[{"name":"Full push-up, 3 sec lowering","sets":"12","steps":["Full push-up position (or knees if needed), body straight.","Lower your chest to just above the floor counting 3 slow seconds.","Push back up."],"feel":"chest, arms, core","dont":"let hips sag"},{"name":"One-arm dumbbell row, 3 sec lowering","sets":"12/side","steps":["Hand and knee on the couch, dumbbell in the other hand.","Pull the dumbbell up to your hip, squeeze your shoulder blade.","Lower counting 3 slow seconds. All reps one side, then switch."],"feel":"upper/middle back","dont":"twist or shrug"},{"name":"Reverse snow angel","sets":"15","steps":["Lie face down, forehead on a folded towel, arms by your sides, palms down.","Lift your arms a few cm off the floor and squeeze your shoulder blades together.","Keeping arms off the floor and straight, sweep them out to the sides and up overhead (like a snow angel).","Sweep them back down to your sides. That's 1 rep."],"feel":"upper back, back of shoulders (great for posture, doesn't bulk)","dont":"shrug your shoulders up"},{"name":"Hollow rocks","sets":"15","steps":["Get into a hollow hold: on your back, lower back pressed down, arms overhead, legs straight and lifted.","Keeping that banana shape locked, gently rock back and forth like a rocking chair.","Each rock forward and back = 1 rep."],"feel":"abs","dont":"break the shape; if it breaks, go back to holds"},{"name":"Star side plank","sets":"20 sec/side","steps":["Side plank on your hand (arm straight) or elbow, feet stacked.","Lift your top leg up and reach your top arm to the ceiling, making a star.","Hold for the time, then switch."],"feel":"side of your bum and waist","dont":"let your hips sag"},{"name":"Reverse plank leg lift","sets":"8/side","steps":["Get into a reverse plank: sit, hands behind your hips, lift your body into a straight line.","Keeping hips up, lift one straight leg a little, hold 1 sec, lower.","Alternate legs. Each lift = 1 rep on that side."],"feel":"bum, hamstrings, back of shoulders","dont":"let your hips sag"}],"notes":["Upper body stays light on purpose: posture and a tight waist, no bulk. Use light dumbbells for rows."]},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"15 min","items":[{"name":"Cat-cow","hold":"15 reps","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null},{"name":"Thread-the-needle","hold":"90 sec/side","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Sphinx or cobra","hold":"90 sec","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null},{"name":"Doorway chest opener","hold":"90 sec/side","steps":["Stand in a doorway. Put your forearm on the frame, elbow at shoulder height.","Step forward with the same-side foot until you feel a stretch across your chest.","Hold, then switch."],"feel":"chest and front of shoulder","dont":null},{"name":"Puppy pose","hold":"2 min","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null},{"name":"Full bridge hold","hold":"3 x 30 sec","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null},{"name":"Supine twist","hold":"90 sec/side","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"4 sets unless noted","items":[{"name":"Pistol squat (hold door frame)","sets":"4 x 5/side","steps":["Stand on one leg, holding a door frame with one or both hands. Free leg straight out in front.","Squat down on the standing leg as low as you can, heel down.","Stand back up, using the frame as little as possible. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the knee cave in"},{"name":"Shrimp squat with dumbbell","sets":"3 x 6/side","steps":["Same as shrimp squat, holding a light dumbbell in your free hand, reaching it forward for balance.","Hold the back foot, lower the back knee to the cushion, stand back up.","All reps one side, then switch."],"feel":"thigh and bum","dont":"let the knee cave in"},{"name":"Squat jump (soft landing)","sets":"3 x 8","steps":["Stand with feet shoulder-width.","Squat down to about half depth, then jump straight up.","Land softly on the balls of your feet, sinking straight into the next squat. Quiet landings."],"feel":"thighs, bum, power","dont":"land with straight knees or loudly"},{"name":"Skater hops","sets":"3 x 10/side","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged"},{"name":"Single-leg RDL to knee drive","sets":"3 x 10/side","steps":["Stand on one leg.","Hinge forward into a single-leg RDL, back leg lifting.","Stand up and drive the back knee up in front of you to hip height. Balance 1 sec.","That's 1 rep. All reps one side, then switch."],"feel":"bum, hamstring, balance","dont":"rush"},{"name":"Single-leg calf raise off a stair, with dumbbell","sets":"3 x 20/side","steps":["Dumbbell in the hand on the same side as your standing leg. Stand on one foot on the edge of a stair, heel hanging off, other hand on the rail.","Lower your heel below the step, then rise as high as you can.","All reps one side, then switch."],"feel":"calf","dont":"bounce"}],"notes":[]},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"15-20 min","items":[{"name":"Butterfly","hold":"3 min","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"3 min","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Pancake fold","hold":"3 min","steps":["Sit with legs wide in a straddle, toes up. Sit on a cushion if your back rounds.","Tilt your pelvis forward (stick your bum out) and walk your hands forward.","Lower your chest toward the floor with a flat back. Hold."],"feel":"inner thighs, back of thighs","dont":null},{"name":"Middle split","hold":"3 min","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null},{"name":"Cossack squat hold","hold":"30 sec x 4/side","steps":["Stand with feet very wide.","Sit down into one side (bent knee), other leg straight with toes up.","Hold the low position for the time, then switch sides. Hold a chair if needed."],"feel":"inner thigh of the straight leg","dont":null},{"name":"Side leg hold","hold":"6 x 10 sec/side","steps":["Stand tall, side-on to a wall, hand on it.","Lift your outside leg straight out to the side as high as you can, toes forward.","Hold for the time, lower. Do all reps, then switch."],"feel":"side of hip working, inner thigh stretching","dont":null}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"4 sets unless noted","items":[{"name":"Barbell Romanian deadlift","sets":"4 x 8 (heavy)","steps":["Stand holding the bar in front of your thighs, hands just outside your legs, feet hip-width. (First rep: deadlift it up off the floor with a flat back.)","Soft knees. Push your hips back and slide the bar down your thighs, keeping it touching your legs and your back flat.","Go until you feel a strong stretch in the back of your thighs (usually just below the knee).","Squeeze your bum and push your hips forward to stand up."],"feel":"back of thighs and bum","dont":"round your back or let the bar drift away from your legs"},{"name":"Single-leg dumbbell hip thrust, 1.5 reps","sets":"4 x 10/side","steps":["Upper back on the couch, dumbbell across your hips, one foot down.","Up all the way, down halfway, up all the way, then down fully. That's 1 rep.","All reps one side, then switch."],"feel":"bum of the working leg burning","dont":"let the hips tilt"},{"name":"Single-leg slider hamstring curl","sets":"3 x 10/side","steps":["Lie on your back, one heel on a towel on a smooth floor, other leg lifted.","Lift your hips up into a bridge.","Pull the heel in toward your bum, then slowly slide it back out. Hips stay up.","All reps one side, then switch."],"feel":"back of thigh","dont":"let your hips sag"},{"name":"Nordic-style hamstring lower, 5 sec lowering","sets":"3 x 8","steps":["Kneel on a cushion, ankles hooked under a heavy couch.","Body straight from knees to head.","Lower forward counting 5 slow seconds, catch yourself with your hands, push back up."],"feel":"back of thighs, very hard","dont":"bend at the hips"},{"name":"Copenhagen plank (foot on couch)","sets":"3 x 25 sec/side","steps":["Same as the knee version, but your top foot/ankle rests on the couch (harder, longer lever).","Elbow under shoulder, lift hips so body is straight.","Hold for the time, then switch."],"feel":"inner thigh","dont":"let your hips sag"},{"name":"Relevé balance (single leg, on toes)","sets":"3 x 20 sec/side","steps":["Stand on one leg, near a wall.","Rise up onto the ball of that foot (heel high) and hold your balance, other foot at your ankle or knee.","Hold for the time, then switch."],"feel":"calf, ankle, outer hip","dont":"sink your heel"}],"notes":[]},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"20 min","items":[{"name":"Front split","hold":"3 min/side","steps":["Start in a half split. Keep one book or a cushion under your front thigh if you need it.","Slide your front heel forward and back knee back until you're as low as you can go, hips square.","Hands on the floor or books beside you. Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null},{"name":"Middle split","hold":"3 min","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null},{"name":"Standing split","hold":"90 sec/side","steps":["Stand facing the floor in a forward fold, hands on the floor or on books.","Lift one leg straight up behind you as high as it will go, hips as square as you can.","Hold, then switch."],"feel":"back of the standing thigh, front of the lifted hip","dont":null},{"name":"Pancake fold","hold":"2 min","steps":["Sit with legs wide in a straddle, toes up. Sit on a cushion if your back rounds.","Tilt your pelvis forward (stick your bum out) and walk your hands forward.","Lower your chest toward the floor with a flat back. Hold."],"feel":"inner thighs, back of thighs","dont":null},{"name":"Lying figure-4 contract-relax","hold":"3 x 10 sec/side","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null}],"notes":[]}]},{"dow":"Saturday","title":"Row + test day","flow":"Row → Full-body flow → Test","sections":[{"kind":"row","title":"CONCEPT2 ROW: INTERVALS","meta":"","intro":["Warm up 5 min easy. Then alternate 1 min hard (effort 8-9 out of 10) / 1 min easy. Cool down 3 min."],"table":[["Start","10 rounds"],["When that's easy","12 rounds"],["Easy week","8 rounds"]],"notes":["Effort: Intervals. Short and sharp, like a dance class."],"tableHead":"Row"},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"30 min","items":[{"name":"Pigeon pose (each side)","hold":"3 min","steps":["Start on hands and knees. Bring your right knee forward behind your right wrist, right shin across your body.","Slide your left leg straight back. Keep hips square (put a cushion under your right hip if it's high).","Walk your hands forward and fold over the front leg as far as is comfortable. Hold, then switch.","Knees complain? Do figure-4 instead: sit on a couch, ankle on opposite knee, lean forward."],"feel":"outside of front hip/bum","dont":null},{"name":"Half split (each side)","hold":"3 min","steps":["Kneel in a low lunge with your right foot forward.","Shift your hips back over your back knee and straighten your front leg, toes pointing up.","Hands on the floor or books either side. Back flat, fold forward a little. Hold, then switch."],"feel":"back of the front thigh","dont":null},{"name":"Seated straddle fold","hold":"3 min","steps":["Sit with legs straight and wide apart, toes up.","Sit tall (on a cushion if needed).","Walk your hands forward, hinge from your hips, back flat. Hold."],"feel":"inner thighs","dont":null},{"name":"Frog stretch","hold":"3 min","steps":["Get on hands and knees (cushions under knees).","Slide your knees out wide, feet out to the sides in line with your knees, ankles flexed.","Lower onto your forearms and gently push your hips back. Hold."],"feel":"inner thighs, groin","dont":null},{"name":"Thread-the-needle (each side)","hold":"3 min","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null},{"name":"Deep squat hold","hold":"3 min","steps":["Stand with feet a bit wider than shoulders, toes out.","Sit all the way down into the deepest squat you can, heels down (heels on a folded towel if they lift).","Hands together at your chest and use your elbows to push your knees out. Keep chest up and hold."],"feel":"hips, inner thighs, ankles","dont":null},{"name":"Bridge prep","hold":"3 min","steps":["Lie on your back, knees bent, feet flat near your bum.","Put your hands on the floor beside your ears, fingers pointing toward your shoulders.","Push through hands and feet to lift your hips and head off the floor (full bridge). Or just the top of your head down if that's as far as you get.","Hold for the time, lower gently."],"feel":"shoulders, front of body opening","dont":null}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm or pillows)","Middle split: hips from floor (cm or pillows)","Deep squat hold time","Bridge hold time","Barbell hip thrust: best weight x reps this week"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","hold":"2 min","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null},{"name":"Supine twist","hold":"1 min/side","steps":["On back, knees bent, let both knees fall to one side, shoulders stay down."],"feel":null,"dont":null},{"name":"Legs up the wall","hold":"5 min","steps":["Lie with bum near a wall and legs straight up it. Arms relaxed."],"feel":null,"dont":null},{"name":"Slow breathing","hold":"2 min","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null}],"notes":[]}]}]},{"n":7,"name":"Floor Foundations","tagline":"The weights are gone. Single-leg bridging, slow lunges, pike push-ups and L-sit tucks keep your glutes and legs working hard.","bw":true,"info":[["Strength","Single-leg and slow tempo work, 3-4 sets. It feels easier than the barbell but sets end close to failure. Bodyweight, a pull-up bar, resistance bands, ankle weights and parallettes."],["Lower-body sets","About 66 hard sets a week on Mon, Thu and Fri: 20 hip-extension (bridge, hinge, hamstring), 22 squat, lunge and jump, 24 side-hip and inner-thigh. Plus Tuesday jumps. When a set gets easy, go up a band or add ankle weight first, then make it slower."],["Stretch holds","1-3 min holds. Hands-on-floor splits, contract-relax on everything."],["Goals","Single-leg glute bridge 15 per side with a 3 sec squeeze. Pistol squat to 90 degrees, 4 per side. Pike push-up 8. L-sit tuck 20 sec. Front split hands on the floor, as low as your hips allow. Hip hinge: single-leg RDL 12 per side. Dead hang 30 sec."],["Time here","About 6-8 weeks for the lower body. Skills like handstand push-ups and planche can lag behind: move up when the legs and glutes feel easy, and keep practising the skill step you're on (each one has a \\"Can't yet?\\" option)."],["Move to next plan","After about 6-8 weeks, when this whole week feels easy."],["Safety","Warm up first, never bounce in a stretch, stay at strong-but-comfortable. Pain, pinching or numbness means back off a step. Jumps: soft landings, clear floor. Handstand work: clear space, learn a cartwheel exit, stop if neck, wrists or shoulders hurt. Pull-up bar: check it is fixed solidly before every session and never jump to grab it."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"3-4 sets unless noted","items":[{"name":"Single-leg glute bridge, 3 sec squeeze","steps":["Lie on your back, knees bent, feet flat.","Lift one foot off the floor and hold that knee up toward your chest (or keep that leg straight in line with the other thigh).","Push through the heel of the foot on the floor and lift your hips until straight.","Squeeze 1-2 sec at the top, lower slowly. Do all reps, then switch legs."],"feel":"bum of the working leg","dont":"let the hips tilt; keep both hip bones level","sets":"4 x 12/side, 3s squeeze"},{"name":"Forward-lean split squat","steps":["Stand in a long split stance, back heel up, feet hip-width apart like train tracks.","Lean your chest forward about 30-45 degrees with a flat back, hands on your hips or reaching forward.","Lower until your back knee lightly touches the floor and you feel a deep stretch in the bum of your front leg. Hold the pause.","Drive through the front heel to come up, stopping just short of standing so the glute keeps working. All reps one side, then switch."],"feel":"deep stretch and burn in the bum of the front leg","dont":"let the front knee cave in or the front heel lift","sets":"3 x 12/side, 2s pause"},{"name":"Banded glute bridge","steps":["Loop a long resistance band over your hip crease and pin each end to the floor under your hands.","Feet flat, hip-width apart, heels about a hand-length from your bum.","Drive through your heels and lift your hips into the band until your body is straight from knees to shoulders. Squeeze hard at the top.","Lower slowly. Go up a band when every set feels easy."],"feel":"bum, working hard against the band at the top","dont":"arch your lower back to get higher","sets":"3 x 15, 2s squeeze"},{"name":"Reverse lunge to knee drive","steps":["Stand tall.","Step one leg back into a reverse lunge, back knee near the floor.","Push through the front heel and drive the back knee up in front of you to hip height as you stand. Balance for a moment.","Go straight into the next rep. All reps one side, then switch."],"feel":"bum and thigh of the front leg, balance","dont":"rush; control the balance at the top","sets":"4 x 12/side, 3s lowering"},{"name":"Curtsy lunge","steps":["Hands together at your chest, feet hip-width.","Step one leg back and across, bending both knees into a deep curtsy, hips facing forward.","Push through the front heel to stand. All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"twist your hips","sets":"3 x 12/side"},{"name":"Banded frog pump, 2 sec pause","steps":["Loop a long band over your hips and pin the ends under your hands.","Same as frog pump: on your back, soles together, knees out wide, heels near your bum.","Lift your hips by squeezing your bum.","Hold and squeeze for 2 sec at the top, then lower."],"feel":"bum, especially the sides","dont":"arch your lower back","sets":"3 x 25"},{"name":"Fire hydrant + donkey kick combo, 2 sec hold (ankle weights)","steps":["Ankle weights on both legs.","On hands and knees.","Lift one bent leg out to the side and hold 2 sec. Bring it back.","Kick that foot up toward the ceiling and hold 2 sec. Bring it back. That's 1 rep.","All reps one side, then switch."],"feel":"all of your bum","dont":"arch your lower back","sets":"3 x 12/side"},{"name":"Side plank leg lift, 3 sec hold (ankle weights)","steps":["Ankle weight on your top leg.","Full side plank on elbow and feet.","Lift your top leg and hold it up for 3 sec, lower.","All reps one side, then switch."],"feel":"side of your bum","dont":"let your hips sag","sets":"3 x 12/side"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"about 15 min","items":[{"name":"90/90 hip switches","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null,"hold":"15 reps, hands off the floor"},{"name":"Figure-4 (on back)","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"2 min/side"},{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"2 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"2 min"}],"notes":[]}]},{"dow":"Tuesday","title":"Power + balance + front splits","flow":"Warm-up → Power + balance → Stretch","sections":[{"kind":"strength","title":"POWER + BALANCE","meta":"3 rounds, rest 60-90 sec between rounds. Quality over speed.","items":[{"name":"Squat jump (soft landing)","steps":["Stand with feet shoulder-width.","Squat down to about half depth, then jump straight up.","Land softly on the balls of your feet, sinking straight into the next squat. Quiet landings."],"feel":"thighs, bum, power","dont":"land with straight knees or loudly","sets":"6"},{"name":"Skater hops","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged","sets":"6/side"},{"name":"Relevé balance (single leg, on toes)","steps":["Stand on one leg, near a wall.","Rise up onto the ball of that foot (heel high) and hold your balance, other foot at your ankle or knee.","Hold for the time, then switch."],"feel":"calf, ankle, outer hip","dont":"sink your heel","sets":"20 sec/side"}],"notes":["Soft, quiet landings on a clear floor. Stop a move when your form fades. This and Thursday are your only jump days."],"bw":true},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"about 25 min","items":[{"name":"Standing forward fold","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null,"hold":"2 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"2 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"Front split (hands on the floor)","steps":["From a low lunge, slide the front heel forward and the back knee back, hips square.","Lower as far as feels strong but comfortable, hands on the floor beside you.","Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null,"hold":"2 min/side"},{"name":"Standing split (hands on the floor)","steps":["Stand and fold forward, hands on the floor.","Lift one leg straight up behind you as high as you can, hips square.","Hold, then switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Active leg raise","steps":["Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null,"hold":"8 x 10 sec/side"},{"name":"Standing front leg hold","steps":["Stand tall next to a wall, hand on it.","Lift your outside leg straight in front of you as high as you can, using only your leg muscles.","Hold for the time, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of thigh working, back of thigh stretching","dont":null,"hold":"6 x 10 sec/side"}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + skills + pull","flow":"Warm-up → Upper + skills → Pull → Stretch","sections":[{"kind":"strength","title":"UPPER + CORE","meta":"Straight sets, skills first: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Full push-up, 3 sec lowering","steps":["Full push-up position (or knees if needed), body straight.","Lower your chest to just above the floor counting 3 slow seconds.","Push back up."],"feel":"chest, arms, core","dont":"let hips sag","sets":"3-4 x up to 15"},{"name":"Pike push-up (parallettes)","steps":["Hands on the parallettes, so your head can drop lower than your hands.","Bend your elbows and lower the top of your head toward the floor between your hands.","Press back up until your arms are straight.","Can't yet? Downward-dog holds, then small bends."],"feel":"shoulders and triceps","dont":"flare your elbows wide or bounce","sets":"3-4 x up to 8"},{"name":"Reverse snow angel (floor)","steps":["Lie face down, arms by your sides, forehead slightly off the floor.","Lift your arms and sweep them overhead in a wide arc, then back.","Keep your legs and bum squeezed."],"feel":"upper back, posture muscles","dont":"crank your neck up","sets":"3 x 15"},{"name":"Hollow rocks (floor)","steps":["Lie on your back, arms overhead, lower back pressed into the floor.","Lift your shoulders and legs off the floor into a banana shape.","Rock gently back and forth, keeping the shape.","Can't yet? Hollow hold with knees bent."],"feel":"abs","dont":"let your lower back arch","sets":"3-4 x up to 20"},{"name":"L-sit (parallettes)","steps":["Sit between your parallettes, hands on the handles beside your hips.","Push down to lift your hips and straight legs off the floor.","Hold. Can't yet? Tuck your knees in."],"feel":"abs, hip flexors, triceps","dont":"shrug up to your ears","sets":"3-4 x up to 20 sec"},{"name":"Prone Y-T-W raise (floor)","steps":["Lie face down, forehead slightly off the floor.","Lift your arms into a Y, then a T, then a W, lowering between each.","One of each = 1 rep."],"feel":"upper back, rear shoulders","dont":"shrug up to your ears","sets":"3 x 10"},{"name":"Band pull-apart","steps":["Hold a light long band in front of your chest, hands shoulder-width, arms straight.","Pull the band apart by squeezing your shoulder blades together until it touches your chest.","Return slowly."],"feel":"upper back and the back of your shoulders","dont":"shrug or bend your elbows","sets":"3 x 15"}],"notes":["Upper-body volume stays modest on purpose: skill holds and slow reps build control and definition without bulky arms.","Y-T-W raises and snow angels keep your shoulders back and your posture tall. Pulling comes next."],"bw":true},{"kind":"strength","title":"PULL (BAR)","meta":"Straight sets: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Dead hang","steps":["Grab the bar overhand, hands shoulder-width apart.","Hang with straight arms, shoulders gently pulled down away from your ears, legs together.","Hold for the time and breathe.","Can't yet? Keep your toes lightly on a step or the floor and take some weight off."],"feel":"grip, shoulders, lats stretching","dont":"let your shoulders shrug up to your ears","sets":"3 x up to 30 sec"},{"name":"Scapular pull","steps":["Hang from the bar with straight arms.","Without bending your elbows, pull your shoulder blades down and back so your body rises a few cm.","Lower slowly. That's 1 rep."],"feel":"lower traps and lats","dont":"bend your arms","sets":"3 x 8"},{"name":"Pull-up negative","steps":["Jump or step up so your chin is over the bar.","Lower yourself as slowly as you can until your arms are straight.","Step down, reset, repeat."],"feel":"lats, upper back, arms","dont":"drop through the last part","sets":"3 x 3, 5s lowering"},{"name":"Hanging knee raise","steps":["Hang with straight arms, shoulders down.","Curl your knees up toward your chest, tucking your pelvis under.","Lower slowly without swinging.","Add ankle weights once 12 clean reps feel easy."],"feel":"lower abs","dont":"swing your legs for momentum","sets":"3 x up to 8"}],"notes":["Pulling stays at a moderate dose: enough for strong, healthy shoulders, a lifted posture and real pull-up strength, without building a wide V-shaped back."],"bw":true},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"about 20 min","items":[{"name":"Wrist circles and palm lifts","steps":["Kneel with palms flat, fingers forward, then back, then out. Lean gently back and forth.","Lift your palms, keep fingers down, then circle each wrist slowly.","Stay at a mild stretch, never force."],"feel":"wrists and forearms","dont":null,"hold":"2 min"},{"name":"Cat-cow","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null,"hold":"15 reps"},{"name":"Thread-the-needle","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"90 sec/side"},{"name":"Sphinx or cobra","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null,"hold":"90 sec"},{"name":"Clasped-hands chest opener (kneeling)","steps":["Kneel tall, clasp your hands behind your back.","Straighten your arms and lift them away from your back, chest open.","Hold."],"feel":"chest and front shoulders","dont":null,"hold":"90 sec"},{"name":"Puppy pose","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null,"hold":"2 min"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 30 sec"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"90 sec/side"}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"3-4 sets unless noted","items":[{"name":"Pistol squat","steps":["Stand on one leg, free leg straight out in front, arms reaching forward.","Squat down as low as you can control, heel down. Stop at 90 degrees if you can't go deeper yet.","Stand back up with no hands. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the knee cave in","sets":"3 x 4/side (stop at 90 degrees if needed)"},{"name":"Shrimp squat (floor)","steps":["Stand on one leg, hold the other foot behind you with the same-side hand.","Lower until your back knee gently touches the floor, torso leaning forward.","Stand back up. All reps one side, then switch."],"feel":"front thigh and bum","dont":"drop onto the knee","sets":"3 x 5/side"},{"name":"Deep reverse lunge, forward lean","steps":["Stand tall, then take a long step back and lower until your back knee nearly touches the floor.","Hinge your chest forward over the front thigh with a flat back, fingertips reaching toward the floor beside your front foot.","Pause at the bottom, then push through the front heel to stand. All reps one side, then switch."],"feel":"bum and back of the front thigh","dont":"take a short step or round your back","sets":"3 x 10/side, 2s pause"},{"name":"Cossack squat (bodyweight)","steps":["Feet very wide, toes slightly out.","Sit down into one side, other leg straight with toes up. Heel of the bent leg stays down.","Push back up and switch sides. Each side = 1 rep."],"feel":"bum and inner thighs","dont":"lift the heel of the bent leg","sets":"3 x 10/side"},{"name":"Squat jump (soft landing)","steps":["Stand with feet shoulder-width.","Squat down to about half depth, then jump straight up.","Land softly on the balls of your feet, sinking straight into the next squat. Quiet landings."],"feel":"thighs, bum, power","dont":"land with straight knees or loudly","sets":"3 x 8"},{"name":"Skater hops","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged","sets":"3 x 8/side"},{"name":"Single-leg calf raise (floor, slow)","steps":["Stand on one foot, fingertips on a wall for balance if needed.","Rise as high as you can: 3 sec up, 1 sec pause, 3 sec down.","All reps one side, then switch."],"feel":"calf","dont":"bounce","sets":"3 x 15/side"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"about 20 min","items":[{"name":"Butterfly","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null,"hold":"2 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"2 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Seated forward fold","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null,"hold":"2 min"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"2 min"},{"name":"Cossack squat hold (floor)","steps":["Feet very wide, sit into one side with the other leg straight, toes up.","Hold, chest tall, then switch.","Keep the bent-leg heel down."],"feel":"inner thigh, hip","dont":null,"hold":"30 sec x 4/side"},{"name":"Side leg hold","steps":["Stand tall, side-on to a wall, hand on it.","Lift your outside leg straight out to the side as high as you can, toes forward.","Hold for the time, lower. Do all reps, then switch."],"feel":"side of hip working, inner thigh stretching","dont":null,"hold":"6 x 10 sec/side"}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"3-4 sets unless noted","items":[{"name":"Single-leg RDL (arms reaching)","steps":["Stand on one leg, soft knee, arms reaching forward.","Hinge forward, back leg lifting in line with your body, until your torso is parallel to the floor.","Squeeze your bum to stand. All reps one side, then switch."],"feel":"back of thigh and bum","dont":"round your back or open your hips","sets":"4 x 12/side, 3s lowering"},{"name":"Deep curtsy lunge, bottom pulses","steps":["Step one leg back and across into a deep curtsy, back knee near the floor, chest leaning slightly forward.","Stay low and pulse up and down a few centimetres in the bottom half only.","Keep your hips facing forward the whole time. All reps one side, then switch."],"feel":"outer bum of the front leg burning in the stretch","dont":"come all the way up or twist your hips","sets":"3 x 12/side"},{"name":"Banded lateral walk","steps":["Put a mini band just above your knees (around your ankles is harder, around your feet is hardest).","Sit back into a quarter squat, chest up, feet hip-width apart.","Step sideways with control, keeping tension on the band the whole time. All steps one way, then come back."],"feel":"side of your bum burning","dont":"let your knees cave in or stand up tall","sets":"3 x 12 steps/side"},{"name":"Bridge walkout","steps":["Lie on your back in a bridge, hips high, feet flat.","Walk your heels out as far as you can control, then walk them back in. Hips stay high.","Out and back = 1 rep."],"feel":"back of thighs and bum","dont":"let your hips sag","sets":"3 x 10"},{"name":"Prone hip extension (ankle weights)","steps":["Ankle weights on both legs.","Lie face down, forehead on your hands, legs straight.","Squeeze your bum and lift one straight leg a few cm off the floor.","Lower slowly. All reps one side, then switch."],"feel":"bum","dont":"lift by arching your lower back; small lift is fine","sets":"3 x 15/side"},{"name":"Side plank bottom-leg lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Side plank on your forearm, top foot in front of you on the floor.","Lift your bottom leg up to meet the top leg and hold.","Lower. All reps one side, then switch."],"feel":"inner thigh, side of waist","dont":"let your hips sag","sets":"3 x 8/side"},{"name":"Lateral lunge to curtsy flow","steps":["Step out into a side lunge, sitting back into that hip.","Push off and swing the same leg back and across into a curtsy lunge.","Stand up. Side lunge + curtsy = 1 rep. All reps one side, then switch."],"feel":"bum, outer hips, inner thighs","dont":"rush","sets":"3 x 10/side"},{"name":"Relevé balance (single leg, on toes)","steps":["Stand on one leg, near a wall.","Rise up onto the ball of that foot (heel high) and hold your balance, other foot at your ankle or knee.","Hold for the time, then switch."],"feel":"calf, ankle, outer hip","dont":"sink your heel","sets":"3 x 30 sec/side"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"about 15 min","items":[{"name":"Front split (hands on the floor)","steps":["From a low lunge, slide the front heel forward and the back knee back, hips square.","Lower as far as feels strong but comfortable, hands on the floor beside you.","Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null,"hold":"2 min/side"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"2 min"},{"name":"Standing split (hands on the floor)","steps":["Stand and fold forward, hands on the floor.","Lift one leg straight up behind you as high as you can, hips square.","Hold, then switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Seated forward fold","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null,"hold":"2 min"},{"name":"Lying figure-4 contract-relax","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"3 x 10 sec/side"}],"notes":[]}]},{"dow":"Saturday","title":"Flexibility + test day","flow":"Warm-up → Bar practice → Full-body flow → Test","sections":[{"kind":"strength","title":"BAR PRACTICE","meta":"about 5-10 min, easy and crisp. Never to failure.","items":[{"name":"Dead hang","steps":["Grab the bar overhand, hands shoulder-width apart.","Hang with straight arms, shoulders gently pulled down away from your ears, legs together.","Hold for the time and breathe.","Can't yet? Keep your toes lightly on a step or the floor and take some weight off."],"feel":"grip, shoulders, lats stretching","dont":"let your shoulders shrug up to your ears","sets":"3 x up to 30 sec"},{"name":"Scapular pull","steps":["Hang from the bar with straight arms.","Without bending your elbows, pull your shoulder blades down and back so your body rises a few cm.","Lower slowly. That's 1 rep."],"feel":"lower traps and lats","dont":"bend your arms","sets":"2 x 8"}],"notes":["Short, frequent practice is how pull-ups come fastest."],"bw":true},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"about 15 min","items":[{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"2 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"2 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"2 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"2 min"},{"name":"Thread-the-needle (each side)","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"2 min"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"2 min"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 30 sec"}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm)","Middle split: hips from floor (cm)","Deep squat hold time","Full bridge hold time","Pistol squat: best clean reps per leg"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null,"hold":"2 min"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"1 min/side"},{"name":"Happy baby","steps":["Lie on your back, hold the outsides of your feet with knees wide.","Draw your knees toward your armpits and rock gently.","Hold."],"feel":"hips and lower back","dont":null,"hold":"2 min"},{"name":"Slow breathing","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null,"hold":"2 min"}],"notes":[]}]}]},{"n":8,"name":"Control","tagline":"Long-lever bridges, skater squats, archer push-ups and your first chest-to-wall handstand holds.","bw":true,"info":[["Strength","3-4 sets, slower lowering. Bodyweight, a pull-up bar, resistance bands, ankle weights and parallettes."],["Lower-body sets","About 73 hard sets a week on Mon, Thu and Fri: 24 hip-extension (bridge, hinge, hamstring), 23 squat, lunge and jump, 26 side-hip and inner-thigh. Plus Tuesday jumps. When a set gets easy, go up a band or add ankle weight first, then make it slower."],["Stretch holds","1-3 min holds. Wrist prep, first hands-off split holds, camel pose."],["Goals","Pistol squat 5 per side with a 3 sec lowering. Archer push-up 8. Chest-to-wall handstand 20 sec. Full bridge 40 sec. Prone Y-T-W raise 12. Pull-up negative 4 x 5 sec."],["Time here","About 6-8 weeks for the lower body. Skills like handstand push-ups and planche can lag behind: move up when the legs and glutes feel easy, and keep practising the skill step you're on (each one has a \\"Can't yet?\\" option)."],["Move to next plan","After about 6-8 weeks, when this whole week feels easy."],["Safety","Warm up first, never bounce in a stretch, stay at strong-but-comfortable. Pain, pinching or numbness means back off a step. Jumps: soft landings, clear floor. Handstand work: clear space, learn a cartwheel exit, stop if neck, wrists or shoulders hurt. Pull-up bar: check it is fixed solidly before every session and never jump to grab it."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"3-4 sets unless noted","items":[{"name":"Long-lever single-leg bridge","steps":["Lie on your back, one leg straight in the air, the other foot flat a long way from your hips.","Drive through that heel and lift your hips until your shoulders, hips and raised leg are in one line.","Lower slowly. All reps one side, then switch."],"feel":"bum and back of thigh","dont":"arch your lower back or twist your hips","sets":"4 x 12/side, 3s squeeze"},{"name":"Forward-lean split squat","steps":["Stand in a long split stance, back heel up, feet hip-width apart like train tracks.","Lean your chest forward about 30-45 degrees with a flat back, hands on your hips or reaching forward.","Lower until your back knee lightly touches the floor and you feel a deep stretch in the bum of your front leg. Hold the pause.","Drive through the front heel to come up, stopping just short of standing so the glute keeps working. All reps one side, then switch."],"feel":"deep stretch and burn in the bum of the front leg","dont":"let the front knee cave in or the front heel lift","sets":"3 x 12/side, 3s lowering + 2s pause"},{"name":"Banded glute bridge","steps":["Loop a long resistance band over your hip crease and pin each end to the floor under your hands.","Feet flat, hip-width apart, heels about a hand-length from your bum.","Drive through your heels and lift your hips into the band until your body is straight from knees to shoulders. Squeeze hard at the top.","Lower slowly. Go up a band when every set feels easy."],"feel":"bum, working hard against the band at the top","dont":"arch your lower back to get higher","sets":"3 x 15, 2s squeeze"},{"name":"Skater squat","steps":["Stand on one leg, other leg behind you, arms swinging forward.","Lower on the standing leg until your back knee gently taps the floor.","Stand without pushing off the back foot. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the front knee cave in","sets":"4 x 8/side, 3s lowering"},{"name":"Curtsy lunge","steps":["Hands together at your chest, feet hip-width.","Step one leg back and across, bending both knees into a deep curtsy, hips facing forward.","Push through the front heel to stand. All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"twist your hips","sets":"4 x 12/side, 2s pause"},{"name":"Single-leg glute bridge, 1.5 reps","steps":["Lie on your back, knees bent, feet flat.","Lift one foot off the floor and hold that knee up toward your chest (or keep that leg straight in line with the other thigh).","Push through the heel of the foot on the floor and lift your hips until straight.","Squeeze 1-2 sec at the top, lower slowly. Do all reps, then switch legs."],"feel":"bum of the working leg","dont":"let the hips tilt; keep both hip bones level","sets":"3 x 12/side, 1.5 reps"},{"name":"Fire hydrant + donkey kick combo, 2 sec hold (ankle weights)","steps":["Ankle weights on both legs.","On hands and knees.","Lift one bent leg out to the side and hold 2 sec. Bring it back.","Kick that foot up toward the ceiling and hold 2 sec. Bring it back. That's 1 rep.","All reps one side, then switch."],"feel":"all of your bum","dont":"arch your lower back","sets":"3 x 12/side"},{"name":"Side plank leg lift (on feet) (ankle weights)","steps":["Ankle weight on your top leg.","Get into a full side plank on your elbow and feet, hips up.","Lift your top leg as high as you can, then lower it.","All reps one side, then switch."],"feel":"side of your bum, side of waist","dont":"let your hips sag","sets":"3 x 12/side"},{"name":"Banded frog pump, 2 sec pause","steps":["Loop a long band over your hips and pin the ends under your hands.","Same as frog pump: on your back, soles together, knees out wide, heels near your bum.","Lift your hips by squeezing your bum.","Hold and squeeze for 2 sec at the top, then lower."],"feel":"bum, especially the sides","dont":"arch your lower back","sets":"3 x 25"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"about 20 min","items":[{"name":"90/90 hip switches","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null,"hold":"15 reps, hands off the floor"},{"name":"Figure-4 (on back)","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"2 min/side"},{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"2 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"King pigeon prep (hold your foot)","steps":["From pigeon, bend the back knee and reach back to hold that foot (or your shin).","Lift your chest and gently draw the foot toward your head.","Hold, then switch."],"feel":"front of the back thigh and hip, chest opening","dont":null,"hold":"60 sec/side"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"2 min"}],"notes":[]}]},{"dow":"Tuesday","title":"Power + balance + front splits","flow":"Warm-up → Power + balance → Stretch","sections":[{"kind":"strength","title":"POWER + BALANCE","meta":"3 rounds, rest 60-90 sec between rounds. Quality over speed.","items":[{"name":"Squat jump (soft landing)","steps":["Stand with feet shoulder-width.","Squat down to about half depth, then jump straight up.","Land softly on the balls of your feet, sinking straight into the next squat. Quiet landings."],"feel":"thighs, bum, power","dont":"land with straight knees or loudly","sets":"8"},{"name":"Skater hops","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged","sets":"8/side"},{"name":"Single-leg balance, eyes closed","steps":["Stand on one foot, slight bend in the knee.","Find your balance, then close your eyes.","Hold for the time. Stand near a wall in case you wobble."],"feel":"ankle and outer hip working hard","dont":"lock your knee","sets":"20 sec/side"}],"notes":["Soft, quiet landings on a clear floor. Stop a move when your form fades. This and Thursday are your only jump days."],"bw":true},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"about 30 min","items":[{"name":"Standing forward fold","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null,"hold":"2 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"2 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"Front split (hands on the floor)","steps":["From a low lunge, slide the front heel forward and the back knee back, hips square.","Lower as far as feels strong but comfortable, hands on the floor beside you.","Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null,"hold":"3 min/side"},{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"60 sec/side"},{"name":"Standing split (hands on the floor)","steps":["Stand and fold forward, hands on the floor.","Lift one leg straight up behind you as high as you can, hips square.","Hold, then switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Active leg raise","steps":["Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null,"hold":"8 x 12 sec/side"},{"name":"Standing front leg hold","steps":["Stand tall next to a wall, hand on it.","Lift your outside leg straight in front of you as high as you can, using only your leg muscles.","Hold for the time, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of thigh working, back of thigh stretching","dont":null,"hold":"6 x 12 sec/side"}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + skills + pull","flow":"Warm-up → Upper + skills → Pull → Stretch","sections":[{"kind":"strength","title":"UPPER + SKILLS","meta":"Straight sets, skills first: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Archer push-up","steps":["Full push-up position with hands very wide.","Lower toward one hand while the other arm stays straight out to the side.","Push back up, then lower to the other side. Each side = 1 rep.","Can't yet? Wide push-ups, shifting your weight side to side."],"feel":"chest and arm of the bent side","dont":"let your hips sag","sets":"3-4 x up to 8"},{"name":"Pike push-up (parallettes)","steps":["Hands on the parallettes, so your head can drop lower than your hands.","Bend your elbows and lower the top of your head toward the floor between your hands.","Press back up until your arms are straight.","Can't yet? Downward-dog holds, then small bends."],"feel":"shoulders and triceps","dont":"flare your elbows wide or bounce","sets":"3-4 x up to 10, 4s lowering"},{"name":"Chest-to-wall handstand hold","steps":["Start in a plank with your feet at a wall, hands about 30 cm from it.","Walk your feet up the wall and your hands in until your belly faces the wall, arms locked.","Push the floor away, squeeze bum and legs, hold.","Can't yet? Walk only part way up the wall and hold there."],"feel":"shoulders, core, whole-body line","dont":"let your ribs flare or your back arch","sets":"3-4 x up to 20 sec"},{"name":"L-sit (parallettes)","steps":["Sit between your parallettes, hands on the handles beside your hips.","Push down to lift your hips and straight legs off the floor.","Hold. Can't yet? Tuck your knees in."],"feel":"abs, hip flexors, triceps","dont":"shrug up to your ears","sets":"3-4 x up to 25 sec"},{"name":"Hollow rocks (floor)","steps":["Lie on your back, arms overhead, lower back pressed into the floor.","Lift your shoulders and legs off the floor into a banana shape.","Rock gently back and forth, keeping the shape.","Can't yet? Hollow hold with knees bent."],"feel":"abs","dont":"let your lower back arch","sets":"3-4 x up to 25"},{"name":"Prone Y-T-W raise (floor)","steps":["Lie face down, forehead slightly off the floor.","Lift your arms into a Y, then a T, then a W, lowering between each.","One of each = 1 rep."],"feel":"upper back, rear shoulders","dont":"shrug up to your ears","sets":"3 x 12"},{"name":"Band pull-apart","steps":["Hold a light long band in front of your chest, hands shoulder-width, arms straight.","Pull the band apart by squeezing your shoulder blades together until it touches your chest.","Return slowly."],"feel":"upper back and the back of your shoulders","dont":"shrug or bend your elbows","sets":"3 x 15"},{"name":"Reverse snow angel (floor)","steps":["Lie face down, arms by your sides, forehead slightly off the floor.","Lift your arms and sweep them overhead in a wide arc, then back.","Keep your legs and bum squeezed."],"feel":"upper back, posture muscles","dont":"crank your neck up","sets":"3 x 12"}],"notes":["Upper-body volume stays modest on purpose: skill holds and slow reps build control and definition without bulky arms.","Y-T-W raises and snow angels keep your shoulders back and your posture tall. Pulling comes next."],"bw":true},{"kind":"strength","title":"PULL (BAR)","meta":"Straight sets: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Dead hang","steps":["Grab the bar overhand, hands shoulder-width apart.","Hang with straight arms, shoulders gently pulled down away from your ears, legs together.","Hold for the time and breathe.","Can't yet? Keep your toes lightly on a step or the floor and take some weight off."],"feel":"grip, shoulders, lats stretching","dont":"let your shoulders shrug up to your ears","sets":"3 x up to 40 sec"},{"name":"Scapular pull","steps":["Hang from the bar with straight arms.","Without bending your elbows, pull your shoulder blades down and back so your body rises a few cm.","Lower slowly. That's 1 rep."],"feel":"lower traps and lats","dont":"bend your arms","sets":"3 x 10"},{"name":"Band-assisted pull-up","steps":["Loop a long band over the bar and pull one end through so it hangs in a loop.","Put one knee or foot in the loop, grab the bar overhand, hands just wider than your shoulders.","Pull your elbows down until your chin clears the bar, then lower with control. Use a lighter band as you get stronger."],"feel":"lats, upper back, arms","dont":"bounce out of the bottom","sets":"3 x up to 6"},{"name":"Pull-up negative","steps":["Jump or step up so your chin is over the bar.","Lower yourself as slowly as you can until your arms are straight.","Step down, reset, repeat."],"feel":"lats, upper back, arms","dont":"drop through the last part","sets":"4 x 4, 5s lowering"},{"name":"Hanging knee raise","steps":["Hang with straight arms, shoulders down.","Curl your knees up toward your chest, tucking your pelvis under.","Lower slowly without swinging.","Add ankle weights once 12 clean reps feel easy."],"feel":"lower abs","dont":"swing your legs for momentum","sets":"3 x up to 12"}],"notes":["Pulling stays at a moderate dose: enough for strong, healthy shoulders, a lifted posture and real pull-up strength, without building a wide V-shaped back."],"bw":true},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"about 20 min","items":[{"name":"Wrist circles and palm lifts","steps":["Kneel with palms flat, fingers forward, then back, then out. Lean gently back and forth.","Lift your palms, keep fingers down, then circle each wrist slowly.","Stay at a mild stretch, never force."],"feel":"wrists and forearms","dont":null,"hold":"2 min"},{"name":"Cat-cow","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null,"hold":"15 reps"},{"name":"Thread-the-needle","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"90 sec/side"},{"name":"Sphinx or cobra","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null,"hold":"90 sec"},{"name":"Clasped-hands chest opener (kneeling)","steps":["Kneel tall, clasp your hands behind your back.","Straighten your arms and lift them away from your back, chest open.","Hold."],"feel":"chest and front shoulders","dont":null,"hold":"90 sec"},{"name":"Puppy pose","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null,"hold":"2 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"60 sec"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 40 sec"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"90 sec/side"}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"3-4 sets unless noted","items":[{"name":"Pistol squat","steps":["Stand on one leg, free leg straight out in front, arms reaching forward.","Squat down as low as you can control, heel down. Stop at 90 degrees if you can't go deeper yet.","Stand back up with no hands. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the knee cave in","sets":"4 x 5/side, 3s lowering"},{"name":"Shrimp squat (floor)","steps":["Stand on one leg, hold the other foot behind you with the same-side hand.","Lower until your back knee gently touches the floor, torso leaning forward.","Stand back up. All reps one side, then switch."],"feel":"front thigh and bum","dont":"drop onto the knee","sets":"3 x 6/side"},{"name":"Deep reverse lunge, forward lean","steps":["Stand tall, then take a long step back and lower until your back knee nearly touches the floor.","Hinge your chest forward over the front thigh with a flat back, fingertips reaching toward the floor beside your front foot.","Pause at the bottom, then push through the front heel to stand. All reps one side, then switch."],"feel":"bum and back of the front thigh","dont":"take a short step or round your back","sets":"3 x 12/side, 2s pause"},{"name":"Cossack squat (bodyweight)","steps":["Feet very wide, toes slightly out.","Sit down into one side, other leg straight with toes up. Heel of the bent leg stays down.","Push back up and switch sides. Each side = 1 rep."],"feel":"bum and inner thighs","dont":"lift the heel of the bent leg","sets":"3 x 12/side, 2s pause"},{"name":"Jump lunge (split jump)","steps":["Start in a lunge, back knee low.","Jump up and switch legs in the air.","Land softly in the opposite lunge. Each landing = 1 rep."],"feel":"thighs, bum, power","dont":"land loudly","sets":"3 x 8/side"},{"name":"Skater hops","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged","sets":"3 x 8/side"},{"name":"Single-leg calf raise (floor, slow)","steps":["Stand on one foot, fingertips on a wall for balance if needed.","Rise as high as you can: 3 sec up, 1 sec pause, 3 sec down.","All reps one side, then switch."],"feel":"calf","dont":"bounce","sets":"3 x 15/side"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"about 20 min","items":[{"name":"Butterfly","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null,"hold":"2 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"2 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Straddle fold, chest to floor","steps":["Sit in a wide straddle, toes up.","Walk your hands forward and slowly lower your chest toward the floor.","Hold, breathing slowly."],"feel":"inner thighs, hamstrings","dont":null,"hold":"2 min"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Cossack squat hold (floor)","steps":["Feet very wide, sit into one side with the other leg straight, toes up.","Hold, chest tall, then switch.","Keep the bent-leg heel down."],"feel":"inner thigh, hip","dont":null,"hold":"30 sec x 4/side"},{"name":"Side leg hold","steps":["Stand tall, side-on to a wall, hand on it.","Lift your outside leg straight out to the side as high as you can, toes forward.","Hold for the time, lower. Do all reps, then switch."],"feel":"side of hip working, inner thigh stretching","dont":null,"hold":"6 x 12 sec/side"}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"3-4 sets unless noted","items":[{"name":"Single-leg RDL (arms reaching)","steps":["Stand on one leg, soft knee, arms reaching forward.","Hinge forward, back leg lifting in line with your body, until your torso is parallel to the floor.","Squeeze your bum to stand. All reps one side, then switch."],"feel":"back of thigh and bum","dont":"round your back or open your hips","sets":"4 x 12/side, 3s lowering"},{"name":"Deep curtsy lunge, bottom pulses","steps":["Step one leg back and across into a deep curtsy, back knee near the floor, chest leaning slightly forward.","Stay low and pulse up and down a few centimetres in the bottom half only.","Keep your hips facing forward the whole time. All reps one side, then switch."],"feel":"outer bum of the front leg burning in the stretch","dont":"come all the way up or twist your hips","sets":"3 x 15/side"},{"name":"Banded lateral walk","steps":["Put a mini band just above your knees (around your ankles is harder, around your feet is hardest).","Sit back into a quarter squat, chest up, feet hip-width apart.","Step sideways with control, keeping tension on the band the whole time. All steps one way, then come back."],"feel":"side of your bum burning","dont":"let your knees cave in or stand up tall","sets":"3 x 15 steps/side"},{"name":"Bridge walkout","steps":["Lie on your back in a bridge, hips high, feet flat.","Walk your heels out as far as you can control, then walk them back in. Hips stay high.","Out and back = 1 rep."],"feel":"back of thighs and bum","dont":"let your hips sag","sets":"4 x 10, 3s out"},{"name":"Prone hip extension (ankle weights)","steps":["Ankle weights on both legs.","Lie face down, forehead on your hands, legs straight.","Squeeze your bum and lift one straight leg a few cm off the floor.","Lower slowly. All reps one side, then switch."],"feel":"bum","dont":"lift by arching your lower back; small lift is fine","sets":"3 x 20/side"},{"name":"Side plank bottom-leg lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Side plank on your forearm, top foot in front of you on the floor.","Lift your bottom leg up to meet the top leg and hold.","Lower. All reps one side, then switch."],"feel":"inner thigh, side of waist","dont":"let your hips sag","sets":"3 x 10/side"},{"name":"Lateral lunge to curtsy flow","steps":["Step out into a side lunge, sitting back into that hip.","Push off and swing the same leg back and across into a curtsy lunge.","Stand up. Side lunge + curtsy = 1 rep. All reps one side, then switch."],"feel":"bum, outer hips, inner thighs","dont":"rush","sets":"4 x 10/side"},{"name":"Single-leg balance, eyes closed","steps":["Stand on one foot, slight bend in the knee.","Find your balance, then close your eyes.","Hold for the time. Stand near a wall in case you wobble."],"feel":"ankle and outer hip working hard","dont":"lock your knee","sets":"3 x 30 sec/side"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"about 20 min","items":[{"name":"Front split (hands on the floor)","steps":["From a low lunge, slide the front heel forward and the back knee back, hips square.","Lower as far as feels strong but comfortable, hands on the floor beside you.","Hold, then switch."],"feel":"back of front thigh, front of back hip","dont":null,"hold":"3 min/side"},{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"60 sec/side"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Standing split (hands on the floor)","steps":["Stand and fold forward, hands on the floor.","Lift one leg straight up behind you as high as you can, hips square.","Hold, then switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Seated forward fold","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null,"hold":"2 min"},{"name":"Lying figure-4 contract-relax","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"3 x 10 sec/side"}],"notes":[]}]},{"dow":"Saturday","title":"Flexibility + test day","flow":"Warm-up → Bar practice → Full-body flow → Test","sections":[{"kind":"strength","title":"BAR PRACTICE","meta":"about 5-10 min, easy and crisp. Never to failure.","items":[{"name":"Dead hang","steps":["Grab the bar overhand, hands shoulder-width apart.","Hang with straight arms, shoulders gently pulled down away from your ears, legs together.","Hold for the time and breathe.","Can't yet? Keep your toes lightly on a step or the floor and take some weight off."],"feel":"grip, shoulders, lats stretching","dont":"let your shoulders shrug up to your ears","sets":"3 x up to 40 sec"},{"name":"Pull-up negative","steps":["Jump or step up so your chin is over the bar.","Lower yourself as slowly as you can until your arms are straight.","Step down, reset, repeat."],"feel":"lats, upper back, arms","dont":"drop through the last part","sets":"2 x 3, 5s lowering"}],"notes":["Short, frequent practice is how pull-ups come fastest."],"bw":true},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"about 20 min","items":[{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"2 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"2 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"2 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"2 min"},{"name":"Thread-the-needle (each side)","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"2 min"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"2 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 40 sec"}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm)","Middle split: hips from floor (cm)","Deep squat hold time","Full bridge hold time","Pistol squat: best clean reps per leg"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null,"hold":"2 min"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"1 min/side"},{"name":"Happy baby","steps":["Lie on your back, hold the outsides of your feet with knees wide.","Draw your knees toward your armpits and rock gently.","Hold."],"feel":"hips and lower back","dont":null,"hold":"2 min"},{"name":"Slow breathing","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null,"hold":"2 min"}],"notes":[]}]}]},{"n":9,"name":"Power","tagline":"Wall handstand negatives, pseudo planche, jumps and deep backbends.","bw":true,"info":[["Strength","3-4 sets, jumps and pauses. Bodyweight, a pull-up bar, resistance bands, ankle weights and parallettes."],["Lower-body sets","About 80 hard sets a week on Mon, Thu and Fri: 25 hip-extension (bridge, hinge, hamstring), 29 squat, lunge and jump, 26 side-hip and inner-thigh. Plus Tuesday jumps. When a set gets easy, go up a band or add ankle weight first, then make it slower."],["Stretch holds","1-3 min holds. Active split lift-offs, bow pose, bridge walk-ins, needle scale."],["Goals","Wall handstand push-up negative 4 (5 sec lowering). Chest-to-wall handstand 40 sec. Pistol 6 per side. Reverse Nordic curl 8. Tuck jump 8. Your first strict pull-up."],["Time here","About 6-8 weeks for the lower body. Skills like handstand push-ups and planche can lag behind: move up when the legs and glutes feel easy, and keep practising the skill step you're on (each one has a \\"Can't yet?\\" option)."],["Move to next plan","After about 6-8 weeks, when this whole week feels easy."],["Safety","Warm up first, never bounce in a stretch, stay at strong-but-comfortable. Pain, pinching or numbness means back off a step. Jumps: soft landings, clear floor. Handstand work: clear space, learn a cartwheel exit, stop if neck, wrists or shoulders hurt. Pull-up bar: check it is fixed solidly before every session and never jump to grab it."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"3-4 sets unless noted","items":[{"name":"Long-lever single-leg bridge","steps":["Lie on your back, one leg straight in the air, the other foot flat a long way from your hips.","Drive through that heel and lift your hips until your shoulders, hips and raised leg are in one line.","Lower slowly. All reps one side, then switch."],"feel":"bum and back of thigh","dont":"arch your lower back or twist your hips","sets":"4 x 12/side, 5s lowering"},{"name":"Forward-lean split squat","steps":["Stand in a long split stance, back heel up, feet hip-width apart like train tracks.","Lean your chest forward about 30-45 degrees with a flat back, hands on your hips or reaching forward.","Lower until your back knee lightly touches the floor and you feel a deep stretch in the bum of your front leg. Hold the pause.","Drive through the front heel to come up, stopping just short of standing so the glute keeps working. All reps one side, then switch."],"feel":"deep stretch and burn in the bum of the front leg","dont":"let the front knee cave in or the front heel lift","sets":"4 x 10/side, 3s lowering + 2s pause"},{"name":"Banded glute bridge","steps":["Loop a long resistance band over your hip crease and pin each end to the floor under your hands.","Feet flat, hip-width apart, heels about a hand-length from your bum.","Drive through your heels and lift your hips into the band until your body is straight from knees to shoulders. Squeeze hard at the top.","Lower slowly. Go up a band when every set feels easy."],"feel":"bum, working hard against the band at the top","dont":"arch your lower back to get higher","sets":"4 x 15, 2s squeeze"},{"name":"Skater squat","steps":["Stand on one leg, other leg behind you, arms swinging forward.","Lower on the standing leg until your back knee gently taps the floor.","Stand without pushing off the back foot. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the front knee cave in","sets":"4 x 10/side, 3s lowering"},{"name":"Curtsy lunge","steps":["Hands together at your chest, feet hip-width.","Step one leg back and across, bending both knees into a deep curtsy, hips facing forward.","Push through the front heel to stand. All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"twist your hips","sets":"4 x 12/side, 3s lowering"},{"name":"Single-leg glute bridge, pulses","steps":["Lie on your back, knees bent, feet flat.","Lift one foot off the floor and hold that knee up toward your chest (or keep that leg straight in line with the other thigh).","Push through the heel of the foot on the floor and lift your hips until straight.","Squeeze 1-2 sec at the top, lower slowly. Do all reps, then switch legs."],"feel":"bum of the working leg","dont":"let the hips tilt; keep both hip bones level","sets":"3 x 20/side, pulses"},{"name":"Fire hydrant + donkey kick combo, 2 sec hold (ankle weights)","steps":["Ankle weights on both legs.","On hands and knees.","Lift one bent leg out to the side and hold 2 sec. Bring it back.","Kick that foot up toward the ceiling and hold 2 sec. Bring it back. That's 1 rep.","All reps one side, then switch."],"feel":"all of your bum","dont":"arch your lower back","sets":"3 x 12/side"},{"name":"Star side plank","steps":["Side plank on your hand (arm straight) or elbow, feet stacked.","Lift your top leg up and reach your top arm to the ceiling, making a star.","Hold for the time, then switch."],"feel":"side of your bum and waist","dont":"let your hips sag","sets":"3 x 25 sec/side"},{"name":"Banded frog pump, 2 sec pause","steps":["Loop a long band over your hips and pin the ends under your hands.","Same as frog pump: on your back, soles together, knees out wide, heels near your bum.","Lift your hips by squeezing your bum.","Hold and squeeze for 2 sec at the top, then lower."],"feel":"bum, especially the sides","dont":"arch your lower back","sets":"3 x 25"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"about 25 min","items":[{"name":"90/90 hip switches","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null,"hold":"15 reps, hands off the floor"},{"name":"Figure-4 (on back)","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"2 min/side"},{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"King pigeon prep (hold your foot)","steps":["From pigeon, bend the back knee and reach back to hold that foot (or your shin).","Lift your chest and gently draw the foot toward your head.","Hold, then switch."],"feel":"front of the back thigh and hip, chest opening","dont":null,"hold":"90 sec/side"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"}],"notes":[]}]},{"dow":"Tuesday","title":"Power + balance + front splits","flow":"Warm-up → Power + balance → Stretch","sections":[{"kind":"strength","title":"POWER + BALANCE","meta":"3 rounds, rest 60-90 sec between rounds. Quality over speed.","items":[{"name":"Tuck jump","steps":["Feet hip-width, quarter squat.","Jump straight up, pulling your knees toward your chest.","Land softly and go into the next one."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"5"},{"name":"Skater hops","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged","sets":"8/side"},{"name":"Relevé balance (single leg, on toes)","steps":["Stand on one leg, near a wall.","Rise up onto the ball of that foot (heel high) and hold your balance, other foot at your ankle or knee.","Hold for the time, then switch."],"feel":"calf, ankle, outer hip","dont":"sink your heel","sets":"30 sec/side"}],"notes":["Soft, quiet landings on a clear floor. Stop a move when your form fades. This and Thursday are your only jump days."],"bw":true},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"about 30 min","items":[{"name":"Standing forward fold","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null,"hold":"2 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"2 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"2 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"5 x 10 sec/side"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Active leg raise","steps":["Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null,"hold":"8 x 15 sec/side"},{"name":"Standing front leg hold","steps":["Stand tall next to a wall, hand on it.","Lift your outside leg straight in front of you as high as you can, using only your leg muscles.","Hold for the time, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of thigh working, back of thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + skills + pull","flow":"Warm-up → Upper + skills → Pull → Stretch","sections":[{"kind":"strength","title":"UPPER + SKILLS","meta":"Straight sets, skills first: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Wall handstand push-up negative","steps":["Walk up into a chest-to-wall handstand (belly to the wall), hands about 20 cm from it.","Bend your elbows and lower slowly for 5 sec until the top of your head lightly touches the floor.","Come down safely, rest, and walk up again for the next rep.","Can't yet? Pike push-ups with a 4 sec lowering."],"feel":"shoulders working very hard","dont":"drop fast or flare your elbows","sets":"3-4 x up to 4"},{"name":"Pseudo planche push-up (parallettes)","steps":["Push-up position with hands on the parallettes by your lower ribs.","Lean your shoulders forward past your hands, then lower and push back up.","Keep your body in one hard line.","Can't yet? Lean less, or do them with knees down."],"feel":"chest, front shoulders, core","dont":"let your hips pike up","sets":"3-4 x up to 10"},{"name":"Chest-to-wall handstand hold","steps":["Start in a plank with your feet at a wall, hands about 30 cm from it.","Walk your feet up the wall and your hands in until your belly faces the wall, arms locked.","Push the floor away, squeeze bum and legs, hold.","Can't yet? Walk only part way up the wall and hold there."],"feel":"shoulders, core, whole-body line","dont":"let your ribs flare or your back arch","sets":"3-4 x up to 40 sec"},{"name":"L-sit (parallettes)","steps":["Sit between your parallettes, hands on the handles beside your hips.","Push down to lift your hips and straight legs off the floor.","Hold. Can't yet? Tuck your knees in."],"feel":"abs, hip flexors, triceps","dont":"shrug up to your ears","sets":"3-4 x up to 30 sec"},{"name":"V-up","steps":["Lie on your back, arms overhead, legs straight.","Lift your arms and legs together and touch your toes in a V.","Lower with control."],"feel":"abs, hip flexors","dont":"swing with momentum","sets":"3-4 x up to 15"},{"name":"Prone Y-T-W raise (floor)","steps":["Lie face down, forehead slightly off the floor.","Lift your arms into a Y, then a T, then a W, lowering between each.","One of each = 1 rep."],"feel":"upper back, rear shoulders","dont":"shrug up to your ears","sets":"3 x 12"},{"name":"Band pull-apart","steps":["Hold a light long band in front of your chest, hands shoulder-width, arms straight.","Pull the band apart by squeezing your shoulder blades together until it touches your chest.","Return slowly."],"feel":"upper back and the back of your shoulders","dont":"shrug or bend your elbows","sets":"3 x 15"},{"name":"Reverse snow angel (floor)","steps":["Lie face down, arms by your sides, forehead slightly off the floor.","Lift your arms and sweep them overhead in a wide arc, then back.","Keep your legs and bum squeezed."],"feel":"upper back, posture muscles","dont":"crank your neck up","sets":"3 x 12"}],"notes":["Upper-body volume stays modest on purpose: skill holds and slow reps build control and definition without bulky arms.","Y-T-W raises and snow angels keep your shoulders back and your posture tall. Pulling comes next."],"bw":true},{"kind":"strength","title":"PULL (BAR)","meta":"Straight sets: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3-4 x up to 3"},{"name":"Pull-up negative","steps":["Jump or step up so your chin is over the bar.","Lower yourself as slowly as you can until your arms are straight.","Step down, reset, repeat."],"feel":"lats, upper back, arms","dont":"drop through the last part","sets":"2 x 3, 5s lowering"},{"name":"Scapular pull","steps":["Hang from the bar with straight arms.","Without bending your elbows, pull your shoulder blades down and back so your body rises a few cm.","Lower slowly. That's 1 rep."],"feel":"lower traps and lats","dont":"bend your arms","sets":"3 x 10"},{"name":"Hanging leg raise","steps":["Hang with straight arms, shoulders down.","Keep your legs straight and together and lift them to hip height.","Lower slowly without swinging.","Can't yet? Hanging knee raises."],"feel":"lower abs, hip flexors","dont":"swing","sets":"3 x up to 8"}],"notes":["Pulling stays at a moderate dose: enough for strong, healthy shoulders, a lifted posture and real pull-up strength, without building a wide V-shaped back."],"bw":true},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"about 25 min","items":[{"name":"Wrist circles and palm lifts","steps":["Kneel with palms flat, fingers forward, then back, then out. Lean gently back and forth.","Lift your palms, keep fingers down, then circle each wrist slowly.","Stay at a mild stretch, never force."],"feel":"wrists and forearms","dont":null,"hold":"2 min"},{"name":"Cat-cow","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null,"hold":"15 reps"},{"name":"Thread-the-needle","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"90 sec/side"},{"name":"Sphinx or cobra","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null,"hold":"90 sec"},{"name":"Clasped-hands chest opener (kneeling)","steps":["Kneel tall, clasp your hands behind your back.","Straighten your arms and lift them away from your back, chest open.","Hold."],"feel":"chest and front shoulders","dont":null,"hold":"90 sec"},{"name":"Puppy pose","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null,"hold":"2 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"60 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"60 sec"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 40 sec"},{"name":"Bridge walk-in (hands toward feet)","steps":["Get into a full bridge.","Walk your hands one small step toward your feet, pressing your chest forward over your hands.","Hold, then walk back. Lower by tucking your chin."],"feel":"shoulders, spine, front of hips","dont":null,"hold":"3 x 20 sec"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"90 sec/side"}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"3-4 sets unless noted","items":[{"name":"Pistol squat","steps":["Stand on one leg, free leg straight out in front, arms reaching forward.","Squat down as low as you can control, heel down. Stop at 90 degrees if you can't go deeper yet.","Stand back up with no hands. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the knee cave in","sets":"4 x 6/side, 3s lowering"},{"name":"Shrimp squat (floor)","steps":["Stand on one leg, hold the other foot behind you with the same-side hand.","Lower until your back knee gently touches the floor, torso leaning forward.","Stand back up. All reps one side, then switch."],"feel":"front thigh and bum","dont":"drop onto the knee","sets":"4 x 6/side, 3s lowering"},{"name":"Deep reverse lunge, forward lean","steps":["Stand tall, then take a long step back and lower until your back knee nearly touches the floor.","Hinge your chest forward over the front thigh with a flat back, fingertips reaching toward the floor beside your front foot.","Pause at the bottom, then push through the front heel to stand. All reps one side, then switch."],"feel":"bum and back of the front thigh","dont":"take a short step or round your back","sets":"4 x 10/side, 3s lowering"},{"name":"Reverse Nordic curl","steps":["Kneel tall, arms crossed or reaching forward.","Lean back from the knees as far as you can control, hips pushed forward.","Use your thighs to pull back up.","Can't yet? Lean back only a little and build the range slowly."],"feel":"front of thighs, long stretch","dont":"bend at the hips","sets":"3 x 8"},{"name":"Tuck jump","steps":["Feet hip-width, quarter squat.","Jump straight up, pulling your knees toward your chest.","Land softly and go into the next one."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"3 x 8"},{"name":"Skater hops","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged","sets":"3 x 8/side"},{"name":"Single-leg calf raise (floor, slow)","steps":["Stand on one foot, fingertips on a wall for balance if needed.","Rise as high as you can: 3 sec up, 1 sec pause, 3 sec down.","All reps one side, then switch."],"feel":"calf","dont":"bounce","sets":"3 x 15/side"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"about 25 min","items":[{"name":"Butterfly","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null,"hold":"2 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Straddle fold, chest to floor","steps":["Sit in a wide straddle, toes up.","Walk your hands forward and slowly lower your chest toward the floor.","Hold, breathing slowly."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Active straddle lift-offs","steps":["Sit in a wide straddle, hands on the floor in front of you.","Lift one straight leg a few cm using your leg muscles, hold, lower. Alternate.","Keep your back flat."],"feel":"inner thighs stretching, hips working","dont":null,"hold":"6 x 8 sec"},{"name":"Cossack squat hold (floor)","steps":["Feet very wide, sit into one side with the other leg straight, toes up.","Hold, chest tall, then switch.","Keep the bent-leg heel down."],"feel":"inner thigh, hip","dont":null,"hold":"30 sec x 4/side"},{"name":"Side leg hold","steps":["Stand tall, side-on to a wall, hand on it.","Lift your outside leg straight out to the side as high as you can, toes forward.","Hold for the time, lower. Do all reps, then switch."],"feel":"side of hip working, inner thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"3-4 sets unless noted","items":[{"name":"Single-leg RDL to knee drive","steps":["Stand on one leg.","Hinge forward into a single-leg RDL, back leg lifting.","Stand up and drive the back knee up in front of you to hip height. Balance 1 sec.","That's 1 rep. All reps one side, then switch."],"feel":"bum, hamstring, balance","dont":"rush","sets":"4 x 12/side"},{"name":"Deep curtsy lunge, bottom pulses","steps":["Step one leg back and across into a deep curtsy, back knee near the floor, chest leaning slightly forward.","Stay low and pulse up and down a few centimetres in the bottom half only.","Keep your hips facing forward the whole time. All reps one side, then switch."],"feel":"outer bum of the front leg burning in the stretch","dont":"come all the way up or twist your hips","sets":"3 x 20/side"},{"name":"Banded lateral walk","steps":["Put a mini band just above your knees (around your ankles is harder, around your feet is hardest).","Sit back into a quarter squat, chest up, feet hip-width apart.","Step sideways with control, keeping tension on the band the whole time. All steps one way, then come back."],"feel":"side of your bum burning","dont":"let your knees cave in or stand up tall","sets":"3 x 15 steps/side, band at ankles"},{"name":"Bridge walkout","steps":["Lie on your back in a bridge, hips high, feet flat.","Walk your heels out as far as you can control, then walk them back in. Hips stay high.","Out and back = 1 rep."],"feel":"back of thighs and bum","dont":"let your hips sag","sets":"4 x 12, 3s out"},{"name":"Side-lying inner thigh lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Lie on your side, top leg bent with the foot in front, bottom leg straight.","Lift the bottom leg up toward the top leg, 2 sec up and 2 sec down.","All reps one side, then switch."],"feel":"inner thigh","dont":"roll your hips back","sets":"3 x 12/side"},{"name":"Side plank bottom-leg lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Side plank on your forearm, top foot in front of you on the floor.","Lift your bottom leg up to meet the top leg and hold.","Lower. All reps one side, then switch."],"feel":"inner thigh, side of waist","dont":"let your hips sag","sets":"3 x 12/side"},{"name":"Lateral lunge to curtsy flow","steps":["Step out into a side lunge, sitting back into that hip.","Push off and swing the same leg back and across into a curtsy lunge.","Stand up. Side lunge + curtsy = 1 rep. All reps one side, then switch."],"feel":"bum, outer hips, inner thighs","dont":"rush","sets":"4 x 12/side"},{"name":"Relevé balance (single leg, on toes)","steps":["Stand on one leg, near a wall.","Rise up onto the ball of that foot (heel high) and hold your balance, other foot at your ankle or knee.","Hold for the time, then switch."],"feel":"calf, ankle, outer hip","dont":"sink your heel","sets":"3 x 40 sec/side"},{"name":"Prone hip extension (ankle weights)","steps":["Ankle weights on both legs.","Lie face down, forehead on your hands, legs straight.","Squeeze your bum and lift one straight leg a few cm off the floor.","Lower slowly. All reps one side, then switch."],"feel":"bum","dont":"lift by arching your lower back; small lift is fine","sets":"3 x 12/side, 3s hold"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"about 15 min","items":[{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"2 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"5 x 10 sec/side"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Seated forward fold","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null,"hold":"2 min"},{"name":"Lying figure-4 contract-relax","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"3 x 10 sec/side"}],"notes":[]}]},{"dow":"Saturday","title":"Flexibility + test day","flow":"Warm-up → Bar practice → Full-body flow → Test","sections":[{"kind":"strength","title":"BAR PRACTICE","meta":"about 5-10 min, easy and crisp. Never to failure.","items":[{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3 easy sets of half your best"},{"name":"Dead hang","steps":["Grab the bar overhand, hands shoulder-width apart.","Hang with straight arms, shoulders gently pulled down away from your ears, legs together.","Hold for the time and breathe.","Can't yet? Keep your toes lightly on a step or the floor and take some weight off."],"feel":"grip, shoulders, lats stretching","dont":"let your shoulders shrug up to your ears","sets":"2 x up to 45 sec"}],"notes":["Short, frequent practice is how pull-ups come fastest."],"bw":true},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"about 25 min","items":[{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Thread-the-needle (each side)","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"3 min"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"90 sec"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 40 sec"}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm)","Middle split: hips from floor (cm)","Deep squat hold time","Full bridge hold time","Pistol squat: best clean reps per leg"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null,"hold":"2 min"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"1 min/side"},{"name":"Happy baby","steps":["Lie on your back, hold the outsides of your feet with knees wide.","Draw your knees toward your armpits and rock gently.","Hold."],"feel":"hips and lower back","dont":null,"hold":"2 min"},{"name":"Slow breathing","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null,"hold":"2 min"}],"notes":[]}]}]},{"n":10,"name":"Goddess","tagline":"Short-range wall handstand push-ups, 5-sec pistols and shrimps, long-lever bridges and real jump power.","bw":true,"info":[["Strength","3-4 sets, near-max tempo. Bodyweight, a pull-up bar, resistance bands, ankle weights and parallettes."],["Lower-body sets","About 83 hard sets a week on Mon, Thu and Fri: 25 hip-extension (bridge, hinge, hamstring), 30 squat, lunge and jump, 28 side-hip and inner-thigh. Plus Tuesday jumps. When a set gets easy, go up a band or add ankle weight first, then make it slower."],["Stretch holds","1-3 min holds. Active split lift-offs, needle scale, deep backbends."],["Goals","Wall handstand push-up (short range) 5. Pistol 8 per side with a 5 sec lowering. Back-to-wall handstand 30 sec. L-sit 40 sec. Full splits hands off the floor, or as close as your hips allow. Single-leg bridge hold 40 sec per side. Pull-ups 5."],["Time here","About 6-8 weeks for the lower body. Skills like handstand push-ups and planche can lag behind: move up when the legs and glutes feel easy, and keep practising the skill step you're on (each one has a \\"Can't yet?\\" option)."],["Move to next plan","When you tick off the Goddess checklist, move on to Plan 11."],["Safety","Warm up first, never bounce in a stretch, stay at strong-but-comfortable. Pain, pinching or numbness means back off a step. Jumps: soft landings, clear floor. Handstand work: clear space, learn a cartwheel exit, stop if neck, wrists or shoulders hurt. Pull-up bar: check it is fixed solidly before every session and never jump to grab it."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"3-4 sets unless noted","items":[{"name":"Long-lever single-leg bridge","steps":["Lie on your back, one leg straight in the air, the other foot flat a long way from your hips.","Drive through that heel and lift your hips until your shoulders, hips and raised leg are in one line.","Lower slowly. All reps one side, then switch."],"feel":"bum and back of thigh","dont":"arch your lower back or twist your hips","sets":"4 x 12/side, 1.5 reps"},{"name":"Forward-lean split squat","steps":["Stand in a long split stance, back heel up, feet hip-width apart like train tracks.","Lean your chest forward about 30-45 degrees with a flat back, hands on your hips or reaching forward.","Lower until your back knee lightly touches the floor and you feel a deep stretch in the bum of your front leg. Hold the pause.","Drive through the front heel to come up, stopping just short of standing so the glute keeps working. All reps one side, then switch."],"feel":"deep stretch and burn in the bum of the front leg","dont":"let the front knee cave in or the front heel lift","sets":"4 x 10/side, 1.5 reps"},{"name":"Banded glute bridge","steps":["Loop a long resistance band over your hip crease and pin each end to the floor under your hands.","Feet flat, hip-width apart, heels about a hand-length from your bum.","Drive through your heels and lift your hips into the band until your body is straight from knees to shoulders. Squeeze hard at the top.","Lower slowly. Go up a band when every set feels easy."],"feel":"bum, working hard against the band at the top","dont":"arch your lower back to get higher","sets":"4 x 12, 3s squeeze"},{"name":"Skater squat","steps":["Stand on one leg, other leg behind you, arms swinging forward.","Lower on the standing leg until your back knee gently taps the floor.","Stand without pushing off the back foot. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the front knee cave in","sets":"4 x 12/side, 5s lowering"},{"name":"Curtsy lunge","steps":["Hands together at your chest, feet hip-width.","Step one leg back and across, bending both knees into a deep curtsy, hips facing forward.","Push through the front heel to stand. All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"twist your hips","sets":"4 x 10/side, 1.5 reps"},{"name":"Single-leg glute bridge, hold","steps":["Lie on your back, knees bent, feet flat.","Lift one foot off the floor and hold that knee up toward your chest (or keep that leg straight in line with the other thigh).","Push through the heel of the foot on the floor and lift your hips until straight.","Squeeze 1-2 sec at the top, lower slowly. Do all reps, then switch legs."],"feel":"bum of the working leg","dont":"let the hips tilt; keep both hip bones level","sets":"3 x 40 sec/side, hold"},{"name":"Fire hydrant + donkey kick combo, 2 sec hold (ankle weights)","steps":["Ankle weights on both legs.","On hands and knees.","Lift one bent leg out to the side and hold 2 sec. Bring it back.","Kick that foot up toward the ceiling and hold 2 sec. Bring it back. That's 1 rep.","All reps one side, then switch."],"feel":"all of your bum","dont":"arch your lower back","sets":"3 x 12/side"},{"name":"Star side plank","steps":["Side plank on your hand (arm straight) or elbow, feet stacked.","Lift your top leg up and reach your top arm to the ceiling, making a star.","Hold for the time, then switch."],"feel":"side of your bum and waist","dont":"let your hips sag","sets":"3 x 35 sec/side"},{"name":"Banded frog pump, 2 sec pause","steps":["Loop a long band over your hips and pin the ends under your hands.","Same as frog pump: on your back, soles together, knees out wide, heels near your bum.","Lift your hips by squeezing your bum.","Hold and squeeze for 2 sec at the top, then lower."],"feel":"bum, especially the sides","dont":"arch your lower back","sets":"3 x 25"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"about 25 min","items":[{"name":"90/90 hip switches","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null,"hold":"15 reps, hands off the floor"},{"name":"Figure-4 (on back)","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"2 min/side"},{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"King pigeon prep (hold your foot)","steps":["From pigeon, bend the back knee and reach back to hold that foot (or your shin).","Lift your chest and gently draw the foot toward your head.","Hold, then switch."],"feel":"front of the back thigh and hip, chest opening","dont":null,"hold":"2 min/side"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"}],"notes":[]}]},{"dow":"Tuesday","title":"Power + balance + front splits","flow":"Warm-up → Power + balance → Stretch","sections":[{"kind":"strength","title":"POWER + BALANCE","meta":"3 rounds, rest 60-90 sec between rounds. Quality over speed.","items":[{"name":"Tuck jump","steps":["Feet hip-width, quarter squat.","Jump straight up, pulling your knees toward your chest.","Land softly and go into the next one."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"6"},{"name":"Skater hops","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged","sets":"8/side"},{"name":"Single-leg hop and stick","steps":["Stand on one leg, soft knee.","Hop forward about 50 cm and land softly on the same leg.","Freeze 2 sec, balanced, then repeat. All reps one side, then switch."],"feel":"outer hip, bum, balance","dont":"land stiff-legged or let the knee cave in","sets":"5/side"},{"name":"Relevé balance (single leg, on toes)","steps":["Stand on one leg, near a wall.","Rise up onto the ball of that foot (heel high) and hold your balance, other foot at your ankle or knee.","Hold for the time, then switch."],"feel":"calf, ankle, outer hip","dont":"sink your heel","sets":"30 sec/side"}],"notes":["Soft, quiet landings on a clear floor. Stop a move when your form fades. This and Thursday are your only jump days."],"bw":true},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"about 30 min","items":[{"name":"Standing forward fold","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null,"hold":"2 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"2 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"2 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"6 x 10 sec/side"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Active leg raise","steps":["Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null,"hold":"8 x 15 sec/side"},{"name":"Standing front leg hold","steps":["Stand tall next to a wall, hand on it.","Lift your outside leg straight in front of you as high as you can, using only your leg muscles.","Hold for the time, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of thigh working, back of thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + skills + pull","flow":"Warm-up → Upper + skills → Pull → Stretch","sections":[{"kind":"strength","title":"UPPER + SKILLS","meta":"Straight sets, skills first: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Wall handstand push-up, short range","steps":["Back-to-wall handstand.","Lower until your elbows reach 90 degrees, head a hand-width off the floor, elbows about 45 degrees from your body.","Press back up to straight arms.","Can't yet? More wall negatives. Can't kick up to the wall? Do them chest-to-wall."],"feel":"shoulders and triceps","dont":"arch your back or let your ribs flare","sets":"3-4 x up to 5"},{"name":"Archer push-up","steps":["Full push-up position with hands very wide.","Lower toward one hand while the other arm stays straight out to the side.","Push back up, then lower to the other side. Each side = 1 rep.","Can't yet? Wide push-ups, shifting your weight side to side."],"feel":"chest and arm of the bent side","dont":"let your hips sag","sets":"3-4 x up to 8"},{"name":"Back-to-wall handstand kick-up hold","steps":["Hands on the floor about 20 cm from a wall.","Kick one leg up softly, then the other, until your heels touch the wall.","Stack wrists, shoulders and hips, hold. Come down one foot at a time.","Can't yet? Chest-to-wall holds."],"feel":"shoulders, core","dont":"kick hard or arch your back","sets":"3-4 x up to 30 sec"},{"name":"L-sit (parallettes)","steps":["Sit between your parallettes, hands on the handles beside your hips.","Push down to lift your hips and straight legs off the floor.","Hold. Can't yet? Tuck your knees in."],"feel":"abs, hip flexors, triceps","dont":"shrug up to your ears","sets":"3-4 x up to 40 sec"},{"name":"Windshield wipers (floor)","steps":["Lie on your back, arms out wide, legs straight up.","Lower both legs to one side, stopping just above the floor, then up and over to the other side.","Keep your shoulders pinned down."],"feel":"obliques, abs","dont":"let your shoulders lift","sets":"3-4 x up to 10"},{"name":"Prone Y-T-W raise (floor)","steps":["Lie face down, forehead slightly off the floor.","Lift your arms into a Y, then a T, then a W, lowering between each.","One of each = 1 rep."],"feel":"upper back, rear shoulders","dont":"shrug up to your ears","sets":"3 x 10"},{"name":"Band pull-apart","steps":["Hold a light long band in front of your chest, hands shoulder-width, arms straight.","Pull the band apart by squeezing your shoulder blades together until it touches your chest.","Return slowly."],"feel":"upper back and the back of your shoulders","dont":"shrug or bend your elbows","sets":"3 x 15"}],"notes":["Upper-body volume stays modest on purpose: skill holds and slow reps build control and definition without bulky arms.","Y-T-W raises and snow angels keep your shoulders back and your posture tall. Pulling comes next."],"bw":true},{"kind":"strength","title":"PULL (BAR)","meta":"Straight sets: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3-4 x up to 5"},{"name":"Tuck front lever hold","steps":["Hang with straight arms, overhand grip.","Press the bar down toward your hips and lean back until your back is flat and level with the floor, knees tucked to your chest.","Hold, then lower with control.","Can't yet? Hold it with your hips a little lower than your shoulders, or do slow scapular pulls."],"feel":"lats, core, everything working","dont":"bend your arms","sets":"3 x up to 10 sec"},{"name":"Hanging leg raise","steps":["Hang with straight arms, shoulders down.","Keep your legs straight and together and lift them to hip height.","Lower slowly without swinging.","Can't yet? Hanging knee raises."],"feel":"lower abs, hip flexors","dont":"swing","sets":"3 x up to 10"}],"notes":["Pulling stays at a moderate dose: enough for strong, healthy shoulders, a lifted posture and real pull-up strength, without building a wide V-shaped back."],"bw":true},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"about 25 min","items":[{"name":"Wrist circles and palm lifts","steps":["Kneel with palms flat, fingers forward, then back, then out. Lean gently back and forth.","Lift your palms, keep fingers down, then circle each wrist slowly.","Stay at a mild stretch, never force."],"feel":"wrists and forearms","dont":null,"hold":"2 min"},{"name":"Cat-cow","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null,"hold":"15 reps"},{"name":"Thread-the-needle","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"90 sec/side"},{"name":"Sphinx or cobra","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null,"hold":"90 sec"},{"name":"Clasped-hands chest opener (kneeling)","steps":["Kneel tall, clasp your hands behind your back.","Straighten your arms and lift them away from your back, chest open.","Hold."],"feel":"chest and front shoulders","dont":null,"hold":"90 sec"},{"name":"Puppy pose","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null,"hold":"2 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"90 sec"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 45 sec"},{"name":"Bridge walk-in (hands toward feet)","steps":["Get into a full bridge.","Walk your hands one small step toward your feet, pressing your chest forward over your hands.","Hold, then walk back. Lower by tucking your chin."],"feel":"shoulders, spine, front of hips","dont":null,"hold":"3 x 30 sec"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"90 sec/side"}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"3-4 sets unless noted","items":[{"name":"Pistol squat","steps":["Stand on one leg, free leg straight out in front, arms reaching forward.","Squat down as low as you can control, heel down. Stop at 90 degrees if you can't go deeper yet.","Stand back up with no hands. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the knee cave in","sets":"4 x 8/side, 5s lowering"},{"name":"Shrimp squat (floor)","steps":["Stand on one leg, hold the other foot behind you with the same-side hand.","Lower until your back knee gently touches the floor, torso leaning forward.","Stand back up. All reps one side, then switch."],"feel":"front thigh and bum","dont":"drop onto the knee","sets":"4 x 8/side, 5s lowering"},{"name":"Deep reverse lunge, forward lean","steps":["Stand tall, then take a long step back and lower until your back knee nearly touches the floor.","Hinge your chest forward over the front thigh with a flat back, fingertips reaching toward the floor beside your front foot.","Pause at the bottom, then push through the front heel to stand. All reps one side, then switch."],"feel":"bum and back of the front thigh","dont":"take a short step or round your back","sets":"4 x 12/side, 3s lowering"},{"name":"Reverse Nordic curl","steps":["Kneel tall, arms crossed or reaching forward.","Lean back from the knees as far as you can control, hips pushed forward.","Use your thighs to pull back up.","Can't yet? Lean back only a little and build the range slowly."],"feel":"front of thighs, long stretch","dont":"bend at the hips","sets":"4 x 10"},{"name":"Jump lunge (split jump)","steps":["Start in a lunge, back knee low.","Jump up and switch legs in the air.","Land softly in the opposite lunge. Each landing = 1 rep."],"feel":"thighs, bum, power","dont":"land loudly","sets":"3 x 8/side"},{"name":"Single-leg hop and stick","steps":["Stand on one leg, soft knee.","Hop forward about 50 cm and land softly on the same leg.","Freeze 2 sec, balanced, then repeat. All reps one side, then switch."],"feel":"outer hip, bum, balance","dont":"land stiff-legged or let the knee cave in","sets":"3 x 6/side"},{"name":"Single-leg calf raise (floor, slow)","steps":["Stand on one foot, fingertips on a wall for balance if needed.","Rise as high as you can: 3 sec up, 1 sec pause, 3 sec down.","All reps one side, then switch."],"feel":"calf","dont":"bounce","sets":"3 x 15/side"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"about 25 min","items":[{"name":"Butterfly","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null,"hold":"2 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Straddle fold, chest to floor","steps":["Sit in a wide straddle, toes up.","Walk your hands forward and slowly lower your chest toward the floor.","Hold, breathing slowly."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Active straddle lift-offs","steps":["Sit in a wide straddle, hands on the floor in front of you.","Lift one straight leg a few cm using your leg muscles, hold, lower. Alternate.","Keep your back flat."],"feel":"inner thighs stretching, hips working","dont":null,"hold":"6 x 8 sec"},{"name":"Cossack squat hold (floor)","steps":["Feet very wide, sit into one side with the other leg straight, toes up.","Hold, chest tall, then switch.","Keep the bent-leg heel down."],"feel":"inner thigh, hip","dont":null,"hold":"30 sec x 4/side"},{"name":"Side leg hold","steps":["Stand tall, side-on to a wall, hand on it.","Lift your outside leg straight out to the side as high as you can, toes forward.","Hold for the time, lower. Do all reps, then switch."],"feel":"side of hip working, inner thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"3-4 sets unless noted","items":[{"name":"Single-leg RDL to knee drive","steps":["Stand on one leg.","Hinge forward into a single-leg RDL, back leg lifting.","Stand up and drive the back knee up in front of you to hip height. Balance 1 sec.","That's 1 rep. All reps one side, then switch."],"feel":"bum, hamstring, balance","dont":"rush","sets":"4 x 15/side"},{"name":"Deep curtsy lunge, bottom pulses","steps":["Step one leg back and across into a deep curtsy, back knee near the floor, chest leaning slightly forward.","Stay low and pulse up and down a few centimetres in the bottom half only.","Keep your hips facing forward the whole time. All reps one side, then switch."],"feel":"outer bum of the front leg burning in the stretch","dont":"come all the way up or twist your hips","sets":"4 x 15/side"},{"name":"Banded lateral walk","steps":["Put a mini band just above your knees (around your ankles is harder, around your feet is hardest).","Sit back into a quarter squat, chest up, feet hip-width apart.","Step sideways with control, keeping tension on the band the whole time. All steps one way, then come back."],"feel":"side of your bum burning","dont":"let your knees cave in or stand up tall","sets":"4 x 15 steps/side, band at ankles"},{"name":"Single-leg bridge walkout","steps":["Lie in a bridge with one foot lifted.","On the working foot, slowly walk the heel out and back with your hips high.","All reps one side, then switch."],"feel":"back of thigh, bum","dont":"let your hips drop","sets":"4 x 8/side"},{"name":"Side-lying inner thigh lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Lie on your side, top leg bent with the foot in front, bottom leg straight.","Lift the bottom leg up toward the top leg, 2 sec up and 2 sec down.","All reps one side, then switch."],"feel":"inner thigh","dont":"roll your hips back","sets":"3 x 12/side"},{"name":"Side plank bottom-leg lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Side plank on your forearm, top foot in front of you on the floor.","Lift your bottom leg up to meet the top leg and hold.","Lower. All reps one side, then switch."],"feel":"inner thigh, side of waist","dont":"let your hips sag","sets":"3 x 12/side"},{"name":"Lateral lunge to curtsy flow","steps":["Step out into a side lunge, sitting back into that hip.","Push off and swing the same leg back and across into a curtsy lunge.","Stand up. Side lunge + curtsy = 1 rep. All reps one side, then switch."],"feel":"bum, outer hips, inner thighs","dont":"rush","sets":"4 x 12/side"},{"name":"Arabesque balance (standing leg, hands free)","steps":["Stand on one leg, hinge forward and lift the other leg straight back to parallel.","Arms reach forward, spine long, hips square.","Hold, then switch."],"feel":"bum and hamstring of the standing leg, balance","dont":"twist your hips open","sets":"3 x 40 sec/side"},{"name":"Prone hip extension (ankle weights)","steps":["Ankle weights on both legs.","Lie face down, forehead on your hands, legs straight.","Squeeze your bum and lift one straight leg a few cm off the floor.","Lower slowly. All reps one side, then switch."],"feel":"bum","dont":"lift by arching your lower back; small lift is fine","sets":"3 x 12/side, 3s hold"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"about 15 min","items":[{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"2 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"6 x 10 sec/side"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Seated forward fold","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null,"hold":"2 min"},{"name":"Lying figure-4 contract-relax","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"3 x 10 sec/side"}],"notes":[]}]},{"dow":"Saturday","title":"Flexibility + test day","flow":"Warm-up → Bar practice → Full-body flow → Test","sections":[{"kind":"strength","title":"BAR PRACTICE","meta":"about 5-10 min, easy and crisp. Never to failure.","items":[{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3 easy sets of half your best"},{"name":"Dead hang","steps":["Grab the bar overhand, hands shoulder-width apart.","Hang with straight arms, shoulders gently pulled down away from your ears, legs together.","Hold for the time and breathe.","Can't yet? Keep your toes lightly on a step or the floor and take some weight off."],"feel":"grip, shoulders, lats stretching","dont":"let your shoulders shrug up to your ears","sets":"2 x up to 45 sec"}],"notes":["Short, frequent practice is how pull-ups come fastest."],"bw":true},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"about 25 min","items":[{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Thread-the-needle (each side)","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"3 min"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"90 sec"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 45 sec"}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm)","Middle split: hips from floor (cm)","Deep squat hold time","Full bridge hold time","Pistol squat: best clean reps per leg"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null,"hold":"2 min"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"1 min/side"},{"name":"Happy baby","steps":["Lie on your back, hold the outsides of your feet with knees wide.","Draw your knees toward your armpits and rock gently.","Hold."],"feel":"hips and lower back","dont":null,"hold":"2 min"},{"name":"Slow breathing","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null,"hold":"2 min"}],"notes":[]}]}]},{"n":11,"name":"Inversions","tagline":"Taller wall handstand push-ups, one-arm negatives, tuck planche and crow. Glute and thigh volume stays high.","bw":true,"info":[["Strength","3-4 sets, skills first. Bodyweight, a pull-up bar, resistance bands, ankle weights and parallettes."],["Lower-body sets","About 81 hard sets a week on Mon, Thu and Fri: 23 hip-extension (bridge, hinge, hamstring), 30 squat, lunge and jump, 28 side-hip and inner-thigh. Plus Tuesday jumps. When a set gets easy, go up a band or add ankle weight first, then make it slower."],["Stretch holds","1-3 min holds. Dancer pose, active lift-offs 15 sec, bridge walk-ins."],["Goals","Wall handstand push-up (short range) 8. Tuck planche 10 sec. Crow 30 sec. Dancer pose 45 sec per side. Pistol 8 per side, 5 sec lowering. Broad jump and stick 8. Pull-ups 6. Tuck front lever 15 sec."],["Time here","About 6-8 weeks for the lower body. Skills like handstand push-ups and planche can lag behind: move up when the legs and glutes feel easy, and keep practising the skill step you're on (each one has a \\"Can't yet?\\" option)."],["Move to next plan","After about 6-8 weeks, when this whole week feels easy."],["Safety","Warm up first, never bounce in a stretch, stay at strong-but-comfortable. Pain, pinching or numbness means back off a step. Jumps: soft landings, clear floor. Handstand work: clear space, learn a cartwheel exit, stop if neck, wrists or shoulders hurt. Pull-up bar: check it is fixed solidly before every session and never jump to grab it."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"3-4 sets unless noted","items":[{"name":"Long-lever single-leg bridge","steps":["Lie on your back, one leg straight in the air, the other foot flat a long way from your hips.","Drive through that heel and lift your hips until your shoulders, hips and raised leg are in one line.","Lower slowly. All reps one side, then switch."],"feel":"bum and back of thigh","dont":"arch your lower back or twist your hips","sets":"4 x 10/side, 2s pause + 5s lowering"},{"name":"Forward-lean split squat","steps":["Stand in a long split stance, back heel up, feet hip-width apart like train tracks.","Lean your chest forward about 30-45 degrees with a flat back, hands on your hips or reaching forward.","Lower until your back knee lightly touches the floor and you feel a deep stretch in the bum of your front leg. Hold the pause.","Drive through the front heel to come up, stopping just short of standing so the glute keeps working. All reps one side, then switch."],"feel":"deep stretch and burn in the bum of the front leg","dont":"let the front knee cave in or the front heel lift","sets":"4 x 12/side, 1.5 reps"},{"name":"Banded glute bridge","steps":["Loop a long resistance band over your hip crease and pin each end to the floor under your hands.","Feet flat, hip-width apart, heels about a hand-length from your bum.","Drive through your heels and lift your hips into the band until your body is straight from knees to shoulders. Squeeze hard at the top.","Lower slowly. Go up a band when every set feels easy."],"feel":"bum, working hard against the band at the top","dont":"arch your lower back to get higher","sets":"4 x 12, 1.5 reps"},{"name":"Skater squat","steps":["Stand on one leg, other leg behind you, arms swinging forward.","Lower on the standing leg until your back knee gently taps the floor.","Stand without pushing off the back foot. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the front knee cave in","sets":"4 x 12/side, 5s lowering"},{"name":"Curtsy lunge","steps":["Hands together at your chest, feet hip-width.","Step one leg back and across, bending both knees into a deep curtsy, hips facing forward.","Push through the front heel to stand. All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"twist your hips","sets":"4 x 12/side, 3s lowering + 2s pause"},{"name":"Fire hydrant + donkey kick combo, 2 sec hold (ankle weights)","steps":["Ankle weights on both legs.","On hands and knees.","Lift one bent leg out to the side and hold 2 sec. Bring it back.","Kick that foot up toward the ceiling and hold 2 sec. Bring it back. That's 1 rep.","All reps one side, then switch."],"feel":"all of your bum","dont":"arch your lower back","sets":"3 x 12/side"},{"name":"Star side plank","steps":["Side plank on your hand (arm straight) or elbow, feet stacked.","Lift your top leg up and reach your top arm to the ceiling, making a star.","Hold for the time, then switch."],"feel":"side of your bum and waist","dont":"let your hips sag","sets":"3 x 45 sec/side"},{"name":"Banded frog pump, 2 sec pause","steps":["Loop a long band over your hips and pin the ends under your hands.","Same as frog pump: on your back, soles together, knees out wide, heels near your bum.","Lift your hips by squeezing your bum.","Hold and squeeze for 2 sec at the top, then lower."],"feel":"bum, especially the sides","dont":"arch your lower back","sets":"4 x 25"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"about 25 min","items":[{"name":"90/90 hip switches","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null,"hold":"20 reps, hands off the floor"},{"name":"Figure-4 (on back)","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"2 min/side"},{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"King pigeon prep (hold your foot)","steps":["From pigeon, bend the back knee and reach back to hold that foot (or your shin).","Lift your chest and gently draw the foot toward your head.","Hold, then switch."],"feel":"front of the back thigh and hip, chest opening","dont":null,"hold":"2 min/side"},{"name":"Dancer pose (standing bow)","steps":["Stand on one leg, hold the other ankle behind you.","Kick your foot back into your hand while your torso tilts forward, free arm reaching ahead.","Hold, hips square, then switch."],"feel":"front of thigh and hip, balance","dont":null,"hold":"45 sec/side"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"}],"notes":[]}]},{"dow":"Tuesday","title":"Power + balance + front splits","flow":"Warm-up → Power + balance → Stretch","sections":[{"kind":"strength","title":"POWER + BALANCE","meta":"3 rounds, rest 60-90 sec between rounds. Quality over speed.","items":[{"name":"Arabesque balance (standing leg, hands free)","steps":["Stand on one leg, hinge forward and lift the other leg straight back to parallel.","Arms reach forward, spine long, hips square.","Hold, then switch."],"feel":"bum and hamstring of the standing leg, balance","dont":"twist your hips open","sets":"30 sec/side"},{"name":"Single-leg hop and stick","steps":["Stand on one leg, soft knee.","Hop forward about 50 cm and land softly on the same leg.","Freeze 2 sec, balanced, then repeat. All reps one side, then switch."],"feel":"outer hip, bum, balance","dont":"land stiff-legged or let the knee cave in","sets":"6/side"},{"name":"Tuck jump","steps":["Feet hip-width, quarter squat.","Jump straight up, pulling your knees toward your chest.","Land softly and go into the next one."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"6"},{"name":"Skater hops","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged","sets":"8/side"},{"name":"Broad jump and stick","steps":["Feet hip-width, swing your arms back.","Jump forward as far as you can and land softly in a squat.","Freeze 2 sec, walk back, repeat."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"5"}],"notes":["Soft, quiet landings on a clear floor. Stop a move when your form fades. This and Thursday are your only jump days."],"bw":true},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"about 30 min","items":[{"name":"Standing forward fold","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null,"hold":"2 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"2 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"3 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"6 x 15 sec/side"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Active leg raise","steps":["Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null,"hold":"8 x 15 sec/side"},{"name":"Standing front leg hold","steps":["Stand tall next to a wall, hand on it.","Lift your outside leg straight in front of you as high as you can, using only your leg muscles.","Hold for the time, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of thigh working, back of thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + skills + pull","flow":"Warm-up → Upper + skills → Pull → Stretch","sections":[{"kind":"strength","title":"UPPER + SKILLS","meta":"Straight sets, skills first: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Wall handstand push-up, short range","steps":["Back-to-wall handstand.","Lower until your elbows reach 90 degrees, head a hand-width off the floor, elbows about 45 degrees from your body.","Press back up to straight arms.","Can't yet? More wall negatives. Can't kick up to the wall? Do them chest-to-wall."],"feel":"shoulders and triceps","dont":"arch your back or let your ribs flare","sets":"3-4 x up to 8"},{"name":"One-arm push-up negative","steps":["Full plank, feet wide, one hand behind your back.","Lower slowly for 5 sec with your elbow angled back, hips level.","Drop to the floor, reset, repeat. All reps one side, then switch. Knees down if needed.","Can't yet? Archer push-ups, or do the negative with your knees down."],"feel":"chest, arm, core, very hard","dont":"twist your hips open","sets":"3-4 x up to 3/side"},{"name":"Pseudo planche push-up (parallettes)","steps":["Push-up position with hands on the parallettes by your lower ribs.","Lean your shoulders forward past your hands, then lower and push back up.","Keep your body in one hard line.","Can't yet? Lean less, or do them with knees down."],"feel":"chest, front shoulders, core","dont":"let your hips pike up","sets":"3-4 x up to 12"},{"name":"Tuck planche hold (parallettes)","steps":["Hands on the parallettes beside your hips, knees tucked to your chest.","Lean forward, lock your arms and lift your feet off the floor.","Hold. Can't lift yet? Hold the forward lean."],"feel":"shoulders, arms, core","dont":"bend your arms","sets":"3-4 x up to 10 sec"},{"name":"V-sit (parallettes)","steps":["Sit between your parallettes, hands on the handles beside your hips.","Balance on your sit bones with your hands beside your hips, body in a V.","Hold.","Can't yet? L-sit, or a tuck sit with knees bent."],"feel":"abs, hip flexors, balance","dont":"round your upper back","sets":"3-4 x up to 20 sec"},{"name":"Prone Y-T-W raise (floor)","steps":["Lie face down, forehead slightly off the floor.","Lift your arms into a Y, then a T, then a W, lowering between each.","One of each = 1 rep."],"feel":"upper back, rear shoulders","dont":"shrug up to your ears","sets":"3 x 10"},{"name":"Band pull-apart","steps":["Hold a light long band in front of your chest, hands shoulder-width, arms straight.","Pull the band apart by squeezing your shoulder blades together until it touches your chest.","Return slowly."],"feel":"upper back and the back of your shoulders","dont":"shrug or bend your elbows","sets":"3 x 15"}],"notes":["Upper-body volume stays modest on purpose: skill holds and slow reps build control and definition without bulky arms.","Y-T-W raises and snow angels keep your shoulders back and your posture tall. Pulling comes next."],"bw":true},{"kind":"strength","title":"PULL (BAR)","meta":"Straight sets: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3-4 x up to 6"},{"name":"Tuck front lever hold","steps":["Hang with straight arms, overhand grip.","Press the bar down toward your hips and lean back until your back is flat and level with the floor, knees tucked to your chest.","Hold, then lower with control.","Can't yet? Hold it with your hips a little lower than your shoulders, or do slow scapular pulls."],"feel":"lats, core, everything working","dont":"bend your arms","sets":"3 x up to 15 sec"},{"name":"Hanging leg raise","steps":["Hang with straight arms, shoulders down.","Keep your legs straight and together and lift them to hip height.","Lower slowly without swinging.","Can't yet? Hanging knee raises."],"feel":"lower abs, hip flexors","dont":"swing","sets":"3 x up to 12"}],"notes":["Pulling stays at a moderate dose: enough for strong, healthy shoulders, a lifted posture and real pull-up strength, without building a wide V-shaped back."],"bw":true},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"about 25 min","items":[{"name":"Wrist circles and palm lifts","steps":["Kneel with palms flat, fingers forward, then back, then out. Lean gently back and forth.","Lift your palms, keep fingers down, then circle each wrist slowly.","Stay at a mild stretch, never force."],"feel":"wrists and forearms","dont":null,"hold":"2 min"},{"name":"Cat-cow","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null,"hold":"15 reps"},{"name":"Thread-the-needle","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"90 sec/side"},{"name":"Sphinx or cobra","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null,"hold":"90 sec"},{"name":"Clasped-hands chest opener (kneeling)","steps":["Kneel tall, clasp your hands behind your back.","Straighten your arms and lift them away from your back, chest open.","Hold."],"feel":"chest and front shoulders","dont":null,"hold":"90 sec"},{"name":"Puppy pose","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null,"hold":"2 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"90 sec"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 45 sec"},{"name":"Bridge walk-in (hands toward feet)","steps":["Get into a full bridge.","Walk your hands one small step toward your feet, pressing your chest forward over your hands.","Hold, then walk back. Lower by tucking your chin."],"feel":"shoulders, spine, front of hips","dont":null,"hold":"3 x 30 sec"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"90 sec/side"}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"3-4 sets unless noted","items":[{"name":"Pistol squat","steps":["Stand on one leg, free leg straight out in front, arms reaching forward.","Squat down as low as you can control, heel down. Stop at 90 degrees if you can't go deeper yet.","Stand back up with no hands. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the knee cave in","sets":"4 x 8/side, 5s lowering"},{"name":"Shrimp squat (floor)","steps":["Stand on one leg, hold the other foot behind you with the same-side hand.","Lower until your back knee gently touches the floor, torso leaning forward.","Stand back up. All reps one side, then switch."],"feel":"front thigh and bum","dont":"drop onto the knee","sets":"4 x 8/side, 5s lowering"},{"name":"Deep reverse lunge, forward lean","steps":["Stand tall, then take a long step back and lower until your back knee nearly touches the floor.","Hinge your chest forward over the front thigh with a flat back, fingertips reaching toward the floor beside your front foot.","Pause at the bottom, then push through the front heel to stand. All reps one side, then switch."],"feel":"bum and back of the front thigh","dont":"take a short step or round your back","sets":"4 x 10/side, 1.5 reps"},{"name":"Reverse Nordic curl","steps":["Kneel tall, arms crossed or reaching forward.","Lean back from the knees as far as you can control, hips pushed forward.","Use your thighs to pull back up.","Can't yet? Lean back only a little and build the range slowly."],"feel":"front of thighs, long stretch","dont":"bend at the hips","sets":"4 x 12"},{"name":"Broad jump and stick","steps":["Feet hip-width, swing your arms back.","Jump forward as far as you can and land softly in a squat.","Freeze 2 sec, walk back, repeat."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"3 x 6"},{"name":"Single-leg hop and stick","steps":["Stand on one leg, soft knee.","Hop forward about 50 cm and land softly on the same leg.","Freeze 2 sec, balanced, then repeat. All reps one side, then switch."],"feel":"outer hip, bum, balance","dont":"land stiff-legged or let the knee cave in","sets":"3 x 6/side"},{"name":"Single-leg calf raise (floor, slow)","steps":["Stand on one foot, fingertips on a wall for balance if needed.","Rise as high as you can: 3 sec up, 1 sec pause, 3 sec down.","All reps one side, then switch."],"feel":"calf","dont":"bounce","sets":"3 x 15/side"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"about 25 min","items":[{"name":"Butterfly","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null,"hold":"2 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Straddle fold, chest to floor","steps":["Sit in a wide straddle, toes up.","Walk your hands forward and slowly lower your chest toward the floor.","Hold, breathing slowly."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Active straddle lift-offs","steps":["Sit in a wide straddle, hands on the floor in front of you.","Lift one straight leg a few cm using your leg muscles, hold, lower. Alternate.","Keep your back flat."],"feel":"inner thighs stretching, hips working","dont":null,"hold":"6 x 10 sec"},{"name":"Cossack squat hold (floor)","steps":["Feet very wide, sit into one side with the other leg straight, toes up.","Hold, chest tall, then switch.","Keep the bent-leg heel down."],"feel":"inner thigh, hip","dont":null,"hold":"45 sec x 4/side"},{"name":"Side leg hold","steps":["Stand tall, side-on to a wall, hand on it.","Lift your outside leg straight out to the side as high as you can, toes forward.","Hold for the time, lower. Do all reps, then switch."],"feel":"side of hip working, inner thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"3-4 sets unless noted","items":[{"name":"Single-leg RDL to knee drive","steps":["Stand on one leg.","Hinge forward into a single-leg RDL, back leg lifting.","Stand up and drive the back knee up in front of you to hip height. Balance 1 sec.","That's 1 rep. All reps one side, then switch."],"feel":"bum, hamstring, balance","dont":"rush","sets":"4 x 15/side"},{"name":"Deep curtsy lunge, bottom pulses","steps":["Step one leg back and across into a deep curtsy, back knee near the floor, chest leaning slightly forward.","Stay low and pulse up and down a few centimetres in the bottom half only.","Keep your hips facing forward the whole time. All reps one side, then switch."],"feel":"outer bum of the front leg burning in the stretch","dont":"come all the way up or twist your hips","sets":"4 x 20/side"},{"name":"Banded lateral walk","steps":["Put a mini band just above your knees (around your ankles is harder, around your feet is hardest).","Sit back into a quarter squat, chest up, feet hip-width apart.","Step sideways with control, keeping tension on the band the whole time. All steps one way, then come back."],"feel":"side of your bum burning","dont":"let your knees cave in or stand up tall","sets":"4 x 15 steps/side, band at ankles, 2s pause each step"},{"name":"Single-leg bridge walkout","steps":["Lie in a bridge with one foot lifted.","On the working foot, slowly walk the heel out and back with your hips high.","All reps one side, then switch."],"feel":"back of thigh, bum","dont":"let your hips drop","sets":"4 x 10/side"},{"name":"Side-lying inner thigh lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Lie on your side, top leg bent with the foot in front, bottom leg straight.","Lift the bottom leg up toward the top leg, 2 sec up and 2 sec down.","All reps one side, then switch."],"feel":"inner thigh","dont":"roll your hips back","sets":"3 x 12/side"},{"name":"Side plank bottom-leg lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Side plank on your forearm, top foot in front of you on the floor.","Lift your bottom leg up to meet the top leg and hold.","Lower. All reps one side, then switch."],"feel":"inner thigh, side of waist","dont":"let your hips sag","sets":"3 x 15/side"},{"name":"Lateral lunge to curtsy flow","steps":["Step out into a side lunge, sitting back into that hip.","Push off and swing the same leg back and across into a curtsy lunge.","Stand up. Side lunge + curtsy = 1 rep. All reps one side, then switch."],"feel":"bum, outer hips, inner thighs","dont":"rush","sets":"4 x 15/side"},{"name":"Arabesque balance (standing leg, hands free)","steps":["Stand on one leg, hinge forward and lift the other leg straight back to parallel.","Arms reach forward, spine long, hips square.","Hold, then switch."],"feel":"bum and hamstring of the standing leg, balance","dont":"twist your hips open","sets":"3 x 45 sec/side"},{"name":"Prone hip extension (ankle weights)","steps":["Ankle weights on both legs.","Lie face down, forehead on your hands, legs straight.","Squeeze your bum and lift one straight leg a few cm off the floor.","Lower slowly. All reps one side, then switch."],"feel":"bum","dont":"lift by arching your lower back; small lift is fine","sets":"3 x 12/side, 3s hold"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"about 20 min","items":[{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"3 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"6 x 15 sec/side"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Seated forward fold","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null,"hold":"2 min"},{"name":"Lying figure-4 contract-relax","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"3 x 10 sec/side"}],"notes":[]}]},{"dow":"Saturday","title":"Skills + test day","flow":"Warm-up → Skill practice → Full-body flow → Test","sections":[{"kind":"strength","title":"SKILL PRACTICE","meta":"about 15-20 min. Counts are for the whole session, rest as long as you need between tries.","items":[{"name":"Back-to-wall handstand kick-up hold","steps":["Hands on the floor about 20 cm from a wall.","Kick one leg up softly, then the other, until your heels touch the wall.","Stack wrists, shoulders and hips, hold. Come down one foot at a time.","Can't yet? Chest-to-wall holds."],"feel":"shoulders, core","dont":"kick hard or arch your back","sets":"5 x up to 30 sec"},{"name":"Crow pose (crane prep)","steps":["Squat with feet close, knees wide, hands flat shoulder-width, fingers spread.","Bend your elbows, rest your knees on the backs of your upper arms, lean forward.","Lift one foot, then the other, and hold. Look a hand-length ahead.","Can't yet? Rest your knees on your arms and lift one foot at a time."],"feel":"arms, core, balance","dont":"look straight down and tip forward","sets":"5 x up to 30 sec"},{"name":"Wall-assisted press to handstand","steps":["Face a wall in a pike, hands 30 cm from it.","Shift your shoulders over your hands and lift your hips over your shoulders, legs straight.","Rest your toes on the wall if needed. Lower with control.","Can't yet? Pike lean holds: shoulders over hands, hips high, toes light on the floor."],"feel":"shoulders, core, hip flexors","dont":"jump up","sets":"6 total"},{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3 easy sets of half your best"}],"notes":["Skills first while you are fresh. Warm up wrists and shoulders. Clear floor space, wall within reach, and know your cartwheel exit."],"bw":true},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"about 30 min","items":[{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Thread-the-needle (each side)","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"3 min"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"90 sec"},{"name":"Dancer pose (standing bow)","steps":["Stand on one leg, hold the other ankle behind you.","Kick your foot back into your hand while your torso tilts forward, free arm reaching ahead.","Hold, hips square, then switch."],"feel":"front of thigh and hip, balance","dont":null,"hold":"60 sec/side"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 45 sec"}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm)","Middle split: hips from floor (cm)","Deep squat hold time","Full bridge hold time","Handstand: longest clean hold in seconds (wall or freestanding)"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null,"hold":"2 min"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"1 min/side"},{"name":"Happy baby","steps":["Lie on your back, hold the outsides of your feet with knees wide.","Draw your knees toward your armpits and rock gently.","Hold."],"feel":"hips and lower back","dont":null,"hold":"2 min"},{"name":"Slow breathing","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null,"hold":"2 min"}],"notes":[]}]}]},{"n":12,"name":"Skills","tagline":"Full-range wall handstand push-ups, press-to-handstand practice, tuck planche and crane.","bw":true,"info":[["Strength","3-4 sets, slow lowering and skills. Bodyweight, a pull-up bar, resistance bands, ankle weights and parallettes."],["Lower-body sets","About 85 hard sets a week on Mon, Thu and Fri: 23 hip-extension (bridge, hinge, hamstring), 30 squat, lunge and jump, 32 side-hip and inner-thigh. Plus Tuesday jumps. When a set gets easy, go up a band or add ankle weight first, then make it slower."],["Stretch holds","1-3 min holds. One-leg bridge, active lift-offs 20 sec, dancer pose 60 sec."],["Goals","Wall handstand push-up (full range) 3. Tuck planche 15 sec. V-sit 30 sec. Crane 15 sec. Pistol 10 per side. Reverse Nordic curl 15. Pull-ups 8. Toes-to-bar 8."],["Time here","About 6-8 weeks for the lower body. Skills like handstand push-ups and planche can lag behind: move up when the legs and glutes feel easy, and keep practising the skill step you're on (each one has a \\"Can't yet?\\" option)."],["Move to next plan","After about 6-8 weeks, when this whole week feels easy."],["Safety","Warm up first, never bounce in a stretch, stay at strong-but-comfortable. Pain, pinching or numbness means back off a step. Jumps: soft landings, clear floor. Handstand work: clear space, learn a cartwheel exit, stop if neck, wrists or shoulders hurt. Pull-up bar: check it is fixed solidly before every session and never jump to grab it."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"3-4 sets unless noted","items":[{"name":"Long-lever single-leg bridge","steps":["Lie on your back, one leg straight in the air, the other foot flat a long way from your hips.","Drive through that heel and lift your hips until your shoulders, hips and raised leg are in one line.","Lower slowly. All reps one side, then switch."],"feel":"bum and back of thigh","dont":"arch your lower back or twist your hips","sets":"4 x 12/side, 2s pause + 5s lowering"},{"name":"Forward-lean split squat","steps":["Stand in a long split stance, back heel up, feet hip-width apart like train tracks.","Lean your chest forward about 30-45 degrees with a flat back, hands on your hips or reaching forward.","Lower until your back knee lightly touches the floor and you feel a deep stretch in the bum of your front leg. Hold the pause.","Drive through the front heel to come up, stopping just short of standing so the glute keeps working. All reps one side, then switch."],"feel":"deep stretch and burn in the bum of the front leg","dont":"let the front knee cave in or the front heel lift","sets":"4 x 10/side, 5s lowering + 2s pause"},{"name":"Banded glute bridge","steps":["Loop a long resistance band over your hip crease and pin each end to the floor under your hands.","Feet flat, hip-width apart, heels about a hand-length from your bum.","Drive through your heels and lift your hips into the band until your body is straight from knees to shoulders. Squeeze hard at the top.","Lower slowly. Go up a band when every set feels easy."],"feel":"bum, working hard against the band at the top","dont":"arch your lower back to get higher","sets":"4 x 15, 3s squeeze"},{"name":"Skater squat","steps":["Stand on one leg, other leg behind you, arms swinging forward.","Lower on the standing leg until your back knee gently taps the floor.","Stand without pushing off the back foot. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the front knee cave in","sets":"4 x 12/side, 5s lowering"},{"name":"Curtsy lunge","steps":["Hands together at your chest, feet hip-width.","Step one leg back and across, bending both knees into a deep curtsy, hips facing forward.","Push through the front heel to stand. All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"twist your hips","sets":"4 x 12/side, 3s lowering + 2s pause"},{"name":"Fire hydrant + donkey kick combo, 2 sec hold (ankle weights)","steps":["Ankle weights on both legs.","On hands and knees.","Lift one bent leg out to the side and hold 2 sec. Bring it back.","Kick that foot up toward the ceiling and hold 2 sec. Bring it back. That's 1 rep.","All reps one side, then switch."],"feel":"all of your bum","dont":"arch your lower back","sets":"3 x 12/side"},{"name":"Star side plank","steps":["Side plank on your hand (arm straight) or elbow, feet stacked.","Lift your top leg up and reach your top arm to the ceiling, making a star.","Hold for the time, then switch."],"feel":"side of your bum and waist","dont":"let your hips sag","sets":"3 x 45 sec/side"},{"name":"Banded frog pump, 2 sec pause","steps":["Loop a long band over your hips and pin the ends under your hands.","Same as frog pump: on your back, soles together, knees out wide, heels near your bum.","Lift your hips by squeezing your bum.","Hold and squeeze for 2 sec at the top, then lower."],"feel":"bum, especially the sides","dont":"arch your lower back","sets":"4 x 25"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"about 25 min","items":[{"name":"90/90 hip switches","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null,"hold":"20 reps, hands off the floor"},{"name":"Figure-4 (on back)","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"2 min/side"},{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"King pigeon prep (hold your foot)","steps":["From pigeon, bend the back knee and reach back to hold that foot (or your shin).","Lift your chest and gently draw the foot toward your head.","Hold, then switch."],"feel":"front of the back thigh and hip, chest opening","dont":null,"hold":"2 min/side"},{"name":"Dancer pose (standing bow)","steps":["Stand on one leg, hold the other ankle behind you.","Kick your foot back into your hand while your torso tilts forward, free arm reaching ahead.","Hold, hips square, then switch."],"feel":"front of thigh and hip, balance","dont":null,"hold":"60 sec/side"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"}],"notes":[]}]},{"dow":"Tuesday","title":"Power + balance + front splits","flow":"Warm-up → Power + balance → Stretch","sections":[{"kind":"strength","title":"POWER + BALANCE","meta":"3 rounds, rest 60-90 sec between rounds. Quality over speed.","items":[{"name":"Arabesque balance (standing leg, hands free)","steps":["Stand on one leg, hinge forward and lift the other leg straight back to parallel.","Arms reach forward, spine long, hips square.","Hold, then switch."],"feel":"bum and hamstring of the standing leg, balance","dont":"twist your hips open","sets":"30 sec/side"},{"name":"Single-leg hop and stick","steps":["Stand on one leg, soft knee.","Hop forward about 50 cm and land softly on the same leg.","Freeze 2 sec, balanced, then repeat. All reps one side, then switch."],"feel":"outer hip, bum, balance","dont":"land stiff-legged or let the knee cave in","sets":"6/side"},{"name":"Tuck jump","steps":["Feet hip-width, quarter squat.","Jump straight up, pulling your knees toward your chest.","Land softly and go into the next one."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"8"},{"name":"Skater hops","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged","sets":"10/side"},{"name":"Broad jump and stick","steps":["Feet hip-width, swing your arms back.","Jump forward as far as you can and land softly in a squat.","Freeze 2 sec, walk back, repeat."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"5"}],"notes":["Soft, quiet landings on a clear floor. Stop a move when your form fades. This and Thursday are your only jump days."],"bw":true},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"about 35 min","items":[{"name":"Standing forward fold","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null,"hold":"2 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"2 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"3 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"6 x 20 sec/side"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Active leg raise (ankle weight)","steps":["Ankle weight on the lifting leg.","Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null,"hold":"8 x 15 sec/side"},{"name":"Standing front leg hold (ankle weight)","steps":["Ankle weight on the lifting leg.","Stand tall next to a wall, hand on it.","Lift your outside leg straight in front of you as high as you can, using only your leg muscles.","Hold for the time, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of thigh working, back of thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + skills + pull","flow":"Warm-up → Upper + skills → Pull → Stretch","sections":[{"kind":"strength","title":"UPPER + SKILLS","meta":"Straight sets, skills first: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Wall handstand push-up (full range)","steps":["Back-to-wall handstand.","Lower until the top of your head lightly touches the floor, elbows about 45 degrees.","Press back to straight arms. End the set if your form or neck feels off.","Can't yet? Short-range reps, then one slow negative to the floor."],"feel":"shoulders, triceps, core","dont":"bounce off your head","sets":"3-4 x up to 3"},{"name":"One-arm push-up negative","steps":["Full plank, feet wide, one hand behind your back.","Lower slowly for 5 sec with your elbow angled back, hips level.","Drop to the floor, reset, repeat. All reps one side, then switch. Knees down if needed.","Can't yet? Archer push-ups, or do the negative with your knees down."],"feel":"chest, arm, core, very hard","dont":"twist your hips open","sets":"3-4 x up to 4/side"},{"name":"Tuck planche hold (parallettes)","steps":["Hands on the parallettes beside your hips, knees tucked to your chest.","Lean forward, lock your arms and lift your feet off the floor.","Hold. Can't lift yet? Hold the forward lean."],"feel":"shoulders, arms, core","dont":"bend your arms","sets":"3-4 x up to 15 sec"},{"name":"V-sit (parallettes)","steps":["Sit between your parallettes, hands on the handles beside your hips.","Balance on your sit bones with your hands beside your hips, body in a V.","Hold.","Can't yet? L-sit, or a tuck sit with knees bent."],"feel":"abs, hip flexors, balance","dont":"round your upper back","sets":"3-4 x up to 30 sec"},{"name":"Crane pose (straight-arm crow)","steps":["Start in crow with your knees high on your upper arms.","Slowly straighten your arms as you shift your hips up and back.","Hold, then lower with control.","Can't yet? Hold crow and straighten your arms a little more each week."],"feel":"arms, core, wrists","dont":"let your head drop forward","sets":"3-4 x up to 15 sec"},{"name":"Prone Y-T-W raise (floor)","steps":["Lie face down, forehead slightly off the floor.","Lift your arms into a Y, then a T, then a W, lowering between each.","One of each = 1 rep."],"feel":"upper back, rear shoulders","dont":"shrug up to your ears","sets":"3 x 10"},{"name":"Band pull-apart","steps":["Hold a light long band in front of your chest, hands shoulder-width, arms straight.","Pull the band apart by squeezing your shoulder blades together until it touches your chest.","Return slowly."],"feel":"upper back and the back of your shoulders","dont":"shrug or bend your elbows","sets":"3 x 15"}],"notes":["Upper-body volume stays modest on purpose: skill holds and slow reps build control and definition without bulky arms.","Y-T-W raises and snow angels keep your shoulders back and your posture tall. Pulling comes next."],"bw":true},{"kind":"strength","title":"PULL (BAR)","meta":"Straight sets: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3-4 x up to 8"},{"name":"Advanced tuck front lever hold","steps":["Get into a tuck front lever.","Open your hips so your back stays flat and your knees move away from your chest, shins still tucked.","Hold, then lower with control.","Can't yet? Tuck front lever holds."],"feel":"lats and core, very hard","dont":"bend your arms or let your hips drop","sets":"3 x up to 8 sec"},{"name":"Toes-to-bar","steps":["Hang with straight arms, shoulders down.","Lift your straight legs all the way up until your toes touch the bar, rolling your pelvis up.","Lower slowly without swinging.","Can't yet? Hanging leg raises."],"feel":"abs, lats, grip","dont":"kip or swing","sets":"3 x up to 8"}],"notes":["Pulling stays at a moderate dose: enough for strong, healthy shoulders, a lifted posture and real pull-up strength, without building a wide V-shaped back."],"bw":true},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"about 25 min","items":[{"name":"Wrist circles and palm lifts","steps":["Kneel with palms flat, fingers forward, then back, then out. Lean gently back and forth.","Lift your palms, keep fingers down, then circle each wrist slowly.","Stay at a mild stretch, never force."],"feel":"wrists and forearms","dont":null,"hold":"2 min"},{"name":"Cat-cow","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null,"hold":"15 reps"},{"name":"Thread-the-needle","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"90 sec/side"},{"name":"Sphinx or cobra","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null,"hold":"90 sec"},{"name":"Clasped-hands chest opener (kneeling)","steps":["Kneel tall, clasp your hands behind your back.","Straighten your arms and lift them away from your back, chest open.","Hold."],"feel":"chest and front shoulders","dont":null,"hold":"90 sec"},{"name":"Puppy pose","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null,"hold":"2 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"90 sec"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 45 sec"},{"name":"Bridge walk-in (hands toward feet)","steps":["Get into a full bridge.","Walk your hands one small step toward your feet, pressing your chest forward over your hands.","Hold, then walk back. Lower by tucking your chin."],"feel":"shoulders, spine, front of hips","dont":null,"hold":"3 x 30 sec"},{"name":"Bridge, one leg lifted","steps":["Get into a full bridge.","Shift weight onto one leg and lift the other straight up toward the ceiling.","Hold, lower, switch."],"feel":"hips, shoulders, balance","dont":null,"hold":"3 x 15 sec/side"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"90 sec/side"}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"3-4 sets unless noted","items":[{"name":"Pistol squat","steps":["Stand on one leg, free leg straight out in front, arms reaching forward.","Squat down as low as you can control, heel down. Stop at 90 degrees if you can't go deeper yet.","Stand back up with no hands. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the knee cave in","sets":"4 x 10/side, 5s lowering"},{"name":"Shrimp squat (floor)","steps":["Stand on one leg, hold the other foot behind you with the same-side hand.","Lower until your back knee gently touches the floor, torso leaning forward.","Stand back up. All reps one side, then switch."],"feel":"front thigh and bum","dont":"drop onto the knee","sets":"4 x 10/side, 5s lowering"},{"name":"Deep reverse lunge, forward lean","steps":["Stand tall, then take a long step back and lower until your back knee nearly touches the floor.","Hinge your chest forward over the front thigh with a flat back, fingertips reaching toward the floor beside your front foot.","Pause at the bottom, then push through the front heel to stand. All reps one side, then switch."],"feel":"bum and back of the front thigh","dont":"take a short step or round your back","sets":"4 x 12/side, 1.5 reps"},{"name":"Reverse Nordic curl","steps":["Kneel tall, arms crossed or reaching forward.","Lean back from the knees as far as you can control, hips pushed forward.","Use your thighs to pull back up.","Can't yet? Lean back only a little and build the range slowly."],"feel":"front of thighs, long stretch","dont":"bend at the hips","sets":"4 x 12"},{"name":"Tuck jump","steps":["Feet hip-width, quarter squat.","Jump straight up, pulling your knees toward your chest.","Land softly and go into the next one."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"3 x 8"},{"name":"Single-leg hop and stick","steps":["Stand on one leg, soft knee.","Hop forward about 50 cm and land softly on the same leg.","Freeze 2 sec, balanced, then repeat. All reps one side, then switch."],"feel":"outer hip, bum, balance","dont":"land stiff-legged or let the knee cave in","sets":"3 x 6/side"},{"name":"Cossack squat (bodyweight)","steps":["Feet very wide, toes slightly out.","Sit down into one side, other leg straight with toes up. Heel of the bent leg stays down.","Push back up and switch sides. Each side = 1 rep."],"feel":"bum and inner thighs","dont":"lift the heel of the bent leg","sets":"4 x 12/side, 3s pause"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"about 25 min","items":[{"name":"Butterfly","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null,"hold":"2 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Straddle fold, chest to floor","steps":["Sit in a wide straddle, toes up.","Walk your hands forward and slowly lower your chest toward the floor.","Hold, breathing slowly."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Active straddle lift-offs","steps":["Sit in a wide straddle, hands on the floor in front of you.","Lift one straight leg a few cm using your leg muscles, hold, lower. Alternate.","Keep your back flat."],"feel":"inner thighs stretching, hips working","dont":null,"hold":"6 x 10 sec"},{"name":"Cossack squat hold (floor)","steps":["Feet very wide, sit into one side with the other leg straight, toes up.","Hold, chest tall, then switch.","Keep the bent-leg heel down."],"feel":"inner thigh, hip","dont":null,"hold":"45 sec x 4/side"},{"name":"Side leg hold (ankle weight)","steps":["Ankle weight on the lifting leg.","Stand tall, side-on to a wall, hand on it.","Lift your outside leg straight out to the side as high as you can, toes forward.","Hold for the time, lower. Do all reps, then switch."],"feel":"side of hip working, inner thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"3-4 sets unless noted","items":[{"name":"Single-leg RDL to knee drive","steps":["Stand on one leg.","Hinge forward into a single-leg RDL, back leg lifting.","Stand up and drive the back knee up in front of you to hip height. Balance 1 sec.","That's 1 rep. All reps one side, then switch."],"feel":"bum, hamstring, balance","dont":"rush","sets":"4 x 20/side"},{"name":"Deep curtsy lunge, bottom pulses","steps":["Step one leg back and across into a deep curtsy, back knee near the floor, chest leaning slightly forward.","Stay low and pulse up and down a few centimetres in the bottom half only.","Keep your hips facing forward the whole time. All reps one side, then switch."],"feel":"outer bum of the front leg burning in the stretch","dont":"come all the way up or twist your hips","sets":"4 x 20/side, 3s hold at the end"},{"name":"Banded lateral walk","steps":["Put a mini band just above your knees (around your ankles is harder, around your feet is hardest).","Sit back into a quarter squat, chest up, feet hip-width apart.","Step sideways with control, keeping tension on the band the whole time. All steps one way, then come back."],"feel":"side of your bum burning","dont":"let your knees cave in or stand up tall","sets":"4 x 12 steps/side, band at feet"},{"name":"Single-leg bridge walkout","steps":["Lie in a bridge with one foot lifted.","On the working foot, slowly walk the heel out and back with your hips high.","All reps one side, then switch."],"feel":"back of thigh, bum","dont":"let your hips drop","sets":"4 x 12/side"},{"name":"Side-lying inner thigh lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Lie on your side, top leg bent with the foot in front, bottom leg straight.","Lift the bottom leg up toward the top leg, 2 sec up and 2 sec down.","All reps one side, then switch."],"feel":"inner thigh","dont":"roll your hips back","sets":"3 x 12/side"},{"name":"Side plank bottom-leg lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Side plank on your forearm, top foot in front of you on the floor.","Lift your bottom leg up to meet the top leg and hold.","Lower. All reps one side, then switch."],"feel":"inner thigh, side of waist","dont":"let your hips sag","sets":"3 x 15/side"},{"name":"Lateral lunge to curtsy flow","steps":["Step out into a side lunge, sitting back into that hip.","Push off and swing the same leg back and across into a curtsy lunge.","Stand up. Side lunge + curtsy = 1 rep. All reps one side, then switch."],"feel":"bum, outer hips, inner thighs","dont":"rush","sets":"4 x 15/side"},{"name":"Arabesque balance (standing leg, hands free)","steps":["Stand on one leg, hinge forward and lift the other leg straight back to parallel.","Arms reach forward, spine long, hips square.","Hold, then switch."],"feel":"bum and hamstring of the standing leg, balance","dont":"twist your hips open","sets":"3 x 45 sec/side"},{"name":"Prone hip extension (ankle weights)","steps":["Ankle weights on both legs.","Lie face down, forehead on your hands, legs straight.","Squeeze your bum and lift one straight leg a few cm off the floor.","Lower slowly. All reps one side, then switch."],"feel":"bum","dont":"lift by arching your lower back; small lift is fine","sets":"3 x 12/side, 3s hold"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"about 20 min","items":[{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"3 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"6 x 20 sec/side"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Seated forward fold","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null,"hold":"2 min"},{"name":"Lying figure-4 contract-relax","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"3 x 10 sec/side"}],"notes":[]}]},{"dow":"Saturday","title":"Skills + test day","flow":"Warm-up → Skill practice → Full-body flow → Test","sections":[{"kind":"strength","title":"SKILL PRACTICE","meta":"about 15-20 min. Counts are for the whole session, rest as long as you need between tries.","items":[{"name":"Freestanding handstand kick-up","steps":["Hands on the floor in open space, a wall within reach behind you if you have one.","Kick up softly with a straight leg and aim to balance over your hands.","Hold what you can, then step down or cartwheel out.","Can't yet? Back-to-wall holds, easing one heel off the wall at a time."],"feel":"shoulders, balance, core","dont":"kick past the balance point","sets":"8 attempts total"},{"name":"Crow pose (crane prep)","steps":["Squat with feet close, knees wide, hands flat shoulder-width, fingers spread.","Bend your elbows, rest your knees on the backs of your upper arms, lean forward.","Lift one foot, then the other, and hold. Look a hand-length ahead.","Can't yet? Rest your knees on your arms and lift one foot at a time."],"feel":"arms, core, balance","dont":"look straight down and tip forward","sets":"5 x up to 30 sec"},{"name":"Wall-assisted press to handstand","steps":["Face a wall in a pike, hands 30 cm from it.","Shift your shoulders over your hands and lift your hips over your shoulders, legs straight.","Rest your toes on the wall if needed. Lower with control.","Can't yet? Pike lean holds: shoulders over hands, hips high, toes light on the floor."],"feel":"shoulders, core, hip flexors","dont":"jump up","sets":"8 total"},{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3 easy sets of half your best"}],"notes":["Skills first while you are fresh. Warm up wrists and shoulders. Clear floor space, wall within reach, and know your cartwheel exit."],"bw":true},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"about 30 min","items":[{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Thread-the-needle (each side)","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"3 min"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"90 sec"},{"name":"Dancer pose (standing bow)","steps":["Stand on one leg, hold the other ankle behind you.","Kick your foot back into your hand while your torso tilts forward, free arm reaching ahead.","Hold, hips square, then switch."],"feel":"front of thigh and hip, balance","dont":null,"hold":"60 sec/side"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 45 sec"}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm)","Middle split: hips from floor (cm)","Deep squat hold time","Full bridge hold time","Handstand: longest clean hold in seconds (wall or freestanding)"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null,"hold":"2 min"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"1 min/side"},{"name":"Happy baby","steps":["Lie on your back, hold the outsides of your feet with knees wide.","Draw your knees toward your armpits and rock gently.","Hold."],"feel":"hips and lower back","dont":null,"hold":"2 min"},{"name":"Slow breathing","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null,"hold":"2 min"}],"notes":[]}]}]},{"n":13,"name":"Float","tagline":"Freestanding handstand work, one-arm push-ups, side crow and long V-sits.","bw":true,"info":[["Strength","3-4 sets, harder balance. Bodyweight, a pull-up bar, resistance bands, ankle weights and parallettes."],["Lower-body sets","About 81 hard sets a week on Mon, Thu and Fri: 23 hip-extension (bridge, hinge, hamstring), 30 squat, lunge and jump, 28 side-hip and inner-thigh. Plus Tuesday jumps. When a set gets easy, go up a band or add ankle weight first, then make it slower."],["Stretch holds","1-3 min holds. Bridge walk-ins 40 sec, active lift-offs 15 sec x 8, dancer pose 60 sec."],["Goals","Wall handstand push-up 5. One-arm push-up 2 per side. Tuck planche 20 sec. Freestanding handstand 5 sec. Side crow 20 sec per side. Single-leg bridge walkout 12 per side. Advanced tuck front lever 12 sec."],["Time here","About 6-8 weeks for the lower body. Skills like handstand push-ups and planche can lag behind: move up when the legs and glutes feel easy, and keep practising the skill step you're on (each one has a \\"Can't yet?\\" option)."],["Move to next plan","After about 6-8 weeks, when this whole week feels easy."],["Safety","Warm up first, never bounce in a stretch, stay at strong-but-comfortable. Pain, pinching or numbness means back off a step. Jumps: soft landings, clear floor. Handstand work: clear space, learn a cartwheel exit, stop if neck, wrists or shoulders hurt. Pull-up bar: check it is fixed solidly before every session and never jump to grab it."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"3-4 sets unless noted","items":[{"name":"Long-lever single-leg bridge","steps":["Lie on your back, one leg straight in the air, the other foot flat a long way from your hips.","Drive through that heel and lift your hips until your shoulders, hips and raised leg are in one line.","Lower slowly. All reps one side, then switch."],"feel":"bum and back of thigh","dont":"arch your lower back or twist your hips","sets":"4 x 10/side, 1.5 reps + 5s lowering"},{"name":"Forward-lean split squat","steps":["Stand in a long split stance, back heel up, feet hip-width apart like train tracks.","Lean your chest forward about 30-45 degrees with a flat back, hands on your hips or reaching forward.","Lower until your back knee lightly touches the floor and you feel a deep stretch in the bum of your front leg. Hold the pause.","Drive through the front heel to come up, stopping just short of standing so the glute keeps working. All reps one side, then switch."],"feel":"deep stretch and burn in the bum of the front leg","dont":"let the front knee cave in or the front heel lift","sets":"4 x 12/side, 5s lowering + 2s pause"},{"name":"Banded glute bridge","steps":["Loop a long resistance band over your hip crease and pin each end to the floor under your hands.","Feet flat, hip-width apart, heels about a hand-length from your bum.","Drive through your heels and lift your hips into the band until your body is straight from knees to shoulders. Squeeze hard at the top.","Lower slowly. Go up a band when every set feels easy."],"feel":"bum, working hard against the band at the top","dont":"arch your lower back to get higher","sets":"4 x 12, 1.5 reps + 3s squeeze"},{"name":"Skater squat","steps":["Stand on one leg, other leg behind you, arms swinging forward.","Lower on the standing leg until your back knee gently taps the floor.","Stand without pushing off the back foot. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the front knee cave in","sets":"4 x 12/side, 5s lowering"},{"name":"Curtsy lunge","steps":["Hands together at your chest, feet hip-width.","Step one leg back and across, bending both knees into a deep curtsy, hips facing forward.","Push through the front heel to stand. All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"twist your hips","sets":"4 x 10/side, 1.5 reps + 3s lowering"},{"name":"Fire hydrant + donkey kick combo, 2 sec hold (ankle weights)","steps":["Ankle weights on both legs.","On hands and knees.","Lift one bent leg out to the side and hold 2 sec. Bring it back.","Kick that foot up toward the ceiling and hold 2 sec. Bring it back. That's 1 rep.","All reps one side, then switch."],"feel":"all of your bum","dont":"arch your lower back","sets":"3 x 12/side"},{"name":"Star side plank","steps":["Side plank on your hand (arm straight) or elbow, feet stacked.","Lift your top leg up and reach your top arm to the ceiling, making a star.","Hold for the time, then switch."],"feel":"side of your bum and waist","dont":"let your hips sag","sets":"3 x 45 sec/side"},{"name":"Banded frog pump, 2 sec pause","steps":["Loop a long band over your hips and pin the ends under your hands.","Same as frog pump: on your back, soles together, knees out wide, heels near your bum.","Lift your hips by squeezing your bum.","Hold and squeeze for 2 sec at the top, then lower."],"feel":"bum, especially the sides","dont":"arch your lower back","sets":"4 x 25"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"about 25 min","items":[{"name":"90/90 hip switches","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null,"hold":"20 reps, hands off the floor"},{"name":"Figure-4 (on back)","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"2 min/side"},{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"King pigeon prep (hold your foot)","steps":["From pigeon, bend the back knee and reach back to hold that foot (or your shin).","Lift your chest and gently draw the foot toward your head.","Hold, then switch."],"feel":"front of the back thigh and hip, chest opening","dont":null,"hold":"2 min/side"},{"name":"Dancer pose (standing bow)","steps":["Stand on one leg, hold the other ankle behind you.","Kick your foot back into your hand while your torso tilts forward, free arm reaching ahead.","Hold, hips square, then switch."],"feel":"front of thigh and hip, balance","dont":null,"hold":"60 sec/side"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"}],"notes":[]}]},{"dow":"Tuesday","title":"Power + balance + front splits","flow":"Warm-up → Power + balance → Stretch","sections":[{"kind":"strength","title":"POWER + BALANCE","meta":"4 rounds, rest 60-90 sec between rounds. Quality over speed.","items":[{"name":"Arabesque balance (standing leg, hands free)","steps":["Stand on one leg, hinge forward and lift the other leg straight back to parallel.","Arms reach forward, spine long, hips square.","Hold, then switch."],"feel":"bum and hamstring of the standing leg, balance","dont":"twist your hips open","sets":"30 sec/side"},{"name":"Single-leg hop and stick","steps":["Stand on one leg, soft knee.","Hop forward about 50 cm and land softly on the same leg.","Freeze 2 sec, balanced, then repeat. All reps one side, then switch."],"feel":"outer hip, bum, balance","dont":"land stiff-legged or let the knee cave in","sets":"6/side"},{"name":"Tuck jump","steps":["Feet hip-width, quarter squat.","Jump straight up, pulling your knees toward your chest.","Land softly and go into the next one."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"8"},{"name":"Skater hops","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged","sets":"10/side"},{"name":"Broad jump and stick","steps":["Feet hip-width, swing your arms back.","Jump forward as far as you can and land softly in a squat.","Freeze 2 sec, walk back, repeat."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"5"}],"notes":["Soft, quiet landings on a clear floor. Stop a move when your form fades. This and Thursday are your only jump days."],"bw":true},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"about 35 min","items":[{"name":"Standing forward fold","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null,"hold":"2 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"2 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"3 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"8 x 15 sec/side"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Active leg raise (ankle weight)","steps":["Ankle weight on the lifting leg.","Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null,"hold":"8 x 15 sec/side"},{"name":"Standing front leg hold (ankle weight)","steps":["Ankle weight on the lifting leg.","Stand tall next to a wall, hand on it.","Lift your outside leg straight in front of you as high as you can, using only your leg muscles.","Hold for the time, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of thigh working, back of thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + skills + pull","flow":"Warm-up → Upper + skills → Pull → Stretch","sections":[{"kind":"strength","title":"UPPER + SKILLS","meta":"Straight sets, skills first: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Wall handstand push-up (full range)","steps":["Back-to-wall handstand.","Lower until the top of your head lightly touches the floor, elbows about 45 degrees.","Press back to straight arms. End the set if your form or neck feels off.","Can't yet? Short-range reps, then one slow negative to the floor."],"feel":"shoulders, triceps, core","dont":"bounce off your head","sets":"3-4 x up to 5"},{"name":"One-arm push-up (feet wide)","steps":["Full plank, feet wide, one hand behind your back.","Lower your chest toward the floor, elbow angled back, hips level.","Press up. All reps one side, then switch.","Can't yet? One-arm negatives."],"feel":"chest, arm, core","dont":"twist your hips open","sets":"3-4 x up to 2/side"},{"name":"Tuck planche hold (parallettes)","steps":["Hands on the parallettes beside your hips, knees tucked to your chest.","Lean forward, lock your arms and lift your feet off the floor.","Hold. Can't lift yet? Hold the forward lean."],"feel":"shoulders, arms, core","dont":"bend your arms","sets":"3-4 x up to 20 sec"},{"name":"V-sit (parallettes)","steps":["Sit between your parallettes, hands on the handles beside your hips.","Balance on your sit bones with your hands beside your hips, body in a V.","Hold.","Can't yet? L-sit, or a tuck sit with knees bent."],"feel":"abs, hip flexors, balance","dont":"round your upper back","sets":"3-4 x up to 40 sec"},{"name":"Side crow","steps":["Deep squat twisted to one side, hands flat, outer thighs against one upper arm.","Lean over your hands until your feet lift.","Hold, then switch sides.","Can't yet? Lift one foot at a time."],"feel":"arms, side of waist, balance","dont":"rush it","sets":"3-4 x up to 20 sec/side"},{"name":"Prone Y-T-W raise (floor)","steps":["Lie face down, forehead slightly off the floor.","Lift your arms into a Y, then a T, then a W, lowering between each.","One of each = 1 rep."],"feel":"upper back, rear shoulders","dont":"shrug up to your ears","sets":"3 x 10"},{"name":"Band pull-apart","steps":["Hold a light long band in front of your chest, hands shoulder-width, arms straight.","Pull the band apart by squeezing your shoulder blades together until it touches your chest.","Return slowly."],"feel":"upper back and the back of your shoulders","dont":"shrug or bend your elbows","sets":"3 x 15"}],"notes":["Upper-body volume stays modest on purpose: skill holds and slow reps build control and definition without bulky arms.","Y-T-W raises and snow angels keep your shoulders back and your posture tall. Pulling comes next."],"bw":true},{"kind":"strength","title":"PULL (BAR)","meta":"Straight sets: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3-4 x up to 8, 3s lowering"},{"name":"Advanced tuck front lever hold","steps":["Get into a tuck front lever.","Open your hips so your back stays flat and your knees move away from your chest, shins still tucked.","Hold, then lower with control.","Can't yet? Tuck front lever holds."],"feel":"lats and core, very hard","dont":"bend your arms or let your hips drop","sets":"3 x up to 12 sec"},{"name":"Toes-to-bar","steps":["Hang with straight arms, shoulders down.","Lift your straight legs all the way up until your toes touch the bar, rolling your pelvis up.","Lower slowly without swinging.","Can't yet? Hanging leg raises."],"feel":"abs, lats, grip","dont":"kip or swing","sets":"3 x up to 10"}],"notes":["Pulling stays at a moderate dose: enough for strong, healthy shoulders, a lifted posture and real pull-up strength, without building a wide V-shaped back."],"bw":true},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"about 25 min","items":[{"name":"Wrist circles and palm lifts","steps":["Kneel with palms flat, fingers forward, then back, then out. Lean gently back and forth.","Lift your palms, keep fingers down, then circle each wrist slowly.","Stay at a mild stretch, never force."],"feel":"wrists and forearms","dont":null,"hold":"2 min"},{"name":"Cat-cow","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null,"hold":"15 reps"},{"name":"Thread-the-needle","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"90 sec/side"},{"name":"Sphinx or cobra","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null,"hold":"90 sec"},{"name":"Clasped-hands chest opener (kneeling)","steps":["Kneel tall, clasp your hands behind your back.","Straighten your arms and lift them away from your back, chest open.","Hold."],"feel":"chest and front shoulders","dont":null,"hold":"90 sec"},{"name":"Puppy pose","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null,"hold":"2 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"90 sec"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 45 sec"},{"name":"Bridge walk-in (hands toward feet)","steps":["Get into a full bridge.","Walk your hands one small step toward your feet, pressing your chest forward over your hands.","Hold, then walk back. Lower by tucking your chin."],"feel":"shoulders, spine, front of hips","dont":null,"hold":"3 x 40 sec"},{"name":"Bridge, one leg lifted","steps":["Get into a full bridge.","Shift weight onto one leg and lift the other straight up toward the ceiling.","Hold, lower, switch."],"feel":"hips, shoulders, balance","dont":null,"hold":"3 x 15 sec/side"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"90 sec/side"}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"3-4 sets unless noted","items":[{"name":"Pistol squat","steps":["Stand on one leg, free leg straight out in front, arms reaching forward.","Squat down as low as you can control, heel down. Stop at 90 degrees if you can't go deeper yet.","Stand back up with no hands. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the knee cave in","sets":"4 x 10/side, 5s lowering"},{"name":"Shrimp squat (floor)","steps":["Stand on one leg, hold the other foot behind you with the same-side hand.","Lower until your back knee gently touches the floor, torso leaning forward.","Stand back up. All reps one side, then switch."],"feel":"front thigh and bum","dont":"drop onto the knee","sets":"4 x 10/side, 5s lowering"},{"name":"Deep reverse lunge, forward lean","steps":["Stand tall, then take a long step back and lower until your back knee nearly touches the floor.","Hinge your chest forward over the front thigh with a flat back, fingertips reaching toward the floor beside your front foot.","Pause at the bottom, then push through the front heel to stand. All reps one side, then switch."],"feel":"bum and back of the front thigh","dont":"take a short step or round your back","sets":"4 x 10/side, 5s lowering"},{"name":"Reverse Nordic curl","steps":["Kneel tall, arms crossed or reaching forward.","Lean back from the knees as far as you can control, hips pushed forward.","Use your thighs to pull back up.","Can't yet? Lean back only a little and build the range slowly."],"feel":"front of thighs, long stretch","dont":"bend at the hips","sets":"4 x 12"},{"name":"Broad jump and stick","steps":["Feet hip-width, swing your arms back.","Jump forward as far as you can and land softly in a squat.","Freeze 2 sec, walk back, repeat."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"3 x 6"},{"name":"Single-leg hop and stick","steps":["Stand on one leg, soft knee.","Hop forward about 50 cm and land softly on the same leg.","Freeze 2 sec, balanced, then repeat. All reps one side, then switch."],"feel":"outer hip, bum, balance","dont":"land stiff-legged or let the knee cave in","sets":"3 x 6/side"},{"name":"Single-leg calf raise (floor, slow)","steps":["Stand on one foot, fingertips on a wall for balance if needed.","Rise as high as you can: 3 sec up, 1 sec pause, 3 sec down.","All reps one side, then switch."],"feel":"calf","dont":"bounce","sets":"3 x 15/side"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"about 25 min","items":[{"name":"Butterfly","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null,"hold":"2 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Straddle fold, chest to floor","steps":["Sit in a wide straddle, toes up.","Walk your hands forward and slowly lower your chest toward the floor.","Hold, breathing slowly."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Active straddle lift-offs","steps":["Sit in a wide straddle, hands on the floor in front of you.","Lift one straight leg a few cm using your leg muscles, hold, lower. Alternate.","Keep your back flat."],"feel":"inner thighs stretching, hips working","dont":null,"hold":"6 x 12 sec"},{"name":"Cossack squat hold (floor)","steps":["Feet very wide, sit into one side with the other leg straight, toes up.","Hold, chest tall, then switch.","Keep the bent-leg heel down."],"feel":"inner thigh, hip","dont":null,"hold":"45 sec x 4/side"},{"name":"Side leg hold (ankle weight)","steps":["Ankle weight on the lifting leg.","Stand tall, side-on to a wall, hand on it.","Lift your outside leg straight out to the side as high as you can, toes forward.","Hold for the time, lower. Do all reps, then switch."],"feel":"side of hip working, inner thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"3-4 sets unless noted","items":[{"name":"Single-leg RDL to knee drive","steps":["Stand on one leg.","Hinge forward into a single-leg RDL, back leg lifting.","Stand up and drive the back knee up in front of you to hip height. Balance 1 sec.","That's 1 rep. All reps one side, then switch."],"feel":"bum, hamstring, balance","dont":"rush","sets":"4 x 20/side"},{"name":"Deep curtsy lunge, bottom pulses","steps":["Step one leg back and across into a deep curtsy, back knee near the floor, chest leaning slightly forward.","Stay low and pulse up and down a few centimetres in the bottom half only.","Keep your hips facing forward the whole time. All reps one side, then switch."],"feel":"outer bum of the front leg burning in the stretch","dont":"come all the way up or twist your hips","sets":"4 x 20/side, 5s hold at the end"},{"name":"Banded lateral walk","steps":["Put a mini band just above your knees (around your ankles is harder, around your feet is hardest).","Sit back into a quarter squat, chest up, feet hip-width apart.","Step sideways with control, keeping tension on the band the whole time. All steps one way, then come back."],"feel":"side of your bum burning","dont":"let your knees cave in or stand up tall","sets":"4 x 15 steps/side, band at feet"},{"name":"Single-leg bridge walkout","steps":["Lie in a bridge with one foot lifted.","On the working foot, slowly walk the heel out and back with your hips high.","All reps one side, then switch."],"feel":"back of thigh, bum","dont":"let your hips drop","sets":"4 x 12/side"},{"name":"Side-lying inner thigh lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Lie on your side, top leg bent with the foot in front, bottom leg straight.","Lift the bottom leg up toward the top leg, 2 sec up and 2 sec down.","All reps one side, then switch."],"feel":"inner thigh","dont":"roll your hips back","sets":"3 x 12/side"},{"name":"Side plank bottom-leg lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Side plank on your forearm, top foot in front of you on the floor.","Lift your bottom leg up to meet the top leg and hold.","Lower. All reps one side, then switch."],"feel":"inner thigh, side of waist","dont":"let your hips sag","sets":"3 x 20/side"},{"name":"Lateral lunge to curtsy flow","steps":["Step out into a side lunge, sitting back into that hip.","Push off and swing the same leg back and across into a curtsy lunge.","Stand up. Side lunge + curtsy = 1 rep. All reps one side, then switch."],"feel":"bum, outer hips, inner thighs","dont":"rush","sets":"4 x 15/side"},{"name":"Arabesque balance (standing leg, hands free)","steps":["Stand on one leg, hinge forward and lift the other leg straight back to parallel.","Arms reach forward, spine long, hips square.","Hold, then switch."],"feel":"bum and hamstring of the standing leg, balance","dont":"twist your hips open","sets":"3 x 45 sec/side, eyes closed last 20s"},{"name":"Prone hip extension (ankle weights)","steps":["Ankle weights on both legs.","Lie face down, forehead on your hands, legs straight.","Squeeze your bum and lift one straight leg a few cm off the floor.","Lower slowly. All reps one side, then switch."],"feel":"bum","dont":"lift by arching your lower back; small lift is fine","sets":"3 x 12/side, 3s hold"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"about 20 min","items":[{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"3 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"8 x 15 sec/side"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Seated forward fold","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null,"hold":"2 min"},{"name":"Lying figure-4 contract-relax","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"3 x 10 sec/side"}],"notes":[]}]},{"dow":"Saturday","title":"Skills + test day","flow":"Warm-up → Skill practice → Full-body flow → Test","sections":[{"kind":"strength","title":"SKILL PRACTICE","meta":"about 15-20 min. Counts are for the whole session, rest as long as you need between tries.","items":[{"name":"Freestanding handstand kick-up","steps":["Hands on the floor in open space, a wall within reach behind you if you have one.","Kick up softly with a straight leg and aim to balance over your hands.","Hold what you can, then step down or cartwheel out.","Can't yet? Back-to-wall holds, easing one heel off the wall at a time."],"feel":"shoulders, balance, core","dont":"kick past the balance point","sets":"10 attempts total, aim for 5 sec"},{"name":"Side crow","steps":["Deep squat twisted to one side, hands flat, outer thighs against one upper arm.","Lean over your hands until your feet lift.","Hold, then switch sides.","Can't yet? Lift one foot at a time."],"feel":"arms, side of waist, balance","dont":"rush it","sets":"4 x up to 20 sec/side"},{"name":"Press to handstand attempt","steps":["Straddle or pike stance, hands on the floor.","Shift your shoulders forward and lift your hips over your hands with straight arms.","Stack into a handstand, hold, lower with control.","Can't yet? Wall-assisted press to handstand."],"feel":"shoulders, core, hips","dont":"jump instead of press","sets":"6 attempts total"},{"name":"Handstand walk (steps)","steps":["Kick up to a freestanding handstand.","Shift weight to one hand and take a small step with the other.","Walk as many steps as you can, then come down safely.","Can't yet? Shoulder taps in a chest-to-wall handstand."],"feel":"shoulders, balance, core","dont":"rush your steps","sets":"6 attempts total"},{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3 easy sets of half your best"}],"notes":["Skills first while you are fresh. Warm up wrists and shoulders. Clear floor space, wall within reach, and know your cartwheel exit."],"bw":true},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"about 30 min","items":[{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Thread-the-needle (each side)","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"3 min"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"90 sec"},{"name":"Dancer pose (standing bow)","steps":["Stand on one leg, hold the other ankle behind you.","Kick your foot back into your hand while your torso tilts forward, free arm reaching ahead.","Hold, hips square, then switch."],"feel":"front of thigh and hip, balance","dont":null,"hold":"60 sec/side"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 45 sec"}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm)","Middle split: hips from floor (cm)","Deep squat hold time","Full bridge hold time","Handstand: longest clean hold in seconds (wall or freestanding)"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null,"hold":"2 min"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"1 min/side"},{"name":"Happy baby","steps":["Lie on your back, hold the outsides of your feet with knees wide.","Draw your knees toward your armpits and rock gently.","Hold."],"feel":"hips and lower back","dont":null,"hold":"2 min"},{"name":"Slow breathing","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null,"hold":"2 min"}],"notes":[]}]}]},{"n":14,"name":"Apex","tagline":"The top of nothing-needed training: handstand push-ups, one-arm push-ups, advanced tuck planche, handstand walking and deep full-range flexibility.","bw":true,"info":[["Strength","3-4 sets, near-max. Bodyweight, a pull-up bar, resistance bands, ankle weights and parallettes."],["Lower-body sets","About 85 hard sets a week on Mon, Thu and Fri: 23 hip-extension (bridge, hinge, hamstring), 30 squat, lunge and jump, 32 side-hip and inner-thigh. Plus Tuesday jumps. When a set gets easy, go up a band or add ankle weight first, then make it slower."],["Stretch holds","1-3 min holds. Needle scale, dancer pose 90 sec, active lift-offs 20 sec x 8."],["Goals","Wall handstand push-up 8. One-arm push-up 4 per side. Advanced tuck planche 8 sec. Freestanding handstand 15 sec. Pistol 12 per side with a 5 sec lowering. Single-leg bridge walkout 15 per side. Pull-ups 10. Advanced tuck front lever 15 sec."],["Time here","About 6-8 weeks for the lower body. Skills like handstand push-ups and planche can lag behind: move up when the legs and glutes feel easy, and keep practising the skill step you're on (each one has a \\"Can't yet?\\" option)."],["Move to next plan","This is the top. Keep repeating it: slower lowering, longer pauses, cleaner holds, and the next skill step."],["Safety","Warm up first, never bounce in a stretch, stay at strong-but-comfortable. Pain, pinching or numbness means back off a step. Jumps: soft landings, clear floor. Handstand work: clear space, learn a cartwheel exit, stop if neck, wrists or shoulders hurt. Pull-up bar: check it is fixed solidly before every session and never jump to grab it."]],"days":[{"dow":"Monday","title":"Glutes","flow":"Warm-up → Strength A → Stretch","sections":[{"kind":"strength","title":"STRENGTH A: GLUTES","meta":"3-4 sets unless noted","items":[{"name":"Long-lever single-leg bridge","steps":["Lie on your back, one leg straight in the air, the other foot flat a long way from your hips.","Drive through that heel and lift your hips until your shoulders, hips and raised leg are in one line.","Lower slowly. All reps one side, then switch."],"feel":"bum and back of thigh","dont":"arch your lower back or twist your hips","sets":"4 x 12/side, 1.5 reps + 5s lowering"},{"name":"Forward-lean split squat","steps":["Stand in a long split stance, back heel up, feet hip-width apart like train tracks.","Lean your chest forward about 30-45 degrees with a flat back, hands on your hips or reaching forward.","Lower until your back knee lightly touches the floor and you feel a deep stretch in the bum of your front leg. Hold the pause.","Drive through the front heel to come up, stopping just short of standing so the glute keeps working. All reps one side, then switch."],"feel":"deep stretch and burn in the bum of the front leg","dont":"let the front knee cave in or the front heel lift","sets":"4 x 12/side, 1.5 reps + 5s lowering"},{"name":"Banded glute bridge","steps":["Loop a long resistance band over your hip crease and pin each end to the floor under your hands.","Feet flat, hip-width apart, heels about a hand-length from your bum.","Drive through your heels and lift your hips into the band until your body is straight from knees to shoulders. Squeeze hard at the top.","Lower slowly. Go up a band when every set feels easy."],"feel":"bum, working hard against the band at the top","dont":"arch your lower back to get higher","sets":"4 x 15, 1.5 reps + 3s squeeze"},{"name":"Skater squat","steps":["Stand on one leg, other leg behind you, arms swinging forward.","Lower on the standing leg until your back knee gently taps the floor.","Stand without pushing off the back foot. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the front knee cave in","sets":"4 x 12/side, 5s lowering"},{"name":"Curtsy lunge","steps":["Hands together at your chest, feet hip-width.","Step one leg back and across, bending both knees into a deep curtsy, hips facing forward.","Push through the front heel to stand. All reps one side, then switch."],"feel":"outer bum of the front leg","dont":"twist your hips","sets":"4 x 12/side, 1.5 reps + 3s lowering"},{"name":"Fire hydrant + donkey kick combo, 2 sec hold (ankle weights)","steps":["Ankle weights on both legs.","On hands and knees.","Lift one bent leg out to the side and hold 2 sec. Bring it back.","Kick that foot up toward the ceiling and hold 2 sec. Bring it back. That's 1 rep.","All reps one side, then switch."],"feel":"all of your bum","dont":"arch your lower back","sets":"3 x 12/side"},{"name":"Star side plank","steps":["Side plank on your hand (arm straight) or elbow, feet stacked.","Lift your top leg up and reach your top arm to the ceiling, making a star.","Hold for the time, then switch."],"feel":"side of your bum and waist","dont":"let your hips sag","sets":"3 x 45 sec/side"},{"name":"Banded frog pump, 2 sec pause","steps":["Loop a long band over your hips and pin the ends under your hands.","Same as frog pump: on your back, soles together, knees out wide, heels near your bum.","Lift your hips by squeezing your bum.","Hold and squeeze for 2 sec at the top, then lower."],"feel":"bum, especially the sides","dont":"arch your lower back","sets":"4 x 25"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: HIPS AND GLUTES","meta":"about 30 min","items":[{"name":"90/90 hip switches","steps":["Sit on the floor, knees bent, feet flat and wide apart, hands behind you.","Let both knees drop to the right so both legs make 90-degree angles (front leg and back leg).","Lift both knees back up and drop them to the left. That's 1 rep."],"feel":"hips","dont":null,"hold":"20 reps, hands off the floor"},{"name":"Figure-4 (on back)","steps":["Lie on your back, knees bent, feet flat.","Cross your right ankle over your left knee.","Lift your left foot and pull your left thigh toward your chest until you feel it in your right bum.","Hold, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"2 min/side"},{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"King pigeon prep (hold your foot)","steps":["From pigeon, bend the back knee and reach back to hold that foot (or your shin).","Lift your chest and gently draw the foot toward your head.","Hold, then switch."],"feel":"front of the back thigh and hip, chest opening","dont":null,"hold":"2 min/side"},{"name":"Dancer pose (standing bow)","steps":["Stand on one leg, hold the other ankle behind you.","Kick your foot back into your hand while your torso tilts forward, free arm reaching ahead.","Hold, hips square, then switch."],"feel":"front of thigh and hip, balance","dont":null,"hold":"90 sec/side"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"}],"notes":[]}]},{"dow":"Tuesday","title":"Power + balance + front splits","flow":"Warm-up → Power + balance → Stretch","sections":[{"kind":"strength","title":"POWER + BALANCE","meta":"4 rounds, rest 60-90 sec between rounds. Quality over speed.","items":[{"name":"Arabesque balance (standing leg, hands free)","steps":["Stand on one leg, hinge forward and lift the other leg straight back to parallel.","Arms reach forward, spine long, hips square.","Hold, then switch."],"feel":"bum and hamstring of the standing leg, balance","dont":"twist your hips open","sets":"30 sec/side"},{"name":"Single-leg hop and stick","steps":["Stand on one leg, soft knee.","Hop forward about 50 cm and land softly on the same leg.","Freeze 2 sec, balanced, then repeat. All reps one side, then switch."],"feel":"outer hip, bum, balance","dont":"land stiff-legged or let the knee cave in","sets":"6/side"},{"name":"Tuck jump","steps":["Feet hip-width, quarter squat.","Jump straight up, pulling your knees toward your chest.","Land softly and go into the next one."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"8"},{"name":"Skater hops","steps":["Stand on your right leg.","Hop sideways to your left, landing softly on your left leg, right leg sweeping behind you.","Stick the landing for a second, then hop back. Each landing = 1 rep on that side."],"feel":"outer hips, bum, balance","dont":"land stiff-legged","sets":"10/side"},{"name":"Broad jump and stick","steps":["Feet hip-width, swing your arms back.","Jump forward as far as you can and land softly in a squat.","Freeze 2 sec, walk back, repeat."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"5"}],"notes":["Soft, quiet landings on a clear floor. Stop a move when your form fades. This and Thursday are your only jump days."],"bw":true},{"kind":"stretch","title":"STRETCH: FRONT SPLITS AND HAMSTRINGS","meta":"about 35 min","items":[{"name":"Standing forward fold","steps":["Stand with feet hip-width, knees soft.","Hinge at your hips and let your upper body hang down, head and arms heavy.","Breathe and let gravity pull you lower each exhale."],"feel":"back of thighs, lower back","dont":null,"hold":"2 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"2 min/side"},{"name":"Low lunge hip flexor (back foot held)","steps":["Low lunge with your back knee on the floor.","Reach back and hold the back foot (or your shin), tilting your pelvis under.","Sink your hips forward. Hold, then switch."],"feel":"front of the back hip and thigh","dont":null,"hold":"2 min/side"},{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"3 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"8 x 20 sec/side"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Active leg raise (ankle weight)","steps":["Ankle weight on the lifting leg.","Lie on your back, both legs straight.","Lift one straight leg as high as you can using only your leg muscles (no hands).","Hold it up for the time listed, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of the lifting leg working, back of it stretching","dont":null,"hold":"8 x 15 sec/side"},{"name":"Standing front leg hold (ankle weight)","steps":["Ankle weight on the lifting leg.","Stand tall next to a wall, hand on it.","Lift your outside leg straight in front of you as high as you can, using only your leg muscles.","Hold for the time, lower. That's 1 rep. Do all reps, then switch."],"feel":"front of thigh working, back of thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Wednesday","title":"Upper body + skills + pull","flow":"Warm-up → Upper + skills → Pull → Stretch","sections":[{"kind":"strength","title":"UPPER + SKILLS","meta":"Straight sets, skills first: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Wall handstand push-up (full range)","steps":["Back-to-wall handstand.","Lower until the top of your head lightly touches the floor, elbows about 45 degrees.","Press back to straight arms. End the set if your form or neck feels off.","Can't yet? Short-range reps, then one slow negative to the floor."],"feel":"shoulders, triceps, core","dont":"bounce off your head","sets":"3-4 x up to 8"},{"name":"One-arm push-up (feet wide)","steps":["Full plank, feet wide, one hand behind your back.","Lower your chest toward the floor, elbow angled back, hips level.","Press up. All reps one side, then switch.","Can't yet? One-arm negatives."],"feel":"chest, arm, core","dont":"twist your hips open","sets":"3-4 x up to 4/side"},{"name":"Advanced tuck planche hold (parallettes)","steps":["Hands on the parallettes beside your hips, knees tucked to your chest.","Lean forward, lock your arms, lift your feet, then open your hips until your back is flat.","Hold. Can't open your hips yet? Stay in the regular tuck planche."],"feel":"shoulders, core, arms, very hard","dont":"bend your arms","sets":"3-4 x up to 8 sec"},{"name":"V-sit (parallettes)","steps":["Sit between your parallettes, hands on the handles beside your hips.","Balance on your sit bones with your hands beside your hips, body in a V.","Hold.","Can't yet? L-sit, or a tuck sit with knees bent."],"feel":"abs, hip flexors, balance","dont":"round your upper back","sets":"3-4 x up to 45 sec"},{"name":"Crane pose (straight-arm crow)","steps":["Start in crow with your knees high on your upper arms.","Slowly straighten your arms as you shift your hips up and back.","Hold, then lower with control.","Can't yet? Hold crow and straighten your arms a little more each week."],"feel":"arms, core, wrists","dont":"let your head drop forward","sets":"3-4 x up to 20 sec"},{"name":"Prone Y-T-W raise (floor)","steps":["Lie face down, forehead slightly off the floor.","Lift your arms into a Y, then a T, then a W, lowering between each.","One of each = 1 rep."],"feel":"upper back, rear shoulders","dont":"shrug up to your ears","sets":"3 x 10"},{"name":"Band pull-apart","steps":["Hold a light long band in front of your chest, hands shoulder-width, arms straight.","Pull the band apart by squeezing your shoulder blades together until it touches your chest.","Return slowly."],"feel":"upper back and the back of your shoulders","dont":"shrug or bend your elbows","sets":"3 x 15"}],"notes":["Upper-body volume stays modest on purpose: skill holds and slow reps build control and definition without bulky arms.","Y-T-W raises and snow angels keep your shoulders back and your posture tall. Pulling comes next."],"bw":true},{"kind":"strength","title":"PULL (BAR)","meta":"Straight sets: 3-4 sets of each, rest about 90 sec. Stop each set 1-2 reps short of your best.","items":[{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3-4 x up to 10"},{"name":"Archer pull-up","steps":["Hang with a very wide grip.","Pull up toward one hand while the other arm straightens out along the bar.","Lower with control, then pull to the other side. Each side = 1 rep.","Can't yet? Slow pull-ups with a 3 sec lowering."],"feel":"lats and arm of the pulling side","dont":"swing or twist","sets":"3 x up to 3/side"},{"name":"Advanced tuck front lever hold","steps":["Get into a tuck front lever.","Open your hips so your back stays flat and your knees move away from your chest, shins still tucked.","Hold, then lower with control.","Can't yet? Tuck front lever holds."],"feel":"lats and core, very hard","dont":"bend your arms or let your hips drop","sets":"3 x up to 15 sec"},{"name":"Toes-to-bar","steps":["Hang with straight arms, shoulders down.","Lift your straight legs all the way up until your toes touch the bar, rolling your pelvis up.","Lower slowly without swinging.","Can't yet? Hanging leg raises."],"feel":"abs, lats, grip","dont":"kip or swing","sets":"3 x up to 12"}],"notes":["Pulling stays at a moderate dose: enough for strong, healthy shoulders, a lifted posture and real pull-up strength, without building a wide V-shaped back."],"bw":true},{"kind":"stretch","title":"STRETCH: SPINE AND SHOULDERS","meta":"about 25 min","items":[{"name":"Wrist circles and palm lifts","steps":["Kneel with palms flat, fingers forward, then back, then out. Lean gently back and forth.","Lift your palms, keep fingers down, then circle each wrist slowly.","Stay at a mild stretch, never force."],"feel":"wrists and forearms","dont":null,"hold":"2 min"},{"name":"Cat-cow","steps":["Get on hands and knees.","Breathe in: drop your belly, lift your chest and tailbone (cow).","Breathe out: round your back up toward the ceiling, tuck your chin (cat). That's 1 rep."],"feel":"whole spine moving","dont":null,"hold":"15 reps"},{"name":"Thread-the-needle","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"90 sec/side"},{"name":"Sphinx or cobra","steps":["Lie face down.","Sphinx: prop up on your forearms, elbows under shoulders. Cobra (deeper): hands under shoulders, straighten arms.","Lift your chest, keep hips on the floor, shoulders down. Hold."],"feel":"lower back and front of body opening","dont":null,"hold":"90 sec"},{"name":"Clasped-hands chest opener (kneeling)","steps":["Kneel tall, clasp your hands behind your back.","Straighten your arms and lift them away from your back, chest open.","Hold."],"feel":"chest and front shoulders","dont":null,"hold":"90 sec"},{"name":"Puppy pose","steps":["Start on hands and knees.","Keep hips above knees and walk your hands forward.","Let your chest melt toward the floor, forehead down, arms straight. Hold."],"feel":"shoulders and upper back","dont":null,"hold":"2 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"90 sec"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 45 sec"},{"name":"Bridge walk-in (hands toward feet)","steps":["Get into a full bridge.","Walk your hands one small step toward your feet, pressing your chest forward over your hands.","Hold, then walk back. Lower by tucking your chin."],"feel":"shoulders, spine, front of hips","dont":null,"hold":"3 x 40 sec"},{"name":"Bridge, one leg lifted","steps":["Get into a full bridge.","Shift weight onto one leg and lift the other straight up toward the ceiling.","Hold, lower, switch."],"feel":"hips, shoulders, balance","dont":null,"hold":"3 x 15 sec/side"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"90 sec/side"}],"notes":[]}]},{"dow":"Thursday","title":"Thighs and legs","flow":"Warm-up → Strength B → Stretch","sections":[{"kind":"strength","title":"STRENGTH B: THIGHS AND LEGS","meta":"3-4 sets unless noted","items":[{"name":"Pistol squat","steps":["Stand on one leg, free leg straight out in front, arms reaching forward.","Squat down as low as you can control, heel down. Stop at 90 degrees if you can't go deeper yet.","Stand back up with no hands. All reps one side, then switch."],"feel":"thigh and bum","dont":"let the knee cave in","sets":"4 x 10/side, 5s lowering + 2s pause"},{"name":"Shrimp squat (floor)","steps":["Stand on one leg, hold the other foot behind you with the same-side hand.","Lower until your back knee gently touches the floor, torso leaning forward.","Stand back up. All reps one side, then switch."],"feel":"front thigh and bum","dont":"drop onto the knee","sets":"4 x 10/side, 5s lowering"},{"name":"Deep reverse lunge, forward lean","steps":["Stand tall, then take a long step back and lower until your back knee nearly touches the floor.","Hinge your chest forward over the front thigh with a flat back, fingertips reaching toward the floor beside your front foot.","Pause at the bottom, then push through the front heel to stand. All reps one side, then switch."],"feel":"bum and back of the front thigh","dont":"take a short step or round your back","sets":"4 x 12/side, 5s lowering + 2s pause"},{"name":"Reverse Nordic curl","steps":["Kneel tall, arms crossed or reaching forward.","Lean back from the knees as far as you can control, hips pushed forward.","Use your thighs to pull back up.","Can't yet? Lean back only a little and build the range slowly."],"feel":"front of thighs, long stretch","dont":"bend at the hips","sets":"4 x 12"},{"name":"Broad jump and stick","steps":["Feet hip-width, swing your arms back.","Jump forward as far as you can and land softly in a squat.","Freeze 2 sec, walk back, repeat."],"feel":"thighs, bum, power","dont":"land with straight legs","sets":"3 x 6"},{"name":"Single-leg hop and stick","steps":["Stand on one leg, soft knee.","Hop forward about 50 cm and land softly on the same leg.","Freeze 2 sec, balanced, then repeat. All reps one side, then switch."],"feel":"outer hip, bum, balance","dont":"land stiff-legged or let the knee cave in","sets":"3 x 6/side"},{"name":"Cossack squat (bodyweight)","steps":["Feet very wide, toes slightly out.","Sit down into one side, other leg straight with toes up. Heel of the bent leg stays down.","Push back up and switch sides. Each side = 1 rep."],"feel":"bum and inner thighs","dont":"lift the heel of the bent leg","sets":"4 x 12/side, 3s pause"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: MIDDLE SPLITS AND INNER THIGHS","meta":"about 25 min","items":[{"name":"Butterfly","steps":["Sit up tall, soles of your feet together, knees falling out.","Hold your feet and pull your heels in toward you.","Keeping your back straight, hinge forward from your hips. Hold."],"feel":"inner thighs","dont":null,"hold":"2 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Straddle fold, chest to floor","steps":["Sit in a wide straddle, toes up.","Walk your hands forward and slowly lower your chest toward the floor.","Hold, breathing slowly."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Active straddle lift-offs","steps":["Sit in a wide straddle, hands on the floor in front of you.","Lift one straight leg a few cm using your leg muscles, hold, lower. Alternate.","Keep your back flat."],"feel":"inner thighs stretching, hips working","dont":null,"hold":"6 x 12 sec"},{"name":"Cossack squat hold (floor)","steps":["Feet very wide, sit into one side with the other leg straight, toes up.","Hold, chest tall, then switch.","Keep the bent-leg heel down."],"feel":"inner thigh, hip","dont":null,"hold":"45 sec x 4/side"},{"name":"Side leg hold (ankle weight)","steps":["Ankle weight on the lifting leg.","Stand tall, side-on to a wall, hand on it.","Lift your outside leg straight out to the side as high as you can, toes forward.","Hold for the time, lower. Do all reps, then switch."],"feel":"side of hip working, inner thigh stretching","dont":null,"hold":"6 x 15 sec/side"}],"notes":[]}]},{"dow":"Friday","title":"Hips + hamstrings","flow":"Warm-up → Strength C → Stretch","sections":[{"kind":"strength","title":"STRENGTH C: HIPS + HAMSTRINGS","meta":"3-4 sets unless noted","items":[{"name":"Single-leg RDL to knee drive","steps":["Stand on one leg.","Hinge forward into a single-leg RDL, back leg lifting.","Stand up and drive the back knee up in front of you to hip height. Balance 1 sec.","That's 1 rep. All reps one side, then switch."],"feel":"bum, hamstring, balance","dont":"rush","sets":"4 x 20/side"},{"name":"Deep curtsy lunge, bottom pulses","steps":["Step one leg back and across into a deep curtsy, back knee near the floor, chest leaning slightly forward.","Stay low and pulse up and down a few centimetres in the bottom half only.","Keep your hips facing forward the whole time. All reps one side, then switch."],"feel":"outer bum of the front leg burning in the stretch","dont":"come all the way up or twist your hips","sets":"4 x 20/side, 10s hold at the end"},{"name":"Banded lateral walk","steps":["Put a mini band just above your knees (around your ankles is harder, around your feet is hardest).","Sit back into a quarter squat, chest up, feet hip-width apart.","Step sideways with control, keeping tension on the band the whole time. All steps one way, then come back."],"feel":"side of your bum burning","dont":"let your knees cave in or stand up tall","sets":"4 x 15 steps/side, band at feet, 2s pause each step"},{"name":"Single-leg bridge walkout","steps":["Lie in a bridge with one foot lifted.","On the working foot, slowly walk the heel out and back with your hips high.","All reps one side, then switch."],"feel":"back of thigh, bum","dont":"let your hips drop","sets":"4 x 15/side"},{"name":"Side-lying inner thigh lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Lie on your side, top leg bent with the foot in front, bottom leg straight.","Lift the bottom leg up toward the top leg, 2 sec up and 2 sec down.","All reps one side, then switch."],"feel":"inner thigh","dont":"roll your hips back","sets":"3 x 12/side"},{"name":"Side plank bottom-leg lift (ankle weights)","steps":["Ankle weight on your bottom leg.","Side plank on your forearm, top foot in front of you on the floor.","Lift your bottom leg up to meet the top leg and hold.","Lower. All reps one side, then switch."],"feel":"inner thigh, side of waist","dont":"let your hips sag","sets":"3 x 20/side"},{"name":"Lateral lunge to curtsy flow","steps":["Step out into a side lunge, sitting back into that hip.","Push off and swing the same leg back and across into a curtsy lunge.","Stand up. Side lunge + curtsy = 1 rep. All reps one side, then switch."],"feel":"bum, outer hips, inner thighs","dont":"rush","sets":"4 x 15/side"},{"name":"Arabesque balance (standing leg, hands free)","steps":["Stand on one leg, hinge forward and lift the other leg straight back to parallel.","Arms reach forward, spine long, hips square.","Hold, then switch."],"feel":"bum and hamstring of the standing leg, balance","dont":"twist your hips open","sets":"3 x 45 sec/side, eyes closed"},{"name":"Prone hip extension (ankle weights)","steps":["Ankle weights on both legs.","Lie face down, forehead on your hands, legs straight.","Squeeze your bum and lift one straight leg a few cm off the floor.","Lower slowly. All reps one side, then switch."],"feel":"bum","dont":"lift by arching your lower back; small lift is fine","sets":"3 x 12/side, 3s hold"}],"notes":[],"bw":true},{"kind":"stretch","title":"STRETCH: SPLITS INTEGRATION","meta":"about 20 min","items":[{"name":"Front split, hands off (prayer)","steps":["Get into your lowest front split.","Lift your hands off the floor, palms together at your chest, and hold with your legs.","Hold, then switch."],"feel":"hips and thighs working while stretching","dont":null,"hold":"3 min/side"},{"name":"Active front split lift-offs (hands off)","steps":["Get into your lowest front split, palms together at your chest.","Press your legs into the floor and lift your hips a few cm, hold, lower.","Switch sides."],"feel":"hips and thighs working while stretching","dont":null,"hold":"8 x 20 sec/side"},{"name":"Middle split","steps":["Kneel or stand with legs wide, hands on the floor in front of you.","Slide your feet out until you're as low as you can go. Toes up or forward.","Rest on your forearms if you can. Hold."],"feel":"inner thighs","dont":null,"hold":"3 min"},{"name":"Needle scale (standing split, hold ankle)","steps":["Fold forward and hold the ankle of your standing leg with both hands.","Lift the other leg straight up behind you toward vertical.","Hold, hips as square as you can. Switch."],"feel":"back of the standing leg, front of the lifted hip","dont":null,"hold":"90 sec/side"},{"name":"Seated forward fold","steps":["Sit with legs straight out in front, toes up.","Sit tall, then hinge from your hips and reach for your feet (or shins).","Keep your chest long instead of rounding. Hold."],"feel":"back of thighs","dont":null,"hold":"2 min"},{"name":"Lying figure-4 contract-relax","steps":["Lie on your back in the figure-4 stretch (right ankle on left knee, pull left thigh in).","Put your right hand on your right knee and gently push the knee into your hand at about 20-30% effort for 10 sec.","Relax for 3 breaths, then pull your thigh in a little deeper. Repeat 3 times, then switch."],"feel":"bum of the crossed leg","dont":null,"hold":"3 x 10 sec/side"}],"notes":[]}]},{"dow":"Saturday","title":"Skills + test day","flow":"Warm-up → Skill practice → Full-body flow → Test","sections":[{"kind":"strength","title":"SKILL PRACTICE","meta":"about 15-20 min. Counts are for the whole session, rest as long as you need between tries.","items":[{"name":"Freestanding handstand kick-up","steps":["Hands on the floor in open space, a wall within reach behind you if you have one.","Kick up softly with a straight leg and aim to balance over your hands.","Hold what you can, then step down or cartwheel out.","Can't yet? Back-to-wall holds, easing one heel off the wall at a time."],"feel":"shoulders, balance, core","dont":"kick past the balance point","sets":"10 attempts total, aim for 15 sec"},{"name":"Crane pose (straight-arm crow)","steps":["Start in crow with your knees high on your upper arms.","Slowly straighten your arms as you shift your hips up and back.","Hold, then lower with control.","Can't yet? Hold crow and straighten your arms a little more each week."],"feel":"arms, core, wrists","dont":"let your head drop forward","sets":"5 x up to 20 sec"},{"name":"Press to handstand attempt","steps":["Straddle or pike stance, hands on the floor.","Shift your shoulders forward and lift your hips over your hands with straight arms.","Stack into a handstand, hold, lower with control.","Can't yet? Wall-assisted press to handstand."],"feel":"shoulders, core, hips","dont":"jump instead of press","sets":"8 attempts total"},{"name":"Handstand walk (steps)","steps":["Kick up to a freestanding handstand.","Shift weight to one hand and take a small step with the other.","Walk as many steps as you can, then come down safely.","Can't yet? Shoulder taps in a chest-to-wall handstand."],"feel":"shoulders, balance, core","dont":"rush your steps","sets":"8 attempts total"},{"name":"Pull-up","steps":["Hang overhand, hands just wider than your shoulders, shoulders pulled down.","Pull your elbows down toward your ribs until your chin clears the bar.","Lower with control all the way to a straight-arm hang.","Can't yet? Band-assisted pull-ups, or slow negatives."],"feel":"lats, upper back, arms","dont":"kick or swing","sets":"3 easy sets of half your best"}],"notes":["Skills first while you are fresh. Warm up wrists and shoulders. Clear floor space, wall within reach, and know your cartwheel exit."],"bw":true},{"kind":"stretch","title":"STRETCH: FULL-BODY FLOW","meta":"about 30 min","items":[{"name":"Pigeon pose (floor)","steps":["From hands and knees, bring one knee forward behind your wrist and slide the back leg long.","Square your hips and fold forward over the front shin.","Hold, then switch."],"feel":"outer hip of the front leg","dont":null,"hold":"3 min"},{"name":"Half split (hands on the floor)","steps":["From a low lunge, shift your hips back and straighten the front leg, toes up.","Fold over the front leg with a flat back, hands on the floor.","Hold, then switch."],"feel":"back of the front thigh","dont":null,"hold":"3 min"},{"name":"Seated straddle fold (floor)","steps":["Sit with legs wide and straight, toes up.","Walk your hands forward with a long back.","Hold."],"feel":"inner thighs, hamstrings","dont":null,"hold":"3 min"},{"name":"Frog stretch (floor)","steps":["On hands and knees, widen your knees as far as is comfortable, feet turned out.","Lower to your forearms and rock your hips back.","Hold."],"feel":"inner thighs and groin","dont":null,"hold":"3 min"},{"name":"Thread-the-needle (each side)","steps":["Get on hands and knees.","Slide your right arm under your body along the floor to the left, palm up.","Lower your right shoulder and ear to the floor. Hold, then switch."],"feel":"upper back and back of shoulder","dont":null,"hold":"3 min"},{"name":"Deep squat hold (floor)","steps":["Feet shoulder-width or wider, toes slightly out.","Sink into a deep squat with heels down, elbows pressing your knees out, chest tall.","Hold."],"feel":"hips, ankles, groin","dont":null,"hold":"3 min"},{"name":"Camel pose","steps":["Kneel hip-width apart, hands on your lower back.","Push your hips forward, lift your chest, let your head drop back gently.","Reach for your heels if you can. Hold."],"feel":"front of body, hip flexors","dont":null,"hold":"90 sec"},{"name":"Bow pose","steps":["Lie face down, bend your knees, reach back and hold your ankles.","Kick your feet into your hands to lift your chest and thighs off the floor.","Hold, breathing slowly."],"feel":"front of thighs, chest, back","dont":null,"hold":"90 sec"},{"name":"Dancer pose (standing bow)","steps":["Stand on one leg, hold the other ankle behind you.","Kick your foot back into your hand while your torso tilts forward, free arm reaching ahead.","Hold, hips square, then switch."],"feel":"front of thigh and hip, balance","dont":null,"hold":"60 sec/side"},{"name":"Full bridge hold","steps":["Lie on your back, feet flat near your bum, hands by your ears with fingers toward your shoulders.","Push up through hands and feet into a full bridge, arms as straight as you can.","Push your chest toward the wall behind your hands. Hold, then lower gently by tucking your chin."],"feel":"shoulders, whole front of body opening","dont":null,"hold":"3 x 45 sec"}],"notes":[]},{"kind":"test","title":"Test","meta":"write these down","items":["Fingers to toes in a fold (cm away, or past)","Front split: hips from floor (cm)","Middle split: hips from floor (cm)","Deep squat hold time","Full bridge hold time","Handstand: longest clean hold in seconds (wall or freestanding)"],"notes":["If these improve month to month, it's working."]}]},{"dow":"Sunday","title":"Rest","flow":"Warm-up (3 min) → Restorative stretch","sections":[{"kind":"stretch","title":"SUNDAY: REST","meta":"restorative stretch, 10-15 min, no pushing","items":[{"name":"Child's pose","steps":["Kneel, big toes together, knees apart. Sit back on heels, arms forward, forehead down."],"feel":null,"dont":null,"hold":"2 min"},{"name":"Supine twist","steps":["Lie on your back, knees bent, arms out to the sides.","Let both knees fall to one side.","Keep both shoulders on the floor, look the other way. Hold, then switch."],"feel":"lower back and side of hip","dont":null,"hold":"1 min/side"},{"name":"Happy baby","steps":["Lie on your back, hold the outsides of your feet with knees wide.","Draw your knees toward your armpits and rock gently.","Hold."],"feel":"hips and lower back","dont":null,"hold":"2 min"},{"name":"Slow breathing","steps":["Lie down. Breathe in 4 sec, out 6 sec."],"feel":null,"dont":null,"hold":"2 min"}],"notes":[]}]}]}]`),t=[{name:"March in place",amount:"1 min",steps:["Lift knees to hip height, swing arms, steady pace."]},{name:"Hip circles",amount:"10 each way",steps:["Hands on hips, draw big slow circles with your hips. 10 one way, 10 the other."]},{name:"Cat-cow",amount:"10",steps:["On hands and knees: drop belly and lift chest (cow), then round back up (cat)."]},{name:"Deep squat hold",amount:"30 sec",steps:["Sit as low as you can, heels down, elbows push knees out."]},{name:"Glute bridge",amount:"10",steps:["On back, knees bent, lift hips and squeeze bum, lower."]},{name:"Leg swings",amount:"10 each leg, each direction",steps:["Hold a wall. Swing one leg forward and back 10, then side to side across your body 10. Switch."]}],o=JSON.parse(`{"tagline":"Big round bum · Wider hips · Snatched waist · Shapely thighs · Real flexibility","howto":["There are 14 plans. Plans 1-6 use dumbbells and a barbell. Plans 7-14 drop the weights: bodyweight on a clear floor plus a small travel kit: a pull-up bar (doorway or park), resistance bands, ankle weights and parallettes. A wall is used only as a spotter for handstands.","Each plan is a full week, one day per page. Do the page for today, top to bottom: warm-up, strength, then stretch.","Move up to the next plan when the current one feels easy. After Plan 6 you drop the weights and start Plan 7.","Every day uses the same 5-min warm-up (below). Stretching always comes straight after the workout or row.","The rules and stretching rules are on the next page. Extra reference (level-up ladders, rowing notes, splits ladder, tracking) is at the back.","There's a blank Weight column next to every exercise. Write in what you used so you know what to beat next time."],"warmupNote":"Never stretch cold. On row days, the row is your warm-up. On Sunday, do 3 min of this first.","training":[{"t":"Progress","b":"Weighted moves: when you get all the reps on every set with good form, go up in weight next time (smallest jump you can). Bodyweight moves: once you hit the top of the reps, make it harder (slower lowering, a pause, 1.5 reps, then the next version) rather than adding more reps."},{"t":"Don't go to failure","b":"Stop 1-2 reps before failure. Muscle burn is good. Sharp or joint pain means go back a step."},{"t":"Control the weight","b":"Lower for 2-3 sec, squeeze 1-2 sec at the top. Controlled reps grow more muscle than heavy sloppy ones."},{"t":"Easy week","b":"Every 4th week the app lightens everything for you automatically: one fewer set on each move, stretch holds about 25% shorter, and no contract-relax. Just follow what it shows. The Today screen tells you when the next one is coming."},{"t":"Cardio (Plans 1-6)","b":"Tue and Sat are Concept2 days, followed by stretching. Fat loss comes from the rowing, your 4 strength days, and a modest calorie deficit. Spin bike swap is in the rowing notes. Plans 7-14 have no cardio: Tuesday is jumps and balance, Saturday is skills, stretching and your test, and food does the fat-loss work."},{"t":"Eat to grow and lose","b":"Protein at every meal (roughly 100-140 g a day for most people your size), plenty of veg, and a modest deficit of about 0.5-1 kg (1-2 lb) a week. Crash dieting stalls glute growth."},{"t":"Sleep","b":"7-9 hours. Muscle grows while you rest."},{"t":"Doctor","b":"If you've been inactive or have a medical condition, check with a doctor first."},{"t":"Bodyweight plans (7-14)","b":"No weights, so effort does the work. Studies find light loads grow muscle about as well as heavy ones when sets end close to failure. Stop 1-2 reps before failure. When every set hits the top of the rep range, slow the lowering to 3-5 sec, add a pause, then move to the harder version. Bands and ankle weights are your load: when the top of the reps gets easy, go up a band or add ankle weight first, then slow the reps down."},{"t":"Stretch dose (all plans)","b":"Weekly total time per area and how often you stretch matter more than one huge hold. Aim for roughly 5-10 min per week on each area you want to open, spread over 3+ days. Holds of 1-3 min are plenty. Contract-relax works as well as plain static."},{"t":"Glute and thigh growth rules (Plans 7-14)","b":"Research points to about 10-25 hard sets per muscle per week, trained 2-6 times, covering bridges, squats and lunges, and side-hip work. These plans keep every move at 3-4 sets of 20 reps or fewer. Without weights, glute growth is slower than in Plans 1-6, so make every rep count: slow lowering, a hard squeeze at the top, and stop 1-2 reps before failure. Your glutes grow best when they're worked hard in their deepest stretch, so the forward-lean split squats, curtsy pulses and deep reverse lunges are your best glute builders without weights. Own those pauses at the bottom."},{"t":"Realistic timeline (Plans 7-14)","b":"About 6-8 weeks per plan, so roughly 12-15 months in total. Handstand push-ups, one-arm push-ups and tuck planche each take most women 6-12 months or more, so the plans climb them in small steps. How toned you look also depends on food and sleep."},{"t":"Skill rules (Plans 7-14)","b":"Floor, a pull-up bar, bands, ankle weights and parallettes, plus a wall as a spotter. Parallettes are kinder to your wrists for L-sits and planche work. Order for handstand push-ups: wrist prep, pike push-ups, chest-to-wall hold, wall negatives, short range, then full range. Pull-ups: dead hang, scapular pulls, slow negatives, then full reps. Move on only when the step feels controlled, and use the \\"Can't yet?\\" option on any move you're not ready for. Stop if your neck, wrists or shoulders hurt."}],"kitTitle":"Plans 1-6: 2 short dumbbell handles + 1 long barbell + plates","kit":[{"t":"Choosing weight","b":"Pick a weight where the last 2 reps of each set are hard but your form stays clean (you could do 1-2 more). Write it in the Weight column."},{"t":"What goes heavy","b":"Glutes are strong: hip thrusts, glute bridges and Romanian deadlifts take the heaviest weight (barbell). Lunges, split squats and single-leg moves take much lighter dumbbells. Upper body = light."},{"t":"Warm-up sets","b":"Before your first weighted move each day, do 1-2 lighter sets of 8 to warm up."},{"t":"Safety","b":"Always put the collars on. Wrap a towel or yoga mat around the bar for hip thrusts and bridges."},{"t":"Small plates?","b":"If your plates are too small to roll the bar over your hips, sit down and lift the bar onto your hips, or use a heavy dumbbell across your hips instead."},{"t":"Set-up","b":"No rack needed. The couch is your bench. Also used: wall, chair, stair, towel, a thin book or plate for heel lifts."}],"stretching":[{"t":"How hard","b":"Stretch to mild tension (about 5-6 out of 10). Breathe slowly. Never bounce. Sharp pain, pinching in a joint, or tingling/numbness = back off."},{"t":"Rounds","b":"Do 2 rounds of each stretch, 3 when you have time."},{"t":"Contract-relax","b":"At the end of a hold, gently push into the floor or your hands at about 20-30% effort for 5-10 sec. Relax for 3 breaths, then sink a little deeper. Repeat 3 times. Fastest way to gain range. (Plan 1: Saturday only from month 2. Plans 2-3: hips and hamstrings. Plans 4-6: everything.)"},{"t":"When","b":"Mon, Thu, Fri: right after your workout. Tue and Sat: right after your row. Sun: after a 3-min warm-up."},{"t":"Support","b":"Pillows, books and couch cushions are allowed. Lower the support slowly (see splits ladder at the back)."},{"t":"Joint care","b":"Knees or hips pinchy in kneeling or pigeon? Cushion under the knees or switch to lying figure-4 versions."}],"ladders":[["Squat","Goblet squat to chair → goblet squat 3 sec down → heel-elevated goblet · Split: dumbbell lunge → dumbbell Bulgarian → heavier → 1.5 reps"],["Hip thrust","Dumbbell glute bridge → barbell hip thrust → heavier barbell → pauses / 1.5 reps → B-stance barbell → single-leg dumbbell thrust → feet-elevated single-leg"],["Hinge","Dumbbell Romanian deadlift → barbell Romanian deadlift → heavier → 3 sec lowering · Single-leg: wall → free → heavier → slow"],["Hamstring","Bridge march → slider curl → single-leg slider curl → Nordic lower"],["Push-up","Wall → counter → low incline → knees → full → 3 sec lowering"],["Core","Dead bug → plank (knees, then full) → side plank → hollow hold → hollow rocks"],["Side glutes","Fire hydrant → hydrant with pulses → hydrant + kick combo → side plank leg lift (knee) → (feet) → 3 sec hold"],["Single-leg squat","Skater (wall) → goblet skater (dumbbell) → goblet skater no support → shrimp → assisted pistol → pistol"],["Adding weight","Smallest jump you can (e.g. 1.25-2.5 kg on the barbell, 1-2 kg on a dumbbell). Stuck? Slow the reps down or add a pause instead."]],"flex":[["Plan 1","30-60 sec","2","Learn the shapes, no contract-relax yet","Sit cross-legged comfortably, hands reach toes or shins in a fold"],["Plan 2","60-90 sec","2-3","Contract-relax on hips and hamstrings","Straddle fold with a flat back, half split hands on the floor, bridge prep 10 sec"],["Plan 3","2-3 min","2-3","Lower split supports, active leg holds","Dance-ready hips, high controlled leg lifts, strong bridge"],["Plan 4","2-3 min","2-3","Contract-relax on everything, active holds","Splits with one support, full bridge 15 sec"],["Plan 5","2-3 min","3","Supports almost gone, active holds 8-10 sec","Front split hips near floor, pancake chest heading down"],["Plan 6","3 min","3","Full splits work, active holds 10 sec","Full splits (or as close as your hips allow), full bridge 30 sec"],["Plan 7","1-3 min","1-2","Hands-on-floor splits, contract-relax on everything","Front split hands on the floor, bridge 30 sec"],["Plan 8","1-3 min","1-2","Wrist prep, first hands-off split holds, camel","Front split hands off briefly, bridge 40 sec"],["Plan 9","1-3 min","1-2","Active lift-offs, bow, bridge walk-ins, needle scale","Splits hands off the floor"],["Plan 10","1-3 min","1-2","Active lift-offs 10 sec, deep backbends","Full splits (or close), bridge 45 sec"],["Plan 11","1-3 min","1-2","Dancer pose, lift-offs 15 sec","Dancer pose 45 sec"],["Plan 12","1-3 min","1-2","One-leg bridge, lift-offs 20 sec","Dancer pose 60 sec, bridge with one leg lifted"],["Plan 13","1-3 min","1-2","Bridge walk-ins 40 sec, lift-offs 8 x 15 sec","Bridge walk-in 40 sec"],["Plan 14","1-3 min","1-2","Needle scale, dancer pose 90 sec, lift-offs 8 x 20 sec","Full splits (or close), dancer pose 90 sec"]],"rowing":[{"t":"Damper","b":"Damper 3-5 is plenty. Higher just means a heavier pull on your back, not a better workout."},{"t":"First 2 weeks","b":"Use the first 2 weeks to get back into your rhythm and find your pace. Lower back or knees feel off? Shorten the session."},{"t":"Bulk","b":"Moderate rowing won't bulk your upper body. It builds endurance and a bit of back tone, not big arms or shoulders."},{"t":"Spin bike swap","b":"Keep the same times and rounds. Steady = low-to-moderate resistance at 70-90 rpm. Intervals = 3 min harder (add a little resistance) / 1 min easy. Seat height: knee slightly bent at the bottom of the pedal stroke."}],"splits":["Hands on a stack of books or pillows beside you, with a pillow under your hips if needed.","Every 2 weeks, remove one book or pillow when you can hold 60 sec without strain.","Keep the front leg and back leg straight, hips square. Sink slowly with each exhale.","Don't rush. If a stretch feels sharp, go back one step and hold longer there."],"splitsNote":"Most people get dramatically more flexible in 6 months, and many reach splits. A few are limited by hip structure, which is fine. Go as far as your body allows without pain. A physio or dance teacher can check your form.","why":[{"t":"Big, round glutes","b":"Barbell hip thrusts and Romanian deadlifts are the two best glute builders, and you add weight to them over time. Plus split squats and lunges, 3x a week."},{"t":"Wider, fuller hips","b":"Glute medius/minimus (side glutes) and outer thighs: fire hydrants, side-lying raises, curtsy and lateral lunges, Cossack squats. They add the \\"shelf\\" look. You can't change bone structure, but muscle plus fat loss around the waist changes proportions a lot."},{"t":"Strong thighs","b":"Quads, hamstrings and inner thighs through single-leg work, holds and tempo."},{"t":"Balanced torso","b":"Upper body once a week. Plans 1-6 keep it light and posture-focused. Plans 7-14 add handstand and planche skills: these mostly build the front of your shoulders and your triceps, not the side of the shoulder that adds width, and the volume stays low. Floor back work every Wednesday keeps your shoulders back so they look open, not broad. Side planks and hollow holds tighten the waist without thickening it."}],"dance":["Hold a single-leg balance for 30 sec each side, eyes closed","Do 10 clean curtsy lunges and 8 skater squats per side","Sit in a deep squat for 90 sec","Half split with hands on the floor, and a straddle fold with a flat back","Complete all 4 strength days each week with good form and no joint pain","Row 35 min steady without back or knee pain"],"danceNote":"Then pick a beginner style you love (jazz, contemporary, hip-hop, heels) and start. Keep going with Plan 4.","top":["Pistol squat (holding a door frame) 5 per side","Barbell hip thrust for 10 reps with a weight that felt impossible in Plan 2","Hold a star side plank 20 sec each side","Front and middle split as low as your hips allow, hands free","Hold a full bridge for 30 sec","Hold your leg up in front and to the side for 10 sec with no hands"],"track":[{"t":"Every week","b":"Log your top set for each key move."},{"t":"Every 4 weeks","b":"Take a photo and measure waist, hips and thighs (the scale lies day to day)."},{"t":"Working?","b":"Numbers going up and hips measuring bigger relative to your waist = it's working."}],"goddess":["Pistol squat, no support, 8 per leg with a 5 sec lowering","Long-lever single-leg bridge, 18 per leg","Wall handstand push-up (short range), 5 reps","Chest-to-wall handstand 40 sec and L-sit 30 sec","Front and middle splits, hands off the floor (or as close as your hips allow)","Full bridge 45 sec, then walk your hands toward your feet","5 strict pull-ups"],"apex":["Wall handstand push-up, full range, 8 reps","Freestanding handstand 15 sec and a handstand walk of 5 steps","One-arm push-up, feet wide, 4 per side","Advanced tuck planche 8 sec","Pistol squat with a 5 sec lowering, 12 per leg","Full front and middle splits, hands off the floor (or as close as your hips allow)","V-sit 45 sec","Dancer pose 90 sec each side","10 strict pull-ups and a 15 sec advanced tuck front lever"],"laddersBW":[["Single-leg bridge","Single-leg bridge → long-lever → 1.5 reps → hold → walkout"],["Stretched glutes","Forward-lean split squat → slow lowering + pauses → 1.5 reps · Deep curtsy pulses → longer holds at the bottom · Deep reverse lunge → slower lowering"],["Single-leg squat","Partial pistol → skater squat → shrimp → pistol → slow pistol"],["Quads","Reverse lunge → jump lunge → reverse Nordic curl"],["Handstand push-up","Pike push-up → chest-to-wall hold → wall negative → short range → full range"],["Horizontal push","Push-up → archer → pseudo planche → one-arm negative → one-arm push-up"],["Planche","Pseudo planche → tuck planche → advanced tuck planche"],["Core","Hollow rocks → L-sit → V-sit"],["Handstand skills","Wall hold → kick-up → press attempts → freestanding → handstand walk"],["Arm balances","Crow → side crow → crane"],["Splits and backbends","Hands on floor → hands off → active lift-offs · Bridge → camel / bow → walk-in → one-leg bridge"],["Pull-up","Dead hang → scapular pulls → slow negatives → first pull-up → 8-10 pull-ups → archer pull-ups"],["Front lever","Tuck → advanced tuck"],["Hanging core","Knee raises → straight-leg raises → toes-to-bar"],["Posture","Reverse snow angel → Y-T-W raise → slower reps and longer squeezes"],["Bands and ankle weights","Light band → medium → heavy · Mini band above knees → at ankles → around feet · Ankle weights: lightest first, add only when 12 clean reps feel easy"]],"kitBW":[{"t":"Pull-up bar","b":"A doorway bar at home, or any park bar. Check it's solid before every session and never jump to grab it. Muscle-ups later need a park bar with space above it."},{"t":"Resistance bands","b":"Long loop bands in light, medium and heavy for banded bridges, frog pumps, pull-aparts and assisted pull-ups, plus mini loop bands for lateral walks. Go up a band when the top of the reps feels easy."},{"t":"Ankle weights","b":"An adjustable pair, starting light (about 0.5-1 kg each). Used on hydrants, donkey kicks, side planks, hip extensions, inner-thigh lifts and, from Plan 12, your active leg holds. Add weight only when 12 clean reps feel easy."},{"t":"Parallettes","b":"A low pair for L-sits, V-sits, planche work and pike push-ups. Kinder to your wrists than the floor."},{"t":"Everything else","b":"A clear floor, a wall to spot your handstands, and something soft under your knees."}]}`),s={plans:e,warmup:t,ref:o};export{s as D};
